    t[191092] = { name = "Бивень Он'тука", fen = "A surprisingly light, yet sturdy material the Tuskarr use for many of their buildings.", fua = "Напрочуд легкий, але міцний матеріал, який тускари використовують для багатьох своїх будівель." }
