    t[191118] = { name = "Тотем Карґлапи", fen = "Kargpaw's totem drips with an unnatural and endless fetid ooze that decays anything it touches. The nauseating stench is unbearable.", fua = "Тотем Карґлапи стікає неприродним нескінченним смердючим слизом, що роз'їдає все, чого торкається. Нудотний сморід нестерпний." }
