    t[191623] = "Нестабільний Пояс Льодополум'я"
    t[191633] = { name = "Скалка Кристалізованої Мани", fen = "This crystal sings to you, and in its song you can hear ancient words telling stories of ancient times. Lathos may be interested in it.", fua = "Цей кристал співає до вас, і в його пісні ви чуєте прадавні слова, що розповідають історії прадавніх часів. Лейтос міг би цим зацікавитися." }
    t[191667] = { name = "Старий Ключ", fen = "Seems mostly intact.", fua = "Здається переважно цілим." }
    t[191668] = { name = "Різьблений Кам'яний Кит", fen = "The tail flukes of a lobtailing whale, this carving symbolizes renewal. The edges of the tail were gnawed by large, sharp incisors.", fua = "Хвостові лопаті кита, що б'є хвостом по воді; це різьблення символізує оновлення. Краї хвоста обгризли великі гострі різці." }
    t[191669] = { name = "Гравірований Бивень", fen = "A delicately decorated mammoth tusk, honoring one that provides. Coated with congealed, still damp slobber.", fua = "Витончено оздоблений бивень мамонта на честь того, хто дарує. Вкритий загуслою, ще вологою слиною." }
    t[191670] = { name = "Перстень із Намистинками й Пір'ям", fen = "Eagle feathers woven with beads and leather string, symbolizing sound judgment. Teeth marks are evident in the leather and several beads are broken.", fua = "Орлине пір'я, переплетене намистинками й шкіряним шнурком, символізує тверезість суджень. На шкірі видно сліди зубів, а кілька намистинок поламано." }
    t[191671] = { name = "Розколоте Зображення Таскара", fen = "A well-worn bone effigy of a tuskarr's honored ancestor. Heavily gnawed in the middle.", fua = "Зужите кісткове зображення шанованого предка таскарів. Сильно обгризене посередині." }
    t[191672] = { name = "Знак Годувальника", fen = "An expertly carved bone totem, representing a successful tuskarr fisherman. Deep tooth marks have created cracks in the bone.", fua = "Майстерно вирізьблений тотем із кістки на честь успішного рибалки-таскара. Глибокі сліди зубів утворили тріщини в кістці." }
    t[191673] = { name = "Фетиш Вищиреного Дельфіна", fen = "The long toothy skull of a dolphin, symbolizing leadership. Chipped in several places from being chewed on.", fua = "Видовжений зубатий череп дельфіна, що символізує провідництво. Подекуди надщерблений від обгризання." }
    t[191676] = { name = "Концентрована Сутність Води", fen = "This magical concentrate has been placed in a container perfect for throwing at unruly fire elementals.", fua = "Цей магічний концентрат вміщено в посудину, ідеальну для жбурляння в непокірних вогняних елементалів." }
    t[191681] = { name = "Бездо-ДЗЬОБ-на Машкара Верескокрила", fen = "Made to stop Screechflight harpies from wanting to murder you on sight! Patent Pending!", fua = "Створено, щоб гарпії-верескокрили не прагнули вбити вас одразу ж! Патент очікується!" }
