    t[191855] = { name = "Трофей Каляші", fen = "Smoldering with latent fire, this roughly hewn lava rock is used by Qalashi casters to concentrate the power of their spells.", fua = "Тліючи прихованим вогнем, цей грубо витесаний камінь із лави слугує чаклунам каляші, щоб зосереджувати міць своїх заклять." }
    t[191856] = "Зміцнена Волосінь з Гаком"
    t[191857] = { name = "Річкова Риба Теплих Вод", fen = "Unpleasantly warm to the touch, but seems good to eat all the same.", fua = "Неприємно тепла на дотик, але все одно начебто придатна до їжі." }
    t[191858] = { name = "Соковите М'ясо Луціана", fen = "Despite scorch marks on the crab's shell, the meat inside smells sweet and almost buttery.", fua = "Попри сліди підпалу на панцирі краба, м'ясо всередині пахне солодко й майже масляно." }
    t[191859] = { name = "Напівварена Риба", fen = "The scales and meat flake off in your hands. The fish appears to be cooked through in places.", fua = "Луска й м'ясо відпадають просто в руках. Місцями риба наче проварена наскрізь." }
    t[191861] = { name = "Панцир Рокопада", fen = "Crunchy. Gross. It's a dead bug.", fua = "Хрумкий. Огидний. Це дохла комаха." }
    t[191862] = { name = "Уламок Китової Кістки", fen = "Sturdy and pliable, these bones are the favored materials of tuskarr crafters.", fua = "Міцні й гнучкі, ці кістки — улюблений матеріал майстрів-таскарів." }
    t[191863] = { name = "Просякнуте Водою Дерево", fen = "Drenched but in good condition aside from a few splinters.", fua = "Геть промокле, але, окрім кількох скалок, у доброму стані." }
