    t[192743] = { name = "Дикий Кущоплід", fen = "A cool burst of mint and the perfect amount of crunch.", fua = "Прохолодний сплеск м'яти й ідеальна хрумкість." }
    t[192744] = { name = "Дарунок Римека", fen = "Dynamic, but very cold, gemstones.", fua = "Жваві, та вельми холодні самоцвіти." }
    t[192745] = { name = "Титанічна Комедія", fen = "A satirical tour of the cosmos, from the Emerald Dream to the Shadowlands, led by the titan watcher Dantyr. Neither titans nor aspects are spared the author's ire, all having their perceived sins on full display.", fua = "Сатирична мандрівка космосом, від Смарагдового Сну до Темних Земель, на чолі з титанічним вартовим Дантіром. Ні титани, ні аспекти не уникають авторського гніву, і всі їхні гадані гріхи виставлені напоказ." }
    t[192746] = { name = "Дивовижа Минувшини", fen = "An unrecognizable vestige of a time long past.", fua = "Невпізнаваний слід давно минулих часів." }
    t[192747] = "Зламана Гілка"
    t[192749] = "Хронокристал"
    t[192750] = "Чорнозалізний Дротик"
    t[192751] = { name = "Бруффалон Грозового Дотику", fen = "Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location.", fua = "Навчає викликати цей засіб пересування. Цей засіб пересування змінюється залежно від вашої навички верхової їзди та місцезнаходження." }
    t[192752] = { name = "Навершя Посоха", fen = "The detached focus from a broken Timewalker staff.", fua = "Відокремлений фокус зламаного посоха мандрівника часу." }
    t[192753] = { name = "Луска Гніву", fen = "A savagely poignant rebuttal of the order imposed by the aspects and their titan allies. Told from the point of view of a protodrake who would eventually feel forced to rebel after being pushed to the edges of draconic society.", fua = "Нещадно гостре заперечення порядку, накинутого аспектами та їхніми титанічними союзниками. Розповідь ведеться від імені протодракона, який зрештою змушений був повстати після того, як його витіснили на узбіччя драконячого суспільства." }
    t[192754] = { name = "Дракіхот", fen = "The story of an ancient green dragon who could no longer tell his dreams from the waking world. Accompanied by a long suffering dragonspawn, Dracuixote embarks on a fanciful quest to restore an imagined golden age.", fua = "Історія прадавнього зеленого дракона, який більше не міг відрізнити свої сни від дійсності. У супроводі багатостраждального драконича Дракіхот вирушає у химерну виправу, щоб повернути уявний золотий вік." }
    t[192755] = { name = "Володар Крил", fen = "A band of hardened drakonid and plucky whelps come together to destroy an artifact of terrible power that can only be undone in the forges of the mad aspect who created it.", fua = "Загартовані драконіди й завзяті дракончики об'єднуються, щоб знищити артефакт жахливої сили, який можна зруйнувати лише в кузнях божевільного аспекта, котрий його створив." }
    t[192756] = { name = "Червоний і Чорний Роди", fen = "A low-born black drake fails to reconcile his militaristic heritage with his respect for intelligence and wit, eventually falling to despair over unrequited love and the materialism rampant among dragonkind.", fua = "Чорний дракон низького роду не може примирити свою войовничу спадщину з повагою до розуму й дотепності, і зрештою впадає у відчай через нерозділене кохання та жадобу до речей, що буяє серед драконів." }
    t[192757] = { name = "Гордість і Протодракони", fen = "The quintessential love story. Set in a time before the aspects, an up-and-coming young protodrake runs afoul of a standoffish elder. Their animosity turns to appreciation and, eventually, love as they come to understand each other.", fua = "Найдосконаліша історія кохання. У часи до постання аспектів молодий завзятий протодракон стикається з відлюдкуватим старійшиною. Їхня ворожнеча обертається на повагу, а згодом і на любов, коли вони починають розуміти одне одного." }
    t[192758] = { name = "Моток Важкої Линви", fen = "Heavy as defined by dragonkin. You could likely haul boulders with a single coil.", fua = "Важка за мірками драконів. Однієї бухти, либонь, вистачить, щоб тягати валуни." }
    t[192759] = { name = "Спис Магмової Присяги", fen = "Point towards enemy and strongly apply jabbing motion.", fua = "Спрямуйте на ворога й сильно вдарте колючим рухом." }
