    t[193255] = { name = "Бездоганний Ріг Воркіна", fen = "A rare, species-specific material gathered from Vorquin by players with the Skinning skill. Can be bought and sold on the auction house.", fua = "Рідкісний, видоспецифічний матеріал, що його здобувають із воркінів гравці з умінням шкуродерства. Можна купувати й продавати на аукціоні." }
    t[193256] = { name = "Вітроспівне Пір'я", fen = "A rare, species-specific material gathered from ohuna by players with the Skinning skill. Can be bought and sold on the auction house.", fua = "Рідкісний, видоспецифічний матеріал, що його здобувають з огун гравці з умінням шкуродерства. Можна купувати й продавати на аукціоні." }
    t[193258] = { name = "Сповнена Вогню Шкура", fen = "A rare, species-specific material gathered from fiery creatures by players with the Skinning skill. Can be bought and sold on the auction house.", fua = "Рідкісний, видоспецифічний матеріал, що його здобувають з вогняних істот гравці з умінням шкуродерства. Можна купувати й продавати на аукціоні." }
    t[193259] = { name = "Бездоганна Луска Протодракона", fen = "A rare, species-specific material gathered from Proto Dragons by players with the Skinning skill. Can be bought and sold on the auction house.", fua = "Рідкісний, видоспецифічний матеріал, що його здобувають із протодраконів гравці з умінням шкуродерства. Можна купувати й продавати на аукціоні." }
    t[193260] = { name = "Дорогоцінний Самоцвіт", fen = "Precious as it may be, this fragile gem crumbles at the slightest touch. Whoever offered this to you must truly value your companionship.", fua = "Хоч який він цінний, цей крихкий самоцвіт розсипається від найменшого дотику. Той, хто подарував його вам, певно, справді цінує вашу дружбу." }
    t[193261] = { name = "Шматочок на Один Укус", fen = "Gathered by Skinners specialized in Lure Crafting. Can be bought and sold on the auction house.", fua = "Здобувається шкуродерами, що спеціалізуються на виготовленні принад. Можна купувати й продавати на аукціоні." }
    t[193262] = { name = "Винятковий Шматочок", fen = "Gathered by Skinners specialized in Lure Crafting. Can be bought and sold on the auction house.", fua = "Здобувається шкуродерами, що спеціалізуються на виготовленні принад. Можна купувати й продавати на аукціоні." }
    t[193355] = { name = "Карта Руїн Нелтазана", fen = "This map lays out the ruins in sections separated by their estimated age. A symbol of the Destroyer is scrawled in the margins.", fua = "Ця карта зображує руїни, поділені на ділянки за приблизним віком. На полях нашкрябано символ Руйнівника." }
    t[193357] = { name = "Розбита Оздоба", fen = "Sundered by the Sundered Flame. Precisely what Adenedal feared.", fua = "Розколота Розколотою Полум'ям. Саме те, чого боявся Аденедал." }
    t[193360] = { name = "Трофейне Намисто Кентавра", fen = "A decorative necklace to show one's prowess while hunting as a group. Received rarely when participating in Centaur Hunts.", fua = "Декоративне намисто на знак вправності в груповому полюванні. Рідкісна нагорода за участь у Кентаврських Ловах." }
    t[193362] = { name = "Вогняна Душа", fen = "A smoldering soul captured from a powerful elemental foe with a Zapthrottle Soul Inhaler, crafted by Engineers.", fua = "Тліюча душа, вихоплена в могутнього стихійного ворога Душовловлювачем Зептротла, що його створюють інженери." }
    t[193365] = { name = "Базове Алхімічне Експериментування зі Зіллями", fen = "Experiment with volatile reagents in hopes of discovering new potion recipes.", fua = "Експериментуйте з нестабільними реагентами в надії відкрити нові рецепти зілль." }
    t[193366] = { name = "Поглиблене Алхімічне Експериментування з Флаконами", fen = "Experiment with volatile reagents in hopes of discovering new phial recipes.", fua = "Експериментуйте з нестійкими реагентами в надії відкрити нові рецепти флаконів." }
    t[193367] = { name = "Поглиблене Алхімічне Експериментування зі Зіллями", fen = "Experiment with volatile reagents in hopes of discovering new potion recipes.", fua = "Експериментуйте з нестабільними реагентами в надії відкрити нові рецепти зілль." }
    t[193368] = { name = "Шовковистий Самоцвітний Пил", fen = "Acquired by Jewelcrafters by crushing gems from the Dragon Isles. Can be bought and sold on the auction house.", fua = "Здобувається ювелірами шляхом подрібнення самоцвітів Драконових Островів. Можна купувати й продавати на аукціоні." }
    t[193369] = { name = "Шовковистий Самоцвітний Пил", fen = "Acquired by Jewelcrafters by crushing gems from the Dragon Isles. Can be bought and sold on the auction house.", fua = "Здобувається ювелірами шляхом подрібнення самоцвітів Драконових Островів. Можна купувати й продавати на аукціоні." }
    t[193370] = { name = "Шовковистий Самоцвітний Пил", fen = "Acquired by Jewelcrafters by crushing gems from the Dragon Isles. Can be bought and sold on the auction house.", fua = "Здобувається ювелірами шляхом подрібнення самоцвітів Драконових Островів. Можна купувати й продавати на аукціоні." }
