    t[193375] = { name = "Уламки Артефактів Нелтазана", fen = "These misshapen fragments lay unperturbed for millennia until their most recent upheaval by the Sundered Flame.", fua = "Ці безформні уламки лежали недоторканими тисячоліттями, аж доки їх нещодавно не сколихнула Розколота Полум'я." }
    t[193376] = { name = "Охайний Гаманець Аденедала", fen = "Pristinely kept and neatly folded.", fua = "У бездоганному стані й акуратно складений." }
    t[193378] = { name = "Стихійна Гармонія", fen = "A harmonious union between the gems of the Dragon Isles with Awakened Elements, crafted by jewelcrafters with the assistance of alchemists. Can be bought and sold on the auction house.", fua = "Гармонійне поєднання самоцвітів Драконових Островів із Пробудженими Стихіями, створене ювелірами за допомоги алхіміків. Можна купувати й продавати на аукціоні." }
    t[193379] = { name = "Стихійна Гармонія", fen = "A harmonious union between the gems of the Dragon Isles with Awakened Elements, crafted by jewelcrafters with the assistance of alchemists. Can be bought and sold on the auction house.", fua = "Гармонійне поєднання самоцвітів Драконових Островів із Пробудженими Стихіями, створене ювелірами за допомоги алхіміків. Можна купувати й продавати на аукціоні." }
