    t[193395] = { name = "Пісковий Годинник Мінливих Пісків", fen = "The sands within the hourglass appear to be at a standstill, floating between the walls of the glass chamber, free from disruption.", fua = "Пісок усередині годинника, здається, застиг, ширяючи між скляними стінками камери, вільний від будь-якого збурення." }
    t[193396] = { name = "Зачарована Торба зі Шкіри Мускена", fen = "The enchantment placed upon the locking mechanism appears to be quite simple. However, the curious satchel doesn't appear to have a limit on what can be placed within.", fua = "Чари, накладені на запірний механізм, здаються доволі простими. Однак ця цікава торба, схоже, не має меж тому, що можна в неї покласти." }
    t[193397] = { name = "Ікла Кіракки", fen = "Sharp enough to pierce the toughest of hides.", fua = "Достатньо гострі, щоб пробити найміцнішу шкуру." }
