    t[193401] = { name = "Закривавлений Широкий Пояс зі Шкіри Мускена", fen = "This prized possession has seen many a battle, worn by its previous owner--the late Balakar Khan.", fua = "Ця цінна річ бачила чимало битв на стані свого попереднього власника — покійного Хана Балакара." }
    t[193402] = { name = "Фетиш Декатріархині", fen = "This delicate fetish appears to be in the midst of rotting away.", fua = "Цей тендітний фетиш, схоже, потроху загниває." }
    t[193403] = { name = "Кристалічний Зосереджувач", fen = "This focus seems to be the source of the crystalline growth.", fua = "Цей зосереджувач, схоже, є джерелом кристалічного розростання." }
    t[193404] = { name = "Осердя Водяної Скверни", fen = "The core slightly dissipates when removed from its host.", fua = "Осердя злегка розсіюється, коли його вийняти з носія." }
    t[193405] = { name = "Журнал Директорки", fen = "The cover is titled, 'Students, Teachings, and Studies', though all remaining pages appear to have been ripped from the ledger with great force.", fua = "Обкладинка має назву \"Учні, Навчання та Дослідження\", проте всі решта сторінок, схоже, з великою силою вирвані з журналу." }
