    t[193409] = { name = "Загублена в Часі Дивовижа", fen = "The markings are unrecognizable, or perhaps engraved in a language not yet known...", fua = "Позначки невпізнавані або, можливо, викарбувані мовою, що досі невідома..." }
    t[193410] = "Нудотне Жало"
    t[193411] = { name = "Попелястоскутий Амулет", fen = "Etchings on the back of the stone necklace suggest this is one of many, each with their own emblazoned sigil, still warm to the touch.", fua = "Гравірування на звороті кам'яного амулета вказує, що це один із багатьох, кожен зі своїм карбованим сигілом, і досі теплий на дотик." }
    t[193412] = { name = "Сповнене Первісної Сили Драконяче Яйце", fen = "The life once present within the warmth of the shell has long passed.", fua = "Життя, що колись тепліло в теплі цієї шкаралупи, давно згасло." }
    t[193413] = { name = "Перо Небесної Матері", fen = "A touch of the feather upon the skin is enough to guide a thousand spirits to safer realms.", fua = "Дотику пера до шкіри досить, щоб провести тисячу духів до безпечніших світів." }
    t[193414] = { name = "Старий Шаманський Кинджал", fen = "Although weathered and worn, this dagger does not appear to have seen much combat.", fua = "Хоч вивітрений і потертий, цей кинджал, схоже, мало бачив боїв." }
    t[193415] = { name = "Записи Синдрагоси", fen = "A series of detailed notes and observations about Umbrelskul's condition.", fua = "Низка детальних нотаток і спостережень про стан Умбрелскула." }
    t[193416] = { name = "Голографічний Розподільник", fen = "One side of the strange, spherical device appears to house a slot for a key of some kind. Perhaps a security measure, protecting whatever remains within.", fua = "З одного боку дивного кулястого пристрою, схоже, є гніздо для якогось ключа. Можливо, це захисний засіб, що береже все, що лишилося всередині." }
    t[193417] = { name = "Сновидний Вогник Сплутаних Спогадів", fen = "Whispers within the fragile casing call out, but in an unrecognizable, soft-spoken voice.", fua = "Шепіт із крихкої оболонки кличе, та невпізнаваним, лагідним голосом." }
