    t[197744] = { name = "Шмат Горнсвоґа", fen = "A meat from hornswog, which are commonly found across the Dragon Isles near water, caves, or areas with volcanic activity. Can be bought and sold on the auction house.", fua = "М'ясо горнсвоґів, що зазвичай водяться по всіх Драконячих Островах поблизу води, печер чи місць вулканічної активності. Можна купувати й продавати на аукціоні." }
