    t[198070] = { name = "Подерта Морська Лоза", fen = "Fisherman Tinnak was exceptionally good at weaving harpoon ropes, but he went missing a while ago. Last seen in the Upper Frostlands, not far from Camp Antonidas. Bring it to Tavio in Iskaara.", fua = "Рибалка Тіннак був надзвичайно вправний у плетінні гарпунних мотузок, але він зник якийсь час тому. Востаннє його бачили у Верхніх Морозних Землях, неподалік Табору Антонідаса. Віднесіть її Тавіо в Іскаарі." }
    t[198071] = { name = "Випалена Полум'ям Кістка", fen = "Djaradin runes cover this bone.", fua = "Цю кістку вкривають руни джарадинів." }
    t[198072] = { name = "Драконячий Зуб у Золотій Оправі", fen = "The remnant of a fallen dragon.", fua = "Останок полеглого дракона." }
    t[198073] = { name = "Карга, Спокійний Вітер", fen = "Karha was the staff of Ganmat the Wise, an Ohn'aran windsage who healed countless allies and defeated even more enemies centuries ago.", fua = "Карга був посохом Ганмата Мудрого, мудреця вітру з-поміж нащадків Он'агри, який століття тому зцілив незліченних союзників і подолав ще більше ворогів." }
    t[198074] = { name = "Джосанак, Певна Перемога", fen = "Josanak belonged to the undefeated warrior Zaphil. Zaphil always relied on his halberd, just as his clan could always rely on him.", fua = "Джосанак належав непереможному воїну Зафілу. Зафіл завжди покладався на свою алебарду, так само як його клан завжди міг покладатися на нього." }
    t[198075] = { name = "Цегзая, Тернистий Лук", fen = "Countless arrows from Tsegzaya found their way into both wild game and the enemies of Clan Teerai when Dihar drew the string.", fua = "Незліченні стріли з Цегзаї знаходили шлях і у дику дичину, і у ворогів клану Теераї, коли Дігар натягував тятиву." }
    t[198076] = "Розпилювач від Шкідників"
    t[198078] = { name = "Список Набору", fen = "Pages filled with recruitment strategies and instructions to find an artifact at the Nelthazan Ruins.", fua = "Сторінки, заповнені стратегіями набору та вказівками, як знайти артефакт у Руїнах Нелтазана." }
    t[198079] = { name = "Накази від Саркарета", fen = "The Aspects are complicit in the Destroyer's crimes. Find evidence of their attempts to control us. Speak out! Resist! - Scalecommander Sarkareth", fua = "Аспекти причетні до злочинів Руйнівника. Знайдіть докази їхніх спроб керувати нами. Говоріть уголос! Опирайтеся! - Командир Луски Саркарет" }
