    t[198346] = { name = "«Замовляйте Все, Що Виготовляють Ремісники!»", fen = "An Artisan's Consortium advertisement promoting that crafting orders can be made for any items, including rare and unique items only advanced crafters can make.", fua = "Оголошення Консорціуму Майстрів, що рекламує можливість замовити будь-які речі, зокрема рідкісні та унікальні, які до снаги лише досвідченим ремісникам." }
    t[198347] = { name = "«Загальні Замовлення: Швидко й Саме для Вас!»", fen = "An Artisan's Consortium advertisement promoting public crafting orders as useful for getting items crafted for you and making personal connections with crafters.", fua = "Оголошення Консорціуму Майстрів, що рекламує загальні ремісничі замовлення як зручний спосіб виготовити для себе речі та налагодити особисті зв'язки з ремісниками." }
    t[198348] = { name = "«Якісне Спорядження на Замовлення: Кращі Оборудки з Особистими Замовленнями!»", fen = "An Artisan's Consortium advertisement promoting personal and guild crafting orders which can be used to order custom-made, high-quality items with better guarantees than the public crafting order system.", fua = "Оголошення Консорціуму Майстрів, що рекламує особисті та гільдійні ремісничі замовлення, через які можна замовити високоякісні речі на замовлення з кращими гарантіями, ніж дає система загальних ремісничих замовлень." }
