    t[198452] = { name = "Прототип F", fen = "One of many experimental weapons that never went beyond the prototype stage.", fua = "Одна з багатьох експериментальних видів зброї, що так і не вийшли за межі стадії прототипу." }
    t[198453] = { name = "Нестабільна Азеритова Граната", fen = "Crate loads of these have been sold on the black market.", fua = "Цілі ящики цього продавали на чорному ринку." }
    t[198454] = { name = "Драконячий Трактат з Ковальства", fen = "Contains notes on various tricks of the trade used by Blacksmiths. Can only be studied once a week.", fua = "Містить нотатки про різноманітні фахові хитрощі ковалів. Вивчати можна лише раз на тиждень." }
    t[198455] = { name = "Сплутане Коріння", fen = "Brown and green, tough and tender, all mixed up.", fua = "Буре й зелене, тверде й ніжне — усе впереміш." }
    t[198456] = { name = "Мальок Оливоока", fen = "A young oliveye, partially transparent.", fua = "Молодий оливоок, частково прозорий." }
    t[198457] = { name = "Викрійка: Майстерний Халат", fen = "Teaches you how to craft Exquisite Leatherworker's Smock of Panache.", fua = "Навчає виготовляти Вишуканий Стильний Халат Шкіряра." }
    t[198458] = { name = "Викрійка: Осяйний Чохол", fen = "Teaches you how to craft Master Jeweler's Tool Holster.", fua = "Навчає виготовляти Чохол для Інструментів Майстра-Ювеліра." }
    t[198459] = { name = "Викрійка: Розкішна Квіткова Торба", fen = "Teaches you how to craft Lavish Herbalist's Botany Pack.", fua = "Навчає виготовляти Розкішну Ботанічну Торбу Травника." }
    t[198461] = { name = "Викрійка: Ударостійкі Рукавички", fen = "Teaches you how to craft Magnificent Engineer's Pinch-Proof Handguards.", fua = "Навчає виготовляти Чудові Защемозахисні Рукавиці Інженера." }
    t[198462] = { name = "Викрійка: Вогнетривкий Фартух", fen = "Teaches you how to craft Master Blacksmith's Flame Resistant Apron.", fua = "Навчає виготовляти Вогнестійкий Фартух Майстра-Коваля." }
    t[198463] = { name = "Викрійка: Капелюх Алхіміка-Знавця", fen = "Teaches you how to craft Spectacular Alchemist's Hydrophobic Headpiece.", fua = "Навчає виготовляти Видатний Водовідштовхувальний Головний Убір Алхіміка." }
    t[198464] = { name = "Викрійка: Підсилена Торба", fen = "Teaches you how to craft Superb Skinner's Tanning Rack.", fua = "Навчає виготовляти Чудову Дубильну Раму Білувальника." }
    t[198465] = { name = "Викрійка: Шапка Білувальника-Знавця", fen = "Teaches you how to craft Resplendent Skinner's Trapping Cap.", fua = "Навчає виготовляти Осяйну Мисливську Шапку Білувальника." }
    t[198474] = { name = "Мольберт Митця", fen = "Not everyone can become a great artist, but a great artist can come from anywhere.", fua = "Не кожен може стати великим митцем, але великий митець може постати будь-де." }
    t[198475] = { name = "Відламана Окантовка", fen = "A piece of a gold banding broken off a much larger statue.", fua = "Шматок золотої окантовки, відламаний від значно більшої статуї." }
    t[198476] = { name = "Картина-Знайомство", fen = "Competent strokes depict the Azure Archives, shrouded in snow, as seen from a distance. There is a wistfulness about the piece.", fua = "Вправні мазки зображають оповиті снігом Лазурові Архіви, бачені здалеку. Від твору віє тугою." }
