    t[198480] = { name = "Осяйні Водойми", fen = "A delicate palette of rose, ruby, and verdant green make up this half-finished painting of the Life Pools.", fua = "Витончена палітра рожевого, рубінового й соковито-зеленого складає цю недомальовану картину Водойм Життя." }
