    t[198482] = { name = "Спіраль Курганів", fen = "Spiral patterns curve around gentle, green hills as white, billowing winds blow trees sideways in this painting of the Ohn'ahran Plains.", fua = "Спіральні візерунки звиваються довкола лагідних зелених пагорбів, а білі поривчасті вітри нахиляють дерева вбік на цій картині Рівнин Он'агри." }
    t[198484] = { name = "Тління Папоротешкурів", fen = "A heavy green fog hangs over a rotting forest in this painting. The canvas itself smells foul.", fua = "Густий зелений туман нависає над гнилим лісом на цій картині. Саме полотно тхне гниллю." }
    t[198487] = { name = "Райдужна Вода", fen = "A light and bubbly liquid frequently used by Scribes. Can be purchased from vendors.", fua = "Легка й шипуча рідина, яку часто використовують накреслювачі. Можна придбати в торговців." }
