    t[198511] = { name = "Будівельні Матеріали", fen = "The crumbled remains of an earth elemental, calling it building materials is very charitable.", fua = "Обсипані рештки елементаля землі. Назвати це будівельними матеріалами — вельми великодушно." }
    t[198512] = { name = "Великі Зали", fen = "Barely more than a sketch, tall pillars and bright lights decorate this half-finished painting of the Halls of Infusion.", fua = "Заледве більше ніж ескіз: високі колони й яскраві вогні оздоблюють цю недомальовану картину Залів Просочення." }
    t[198513] = { name = "Академія", fen = "Colorful dragonflight banners hang over a massive wall as drakonids play below in this painting of Algeth'ar Academy.", fua = "Барвисті стяги зграй драконів звисають з велетенської стіни, а внизу бавляться драконіди на цій картині Академії Алгетара." }
    t[198514] = { name = "Запечатана Скарбниця", fen = "Great splatters of purple and blue denote bursts of arcane magic in this painting of the Azure Vault.", fua = "Великі бризки фіолетового й синього зображають спалахи таємної магії на цій картині Лазурової Скарбниці." }
    t[198515] = { name = "Вогняні Лабораторії", fen = "This painting of Neltharus is barely more than vague smudges of red, orange, and black.", fua = "Ця картина з Нелтарусом — заледве більше ніж невиразні мазки червоного, помаранчевого й чорного." }
    t[198516] = { name = "Останній Малюнок Гудзона", fen = "An unfinished sketch of Hudson and Ranpiata, their heads close together, smiling.", fua = "Незавершений ескіз Гудзона й Ранпіати: їхні голови близько схилені, обоє усміхаються." }
    t[198517] = { name = "Шкура Конкгулара", fen = "The color of this pelt blends well with the rocks and dirt in the area.", fua = "Колір цієї шкури добре зливається з камінням і ґрунтом цієї місцини." }
