    t[199120] = { name = "Доленосна Карта Долі", fen = "Actions speak louder than fortune cookies.", fua = "Учинки промовляють гучніше за печиво з передбаченнями." }
    t[199121] = { name = "Доленосна Карта Долі", fen = "Always look before you leap!", fua = "Завжди дивися, перш ніж стрибати!" }
