    t[199123] = { name = "Доленосна Карта Долі", fen = "In one hour, you will be hungry.", fua = "За годину ти зголоднієш." }
    t[199124] = { name = "Доленосна Карта Долі", fen = "Disregard the previous fortune.", fua = "Не зважайте на попереднє віщування." }
    t[199125] = { name = "Доленосна Карта Долі", fen = "Someone is going to give you a very unexpected gift!", fua = "Хтось зробить тобі вельми несподіваний подарунок!" }
    t[199126] = { name = "Доленосна Карта Долі", fen = "You will bring joy to someone.", fua = "Ти комусь подаруєш радість." }
    t[199127] = { name = "Доленосна Карта Долі", fen = "You love a good fortune card.", fua = "Ти любиш гарну карту віщування." }
    t[199128] = "Польові Нотатки з Білування"
    t[199129] = { name = "Доленосна Карта Долі", fen = "If at first you don't succeed, try, try again.", fua = "Якщо з першого разу не вийшло — пробуй, пробуй знову." }
    t[199130] = { name = "Доленосна Карта Долі", fen = "Tomorrows forecast is sunny with a chance of epic loot.", fua = "Прогноз на завтра: сонячно, можлива епічна здобич." }
    t[199131] = { name = "Доленосна Карта Долі", fen = "You'll begin to find what you're looking for.", fua = "Ти нарешті почнеш знаходити те, що шукаєш." }
    t[199132] = { name = "Доленосна Карта Долі", fen = "You will go further beyond your limits.", fua = "Ти зайдеш ще далі за свої межі." }
    t[199133] = { name = "Доленосна Карта Долі", fen = "You can always find happiness at the Darkmoon Faire.", fua = "Щастя завжди знайдеться на ярмарку Даркмун." }
    t[199134] = { name = "Доленосна Карта Долі", fen = "Pack your bags! You're headed on an adventure.", fua = "Збирай речі! На тебе чекає пригода." }
    t[199135] = { name = "Доленосна Карта Долі", fen = "You are feeling very sleepy.", fua = "Тебе хилить на сон." }
    t[199136] = { name = "Доленосна Карта Долі", fen = "You will soon receive an important message.", fua = "Незабаром ти отримаєш важливу звістку." }
    t[199137] = { name = "Доленосна Карта Долі", fen = "You are not illiterate.", fua = "Ти не безграмотний." }
    t[199138] = { name = "Доленосна Карта Долі", fen = "Soon you will be sitting on top of the world!", fua = "Скоро ти будеш на вершині світу!" }
    t[199139] = { name = "Доленосна Карта Долі", fen = "Welcome the changes coming soon into your life.", fua = "Прийміть зміни, що незабаром увійдуть у ваше життя." }
    t[199140] = { name = "Доленосна Карта Долі", fen = "The duck is a lie.", fua = "Качка — це брехня." }
    t[199141] = { name = "Доленосна Карта Долі", fen = "It's a good day to have a good day.", fua = "Сьогодні гарний день, щоб провести гарний день." }
    t[199142] = { name = "Доленосна Карта Долі", fen = "A sudden change of plans will lead to good fortune.", fua = "Раптова зміна планів принесе удачу." }
    t[199143] = { name = "Доленосна Карта Долі", fen = "Why would you trust a piece of paper?", fua = "Навіщо довіряти клаптику паперу?" }
    t[199144] = { name = "Доленосна Карта Долі", fen = "Give this fortune to a stranger for good luck!", fua = "Віддай це передбачення незнайомцю на удачу!" }
    t[199145] = { name = "Доленосна Карта Долі", fen = "When you crush your enemy, juice comes out, because that's whats inside.", fua = "Коли чавиш ворога, з нього бризкає сік, бо саме він усередині." }
    t[199146] = { name = "Доленосна Карта Долі", fen = "Avoid placing unnecessary Auction House bids. Lucky numbers: 5, 27, 57, 84, 42.", fua = "Уникай зайвих ставок на Аукціоні. Щасливі числа: 5, 27, 57, 84, 42." }
    t[199147] = { name = "Доленосна Карта Долі", fen = "Come back later. I am sleeping. (Yes, fortunes need their sleep too.)", fua = "Завітайте пізніше. Я сплю. (Так, віщуванням теж потрібен сон.)" }
    t[199148] = { name = "Доленосна Карта Долі", fen = "You should group with a healer.", fua = "Тобі варто взяти в гурт цілителя." }
    t[199149] = { name = "Доленосна Карта Долі", fen = "We've been trying to reach you about your mounts extended warranty.", fua = "Ми вже давно намагаємося зв'язатися з вами щодо подовження гарантії на ваше верхове." }
    t[199150] = { name = "Доленосна Карта Долі", fen = "I see a raid wipe in your future.", fua = "Я бачу вайп рейду у твоєму майбутньому." }
    t[199151] = { name = "Доленосна Карта Долі", fen = "You are always on N'Zoth's mind.", fua = "Ти завжди в думках Н'Зота." }
    t[199152] = { name = "Доленосна Карта Долі", fen = "Trusting your raid leader will take you far.", fua = "Довіра до проводиря рейду заведе вас далеко." }
    t[199153] = { name = "Доленосна Карта Долі", fen = "Some fortune cards contain no fortune.", fua = "Деякі картки долі не містять жодного передбачення." }
    t[199154] = { name = "Доленосна Карта Долі", fen = "Will that piece of loot drop? All signs point to yes.", fua = "Чи випаде та сама здобич? Усі знаки кажуть: так." }
    t[199155] = { name = "Доленосна Карта Долі", fen = "Keep your goals away from the trolls.", fua = "Тримай свої цілі подалі від тролів." }
    t[199156] = { name = "Доленосна Карта Долі", fen = "In two days, tomorrow will be yesterday.", fua = "За два дні завтра вже стане вчора." }
    t[199157] = { name = "Доленосна Карта Долі", fen = "With many failures will come wisdom.", fua = "Із численних невдач прийде мудрість." }
    t[199158] = { name = "Доленосна Карта Долі", fen = "The weather is wonderful!", fua = "Погода чудова!" }
    t[199159] = { name = "Доленосна Карта Долі", fen = "A fool and their money are soon partying.", fua = "Дурень зі своїми грошима недовго гуляють разом." }
    t[199160] = { name = "Доленосна Карта Долі", fen = "Don't look behind you.", fua = "Не озирайтеся." }
    t[199161] = { name = "Доленосна Карта Долі", fen = "Bigger bags = more loot.", fua = "Більші торби = більше здобичі." }
