    t[199163] = { name = "Доленосна Карта Долі", fen = "You will soon feel very warm. Avoid fire.", fua = "Незабаром тобі стане дуже гаряче. Уникай вогню." }
    t[199164] = { name = "Доленосна Карта Долі", fen = "Your next achievement will be your greatest.", fua = "Твоє наступне досягнення буде найвизначнішим." }
    t[199165] = { name = "Доленосна Карта Долі", fen = "Go for gold today!", fua = "Сьогодні — тільки на золото!" }
