    t[199167] = { name = "Доленосна Карта Долі", fen = "You will stumble upon a forgotten land with many new adventures ahead!", fua = "Ти натрапиш на забуту землю, де на тебе чекає безліч нових пригод!" }
    t[199168] = { name = "Доленосна Карта Долі", fen = "Make all the changes you see necessary.", fua = "Внеси всі зміни, які вважаєш за потрібні." }
    t[199169] = { name = "Доленосна Карта Долі", fen = "You are the mast of every situation.", fua = "Ти володар будь-якої ситуації." }
    t[199170] = { name = "Доленосна Карта Долі", fen = "You've reached it! You've peaked. It's all down hill from here.", fua = "Ти досяг його! Це твоя вершина. Далі — лише під гору." }
    t[199171] = { name = "Трохи Надкушене Качине Яйце", fen = "A distressed chiping can be heard as the egg begins to crack open.", fua = "Чути стривожене попискування, коли яйце починає тріскатися." }
