    t[199176] = { name = "Густе Ведмеже Хутро", fen = "This thick pelt will keep the people of Three-Falls Lookout warm. Hopefully, someone will get rid of the ticks and fleas before turning these into blankets.", fua = "Ця товста шкура зігріє людей із Застави Трьох Водоспадів. Хочеться вірити, що хтось виведе кліщів і бліх, перш ніж із неї зроблять ковдри." }
    t[199188] = { name = "Тюнінг: Підсилювач Полярності", fen = "Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.", fua = "Якість майстрування та спеціалізація в інженерії впливають на шанс успіху. Ця гарантія діє лише для спорядження Драконових Островів." }
