    t[199192] = { name = "Гаманець Драконових Перегонів", fen = "Filled with gold, Dragon Isles Supplies, and a chance for a Drakewatcher's Manuscript.", fua = "Наповнений золотом, Припасами Драконячих Островів і шансом на Фоліант Дракоглядача." }
