    t[199200] = { name = "Ніжне М'ясо Воркіна", fen = "Cut into nice thick slices, this meat is great for steaks.", fua = "Нарізане товстими скибами, це м'ясо чудово годиться на стейки." }
    t[199201] = { name = "Ніжне М'ясо Воркіна", fen = "Cut into nice thick slices, this meat is great for steaks.", fua = "Нарізане товстими скибами, це м'ясо чудово годиться на стейки." }
