    t[199205] = { name = "Манасмок", fen = "A rare fish that feeds off of magical essence. Has a tingly taste.", fua = "Рідкісна риба, що живиться магічною сутністю. Має поколювальний смак." }
    t[199206] = "Розбиті Адамантові Луски"
    t[199207] = { name = "Льодоспинний Бичок", fen = "Its dense bones are counterbalanced by the buoyant ice crystals that run down its spine.", fua = "Його щільні кістки врівноважують плавучі крижані кристали, що тягнуться вздовж хребта." }
    t[199208] = { name = "Ґрунґл", fen = "A truly unremarkable fish.", fua = "Воістину нічим не примітна риба." }
    t[199211] = { name = "Прадавня Сутність", fen = "As ancient as Azeroth itself, reemerged amidst extreme elemental activity. The Storm Hunter near your capital city might be interested in this.", fua = "Така ж давня, як сам Азерот, вона знову з'явилася серед надзвичайної стихійної активності. Цим міг би зацікавитися Мисливець Бурі поблизу твоєї столиці." }
    t[199212] = { name = "Риба-довбня", fen = "Heavy and blunt. If you ever find yourself at a tuskarr food fight, watch out for clubfish.", fua = "Важка й тупа. Якщо колись опинишся в харчовій бійці тускарів, стережися дубинориби." }
    t[199213] = { name = "Лаккамуцька Собача Риба", fen = "A froglike fish with lean white meat and cute little fins.", fua = "Жабоподібна риба з пісним білим м'ясом і милими маленькими плавцями." }
    t[199215] = { name = "Членство Світотрощителів", fen = "Be sure to keep your membership up to date!", fua = "Не забувайте поновлювати своє членство!" }
    t[199216] = { name = "Ящик Каміння", fen = "A perfectly good  box... being wasted on rocks.", fua = "Цілком гарний ящик... змарнований на каміння." }
