    t[199899] = { name = "Тяглові Сани Іскаари", fen = "It is said among the tuskarr that one who pulls the sled for another is a pillar of the community... but that doesn't stop kids from fighting over who gets to ride, instead.", fua = "Серед тускарів кажуть, що той, хто тягне сани для іншого, — опора громади... але це не заважає дітлахам сваритися за те, кому ж кататися." }
    t[199900] = { name = "Вживане Знаряддя Розвідника", fen = "Great for looking like you are doing something.", fua = "Чудово підходить, щоб вдавати, ніби ви чимось зайняті." }
