    t[199905] = "Видобуток: Пробуджена Земля"
    t[199906] = { name = "Реліквія титанів", fen = "The relic is very old and clearly of titan origin. This is the type of relic that Lead Titan Researcher Sorotis asked you to bring to her.", fua = "Реліквія дуже стара й вочевидь титанічного походження. Саме такі реліквії просила вас принести головна дослідниця титанів Соротіс." }
    t[199907] = { name = "Плани Бунтівників", fen = "These detail the plans and motivations of the Primalist-allied rebels.", fua = "У них викладено плани й наміри бунтівників, що в спілці з первісниками." }
    t[199915] = { name = "Прадавній Обсидіановий Талісман", fen = "A charm whose purpose and power has been lost to time.", fua = "Талісман, чиє призначення й сила загублені в часі." }
    t[199917] = { name = "Уламок Драконячої Кістки", fen = "According to the gnolls, these bones hold special Magic. To us, the bones' mutation could be of value.", fua = "За словами ґнолів, ці кістки містять особливу магію. Для нас же цінною може бути їхня мутація." }
    t[199918] = { name = "Сливовий Тарт із Медом", fen = "Sweet, sour, and delicious.", fua = "Солодкий, кислий і смачний." }
    t[199919] = { name = "Пудинг із Якового Молока", fen = "Sour, sweet, and delicious.", fua = "Кислий, солодкий і смачний." }
    t[199924] = { name = "Міцна Морська Капуста", fen = "Often washed ashore in Iskaara. Bring this to Tavio.", fua = "Часто прибивається до берега в Іскаарі. Віднесіть це Тавіо." }
    t[199925] = { name = "Камінь із Діркою", fen = "Not uncommon on the rocky shores of the Azure Span. Tavio in Iskaara will make use of it.", fua = "Не рідкість на скелястих берегах Лазурового Пасма. Тавіо в Іскаарі знайде йому застосування." }
