    t[200061] = { name = "Призматичний Стрибунець", fen = "The scales shimmer in multiple colors. Aside from its Cooking properties, this fish looks to be Millable.", fua = "Луска мерехтить безліччю кольорів. Окрім кулінарних властивостей, цю рибу, схоже, можна молоти." }
    t[200063] = { name = "«Ласощі» Уважних Загадок", fen = "A dubiously-crafted morsel for a cantankerous hornswog.", fua = "Сумнівно зготований шматочок для сварливого горнсвога." }
    t[200064] = { name = "Здобич Мармоні", fen = "A shimmery yellow banana ferreted away for safekeeping.", fua = "Мерехтливий жовтий банан, схований про запас." }
    t[200065] = { name = "Загублене Мило Шукача Пригод", fen = "A necessary item long forgotten by a hapless adventurer.", fua = "Потрібна річ, яку давно загубив бідолашний шукач пригод." }
    t[200066] = { name = "Добре Збережена Кістка", fen = "A dry, crusty piece of bone long protected from the elements.", fua = "Суха, шорстка кістка, що довго була захищена від стихій." }
    t[200067] = { name = "Шепітлива Скалка", fen = "This shard whispers many compliments into your mind. You are pretty great, aren't you?", fua = "Ця скалка нашіптує вам у думки безліч компліментів. Ви ж бо й справді чудові, чи не так?" }
    t[200069] = { name = "Обсидіановий Сховок", fen = "Contains gold, Dragon Isles Supplies, rare Dragon Isles Artifacts and Titan Relics as well as a chance for cosmetic Djaradin weapons and armor.", fua = "Містить золото, Припаси Драконових Островів, рідкісні Артефакти Драконових Островів і Реліквії Титанів, а також дає шанс на оздобну зброю та обладунки джарадинів." }
    t[200070] = { name = "Обсидіанова Скриня", fen = "Contains gold, Dragon Isles Supplies, rare artifacts and relics as well as a chance for cosmetic Djaradin weapons and armor.", fua = "Містить золото, Припаси Драконових Островів, рідкісні артефакти й реліквії, а також дає шанс на оздобну зброю та обладунки джарадинів." }
    t[200071] = { name = "Священний тотем тускарів", fen = "Stolen from the Iskaara Tuskarr, Elder Poa would reward you if you returned it to them.", fua = "Викрадений в іскаарських тускарів. Старійшина Поа винагородить вас, якщо ви повернете його." }
    t[200072] = { name = "Скарбничка фортеці Драконоборців", fen = "Contains plundered items, supplies, gold and artifacts.", fua = "Містить награбовані речі, припаси, золото й артефакти." }
    t[200073] = { name = "Скарби Валдраккена", fen = "Contains equipment, supplies, and treasures gathered throughout the ages.", fua = "Містить спорядження, припаси й скарби, зібрані впродовж віків." }
    t[200074] = { name = "Замерзлий Інеєплавцевий Тунець", fen = "A sturdy fish coated in a frosted outer shell.", fua = "Дужа риба, вкрита крижаним панциром." }
    t[200075] = { name = "Кістки Летючої Риби", fen = "Should be plentiful in fishing villages, such as Iskaara. Bring this to Tavio.", fua = "Їх удосталь у рибальських селищах, як-от Іскаара. Віднесіть це Тавіо." }
    t[200076] = { name = "Вістря Гарпуна", fen = "Skilled blacksmiths, such as Iskaara Tuskarr, should have one. Bring it to Tavio in Iskaara.", fua = "Вправні ковалі, як-от іскаарські таскари, мають таке. Віднесіть його Тавіо в Іскаару." }
    t[200077] = { name = "Дерев'яне Держално", fen = "Should be easy to find somewhere in the forests of western Azure Span. Bring to Tavio in Iskaara.", fua = "Його легко знайти десь у лісах західного Лазурового Пасма. Віднесіть Тавіо в Іскаару." }
    t[200078] = { name = "Лезо Кайла", fen = "You could probably \"borrow\" one in a Dragonscale Expedition camp, such as Three-Falls Lookout. Bring it to Tavio in Iskaara.", fua = "Ви, певно, могли б «позичити» одне в таборі Експедиції Драконячої Луски, як-от на Заставі Трьох Водоспадів. Віднесіть його Тавіо в Іскаару." }
    t[200079] = { name = "Гладкий Морський Базальт", fen = "Should be abundant where lava meets the sea, such as Wild Coast. Bring to Tavio in Iskaara.", fua = "Його вдосталь там, де лава зустрічається з морем, як-от на Дикому Узбережжі. Віднесіть Тавіо в Іскаару." }
    t[200080] = { name = "Самородок Драконію", fen = "Used to improve Iskaaran fishing net. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.", fua = "Слугує для вдосконалення іскаарської рибальської сітки. Віднесіть Тавіо в Іскаару. Можна виловити у високогір'ї Драконових островів, у крижаних ополонках чи лавових озерцях." }
    t[200081] = { name = "Міцна Морська Лоза", fen = "Used to improve Iskaaran harpoon. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.", fua = "Слугує для вдосконалення іскаарського гарпуна. Віднесіть Тавіо в Іскаару. Можна виловити у високогір'ї Драконових островів, у крижаних ополонках чи лавових озерцях." }
    t[200082] = { name = "Подерта Сітка з Імбу", fen = "Used to improve Iskaaran fishing net. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.", fua = "Слугує для вдосконалення іскаарської рибальської сітки. Віднесіть Тавіо в Іскаару. Можна виловити у високогір'ї Драконових островів, у крижаних ополонках чи лавових озерцях." }
    t[200083] = { name = "Гілка Залізодрева", fen = "Used to improve Iskaaran harpoon. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.", fua = "Слугує для вдосконалення іскаарського гарпуна. Віднесіть Тавіо в Іскаару. Можна виловити у високогір'ї Драконових островів, у крижаних ополонках чи лавових озерцях." }
    t[200084] = { name = "Солений Серевіт", fen = "Used to improve Iskaaran harpoon. Bring to Tavio in Iskaara. Can be fished in Dragon Isles highlands, ice holes, or lava pools.", fua = "Слугує для вдосконалення іскаарського гарпуна. Віднесіть Тавіо в Іскаару. Можна виловити у високогір'ї Драконових островів, у крижаних ополонках чи лавових озерцях." }
    t[200085] = { name = "Хазгоритовий Дріт", fen = "Used to further improve Iskaaran fishing net. Bring to Tavio in Iskaara. Can be caught with fishing net.", fua = "Слугує для подальшого вдосконалення іскаарської рибальської сітки. Віднесіть Тавіо в Іскаару. Можна спіймати рибальською сіткою." }
    t[200086] = { name = "Смола, Насичена Хазгоритом", fen = "Used to further improve your Iskaaran harpoon. Bring to Tavio in Iskaara. Can be obtained from BIG fish in the Dragon Isles with an Iskaaran harpoon.", fua = "Слугує для подальшого вдосконалення вашого іскаарського гарпуна. Віднесіть Тавіо в Іскаару. Можна здобути з ВЕЛИЧЕЗНОЇ риби на Драконових островах за допомогою іскаарського гарпуна." }
    t[200087] = { name = "Частка Водоспаду", fen = "This viscous liquid is difficult to hold onto.", fua = "Цю в'язку рідину важко втримати в руках." }
    t[200093] = { name = "Мисливський трофей кентаврів", fen = "Can be turned in to Hunt Instructor Basku in Maruukai to increase your standing with the Maruuk Centaurs.", fua = "Можна віддати інструктору полювання Баску в Маруукаї, аби підвищити вашу репутацію серед кентаврів Маруук." }
    t[200094] = { name = "Скриня Каравану", fen = "Clan Aylaag is known for trade, but also generosity to those who help them. Valuable equipment, artifacts and trade items can be found in their strongboxes.", fua = "Клан Айлаг відомий торгівлею, але й щедрістю до тих, хто йому допомагає. У його скринях можна знайти цінне спорядження, артефакти й торговельні товари." }
    t[200095] = { name = "Казан із Припасами", fen = "As a sign of thanks, the pot is full of supplies and food. There just might be an artifact or piece of equipment buried at the bottom.", fua = "На знак подяки цей казан повний припасів і їжі. А на самому дні може чекати навіть артефакт чи спорядження." }
    t[200099] = { name = "Г.Д.Х.", fen = "Meat Ready to Eat.", fua = "Готова до Харчування. М'ясо." }
    t[200102] = { name = "Креслення: Лютосний Сплав", fen = "Teaches you how to craft Infurious Alloy.", fua = "Навчає вас виготовляти Лютосний Сплав." }
    t[200103] = { name = "Викрійка: Лютосна Шкіра", fen = "Teaches you how to craft Infurious Hides.", fua = "Навчає вас виготовляти Лютосні Шкіри." }
    t[200104] = { name = "Викрійка: Лютотканна Луска", fen = "Teaches you how to craft Infurious Scales.", fua = "Навчає вас виготовляти лютотканну луску." }
    t[200105] = "Вкритий Багном Уламок"
    t[200106] = "Слизький Старий Чобіт"
    t[200107] = "Потьмянілий Заручний Перстень"
    t[200108] = { name = "Енергетичне Ядро Іридея", fen = "Taken from the Halls of Infusion, this device once powered up Watcher Irideus.", fua = "Взяте із Зал Вливання, цей пристрій колись живив Спостерігача Іридея." }
    t[200109] = { name = "Лікувальне Зілля", fen = "A pleasant warmth radiates from the opalescent liquid inside.", fua = "Від опалесцентної рідини всередині линь приємне тепло." }
    t[200110] = { name = "Шепітливі Уламки", fen = "The whispers from these fragments grow louder the more you collect. Perhaps there is no harm in listening just a little bit.", fua = "Шепіт цих уламків гучнішає, що більше ви їх збираєте. Можливо, немає шкоди в тому, щоб трохи дослухатися." }
    t[200113] = { name = "Резонансний Кристал", fen = "Gathered by players with the Enchanting skill by disenchanting items. Can be bought and sold on the auction house.", fua = "Збирається гравцями з умінням Накладання чарів шляхом розчаклування предметів. Можна купити й продати на аукціоні." }
    t[200116] = { name = "Вічний Ріг Лавоплавання", fen = "Just don't be swimming when it wears off.", fua = "Тільки не плавайте, коли дія закінчується." }
    t[200117] = { name = "Золотий Пояс Спостерігача", fen = "Holds many potential secrets of the Titans, metalworking, and most importantly... fashion.", fua = "Містить чимало можливих таємниць Титанів, ковальства і, найголовніше... моди." }
    t[200118] = { name = "Жовтий Оттук-Розвідник", fen = "Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location.", fua = "Навчає викликати цей засіб пересування. Цей засіб пересування змінюється залежно від вашої навички верхової їзди та місцезнаходження." }
    t[200119] = { name = "Вічнопалаюче Вогнесерце", fen = "They say that Firava's heart grew three sizes that day, thanks to the Primalists.", fua = "Кажуть, що того дня серце Фірави зросло втричі — завдяки первісникам." }
    t[200120] = { name = "Енергетичне Ядро Іридея", fen = "Taken from the Halls of Infusion, this device once powered up Watcher Irideus. Now it must be attuned again to regain its original power output.", fua = "Узятий із Залів Вливання, цей пристрій колись живив Вартового Іридея. Тепер його треба наново налаштувати, щоб повернути первісну потужність." }
    t[200121] = { name = "Зілля Удачі Початківця", fen = "You can do it!", fua = "У вас усе вийде!" }
    t[200122] = { name = "Часова Підзорна Труба", fen = "Flickers of things past, present, and future overlap as you look through it.", fua = "Коли дивишся крізь неї, проблиски минулого, теперішнього й майбутнього накладаються один на одного." }
    t[200123] = { name = "Бурхлива Лілія", fen = "Magical water droplets form on the petals and float upwards in spirals.", fua = "На пелюстках утворюються магічні краплі води та злітають угору спіралями." }
    t[200124] = { name = "Спантеличений Бажанохвіст", fen = "Legends say this rare fish has the ability to grant wishes to those who can catch it speaking.", fua = "Легенди кажуть, що ця рідкісна риба здатна виконувати бажання тим, хто застане її за розмовою." }
    t[200125] = { name = "Кам'яне Серце Кам'яносерда", fen = "Infused by the Primalists to bestow tremendous power on a mortal.", fua = "Наснажене первісниками, щоб наділити смертного величезною силою." }
    t[200126] = { name = "Оплічник Незліченних Хронологій", fen = "Small fragments of this cloak constantly vanish and reappear.", fua = "Маленькі клапті цього плаща раз у раз зникають і з'являються знову." }
    t[200127] = { name = "Лезо із Золотого Сплаву", fen = "Resistant to rot.", fua = "Стійке до гниття." }
    t[200128] = "Лезо Зефіру"
    t[200129] = { name = "Клунок Колґара", fen = "Heavy with unused travel gear, enough for two people.", fua = "Важкий від невикористаного дорожнього спорядження, якого вистачить на двох." }
    t[200130] = "Шматувач Трупів"
    t[200131] = "Віднайдений Кинджал Виживальника"
    t[200132] = "Рило Шпигуна"
    t[200133] = "Вулканічний Чакрам"
    t[200134] = { name = "Тотем Масового Скування Огун", fen = "Carefully crafted by cruel Primalists to imprison the children of Ohn'ara.", fua = "Дбайливо виготовлений жорстокими первісниками, щоб ув'язнити дітей Он'агри." }
    t[200135] = { name = "Роз'їдений Дворучний Меч", fen = "Despite being trapped in a water elemental long enough to change color, the blade is still sharp.", fua = "Хоч він був ув'язнений у водному елементалі так довго, що аж змінив колір, лезо досі гостре." }
    t[200136] = "Наручі Мусону"
    t[200137] = "Хітиновий Жахоносець"
    t[200138] = { name = "Довгий Спис Прадавньої Танцівниці", fen = "Large, but remarkably light.", fua = "Великий, але напрочуд легкий." }
    t[200139] = { name = "Грозовий Лук", fen = "Sometimes lightning does strike twice.", fua = "Подеколи блискавка таки б'є двічі." }
    t[200140] = { name = "Уламки Іклопаду", fen = "An ancient sword of unknown power, shattered to pieces during a long-forgotten battle.", fua = "Прадавній меч невідомої сили, розбитий на друзки в давно забутій битві." }
    t[200141] = { name = "Перстень, що Породжує Вітер", fen = "Not suitable for two-legged creatures.", fua = "Не підходить для двоногих створінь." }
    t[200143] = { name = "Череп Феністрази", fen = "Enchanted by the djaradin who slayed the skull's original owner, magma continuously pours from its eye sockets.", fua = "Зачарований джарадинами, що вбили первісного власника черепа; з очниць безперервно струменить магма." }
    t[200144] = "Перстень Незборимості"
    t[200145] = "Моноліт з Руків'ям"
    t[200146] = "Незлагоджений Трощитель Фенрана"
    t[200147] = { name = "Роба з Павутиння", fen = "This silk keeps enemies out as well as it keeps prey in.", fua = "Цей шовк так само добре не пускає ворогів, як і втримує здобич." }
    t[200148] = { name = "Зібрання Самого Себе", fen = "The one you can always count on.", fua = "Той, на кого ви завжди можете покластися." }
    t[200149] = { name = "Вовна Дикого Арґалі", fen = "While stained and courser than domestic argali wool, it still functions well to reinforce sitting blankets and tents.", fua = "Хоч вона плямиста й грубіша за вовну свійського арґалі, вона добре годиться, щоб укріплювати підстилки та намети." }
    t[200150] = "Горнило Інфернума"
    t[200151] = { name = "Лезо Морської Імли", fen = "It's always a bit damp.", fua = "Воно завжди трохи вологе." }
    t[200152] = "Сяйливий Клинок Прозріння"
    t[200153] = "Ножиці для Білування Айлаагів"
    t[200154] = { name = "Перстень з Рубінової Луски", fen = "The etching on the scales is particularly impressive.", fua = "Гравірування на лусці особливо вражає." }
    t[200155] = "Абияк Зварений Захисник"
    t[200156] = { name = "Аметизаритова Жеода", fen = "A fragment of a fallen earth elemental, useful only to those who understand the mysteries of gems.", fua = "Уламок полеглого земного елементаля, корисний лише тим, хто розуміється на таємницях самоцвітів." }
    t[200157] = "Прокладач Шляху"
    t[200158] = { name = "Моторошний Примарний Перстень", fen = "A spirit has attached itself to this band.", fua = "До цього персня причепився дух." }
    t[200159] = { name = "Перстень Полум'я", fen = "Radiates enough heat to start a small fire.", fua = "Випромінює достатньо жару, щоб розпалити невеличке багаття." }
    t[200160] = { name = "Улюблена Страва Нотфара", fen = "Beans and rice are good for your heart.", fua = "Квасоля з рисом корисні для серця." }
    t[200161] = "Талісман Гострого Вітру"
    t[200162] = { name = "Загублений Повітряний Змій Таскарів", fen = "Small scrolls are attached to different pieces of the kite.", fua = "До різних частин змія прив'язані невеличкі сувої." }
    t[200163] = { name = "Перстень Жарин", fen = "Fire lives in the belly of the jewel.", fua = "Вогонь живе в осерді самоцвіту." }
    t[200164] = { name = "Крижаний Перстень", fen = "Always cold to the touch.", fua = "Завжди холодний на дотик." }
    t[200165] = { name = "Егіда з Луски", fen = "These ancient black dragon scale fragments were turned to use for a mortal's defense long ago.", fua = "Ці прадавні уламки луски чорного дракона колись давно пристосували для захисту смертного." }
    t[200166] = "Зіпсутий Ріг Дрейка"
    t[200167] = { name = "Відригнута Кам'яна Ручна Сокира", fen = "A crude weapon, yet strong enough to survive inside a lava worm...", fua = "Груба зброя, та все ж достатньо міцна, щоб уціліти в череві лавового хробака..." }
    t[200168] = "Пояс зі Шкіри Гнола"
    t[200169] = { name = "Розжарений Кий Захисника", fen = "The handle is enchanted to ward off heat.", fua = "Руків'я зачароване, щоб відганяти жар." }
    t[200170] = "Лук Грозоносця"
    t[200171] = "Клинок Похмурого Серця"
    t[200172] = { name = "Перстень-Печатка Зефірного Танцю", fen = "Bears the mark of a famous dancer so graceful they were said to stride upon the winds.", fua = "Несе знак уславленої танцівниці, такої граційної, що, кажуть, вона ступала просто вітром." }
    t[200174] = { name = "Наплічники з Кістяними Сигілами", fen = "The carvings evoke a feeling of security.", fua = "Різьблення викликає відчуття захищеності." }
    t[200175] = { name = "Переплавлене Ковадло", fen = "For when you need to cut--or smash--out the middle man.", fua = "Для тих випадків, коли треба вирізати — або розчавити — посередника." }
    t[200176] = { name = "Ручна Гармата Міссінґвея", fen = "If at first you don't hit the target, shoot, shoot again.", fua = "Якщо з першого разу не влучили в ціль — стріляйте, стріляйте ще." }
    t[200178] = "Заражена Сукровиця"
    t[200179] = { name = "Рубіновий Перстень Життя", fen = "Crafted by Alexstrasza herself long ago. Holding it, you feel reinvigorated for your next adventure.", fua = "Колись давно його створила сама Алекстраза. Тримаючи його, ви відчуваєте новий приплив сил для наступної пригоди." }
    t[200180] = { name = "Посох Кристалізованої Блискавки", fen = "These shards were the pure fury of Gaelzion.", fua = "Ці скалки були чистою люттю Ґаелзіона." }
    t[200181] = "Клинок Палаючої Муки"
    t[200182] = "Клепаний Плащ"
    t[200185] = "Рукавиці Вічноплинного Океану"
    t[200186] = { name = "Покривало з Бурштинового Пера", fen = "Many consider shed ohuna feathers to be lucky.", fua = "Багато хто вважає скинуті пера огуни щасливим знаком." }
    t[200187] = { name = "Жезл Льодовикової Сили", fen = "From time to time, you hear the crack of frigid ice breaking within.", fua = "Час від часу ви чуєте, як усередині тріскається крижаний лід." }
    t[200188] = { name = "Зламана Вудка", fen = "The fishing line tied to this pole has been snapped, but it might still have some use.", fua = "Волосінь, прив'язана до цієї вудки, обірвалася, та вудка ще може стати у пригоді." }
    t[200189] = { name = "Гідрокований Панцерний Шолом", fen = "Do NOT bring into contact with salt!", fua = "НЕ допускайте контакту із сіллю!" }
    t[200190] = { name = "М'яка Іграшка-Каченя", fen = "A small stuffed toy shaped like a duckling, probably left behind by a tuskarr child.", fua = "Маленька м'яка іграшка у формі каченяти, яку, ймовірно, загубило дитя таскарів." }
    t[200191] = { name = "Принада на Оттука", fen = "It's a plushie! On a string! What ottuk could resist this?", fua = "Це м'яка іграшка! На мотузці! Який оттук перед цим устоїть?" }
    t[200192] = { name = "Ручний Гейзер", fen = "Old and always Faithful.", fua = "Старий та завжди надійний." }
    t[200193] = { name = "Сандалі з Манолисту", fen = "Woven from reeds that grow near mana-rich waters.", fua = "Сплетені з очерету, що росте біля багатих на ману вод." }
    t[200195] = { name = "Громолускаті Поножі", fen = "Sturdy, but conductive.", fua = "Міцні, але струмопровідні." }
    t[200197] = { name = "Пастуший Посох для Армородонів", fen = "Some tools are better repurposed for other means.", fua = "Деякі знаряддя краще пристосувати під інші потреби." }
    t[200198] = { name = "В'язниця Первісників", fen = "Jail as old as time.", fua = "Темниця, стара як сам час." }
    t[200199] = { name = "Тягар Стихій", fen = "\"We Primalists gladly shoulder this burden to free the world from the hated Titans' influence.\"", fua = "«Ми, первісники, радо беремо на себе цей тягар, щоб звільнити світ від ненависного впливу Титанів.»" }
    t[200200] = { name = "Земне Первісне Ядро", fen = "Captured from a foe by Neltharion long ago, the core still struggles to escape its restraints.", fua = "Колись давно Нелтаріон відібрав його у ворога, і ядро досі силкується вирватися з пут." }
    t[200202] = { name = "Завтрашні Кайдани", fen = "Eventually you'll need to take them back when they came from.", fua = "Зрештою вам доведеться повернути їх туди, звідки вони взялися." }
    t[200203] = { name = "Перероблений Наперсток Велета", fen = "Not much of a thimble, really.", fua = "Як наперсток він майже нікудишній." }
    t[200204] = "Нагрудник Сяйва Пісків"
    t[200206] = "Великий Лук Вбивці Бегемотів"
    t[200207] = "Скам'янілі Грибні Спори"
    t[200208] = "Хмарозбірні Намотки на Руки"
    t[200209] = "Каптур Вогнедихача"
    t[200210] = { name = "Амнезія", fen = "A pendant empowered by a stolen memory.", fua = "Амулет, наснажений украденим спогадом." }
    t[200211] = "Крижаний Погляд Сніговика"
    t[200212] = "Вкриті Піском Поножі"
    t[200213] = { name = "Заляпаний Лавою Нагрудник", fen = "The encrusted igneous rocks resemble bullet holes quite closely.", fua = "Застиглі вулканічні камені дуже схожі на сліди від куль." }
    t[200214] = "Хватка Заплаканої Вдови"
    t[200215] = "Пернаті Наплічники Полювання"
    t[200216] = { name = "Водогрійний Шнур", fen = "Magically converts water into steam.", fua = "Магічно перетворює воду на пару." }
    t[200217] = "Палаюча Сутність"
    t[200218] = { name = "Обвуглена Вудка", fen = "Fire hardened within the belly of a hornswog.", fua = "Загартована вогнем у череві горнсвоґа." }
    t[200219] = "Небезпечна Завіса"
    t[200221] = "Горлоцькі Кристали"
    t[200222] = { name = "Пігмент Білого Дзвоника", fen = "The chalky pigment of the White Bell flower is very resistant to water making it highly valuable for outdoor use.", fua = "Крейдяний пігмент квітки білого дзвоника дуже стійкий до води, що робить його надзвичайно цінним для роботи просто неба." }
    t[200224] = { name = "Знак Сарґи", fen = "Present this to Sabellian's Quartermasters as proof of your support.", fua = "Покажіть це інтендантам Сабелліана на доказ вашої підтримки." }
    t[200228] = { name = "Протолускаті Наплічники", fen = "Acrosoth's scales are nearly impenetrable.", fua = "Луска Акрозота майже непробивна." }
    t[200229] = { name = "Трохи Перетравлені Поножі", fen = "Still in one piece, these are unusually resilient.", fua = "Вони досі цілі та напрочуд міцні." }
    t[200230] = "Латні Наплічники Жахокігтя"
    t[200231] = { name = "Полум'яний Кам'янолускатий Оплот", fen = "The tough hide of a stone protodrake makes an ideal shield.", fua = "Цупка шкура кам'яного протодракона стає ідеальним щитом." }
    t[200232] = "Кігтиста Глефа Раптора"
    t[200233] = { name = "Парадоксальна Шабля", fen = "An ancient blade, yet to be forged.", fua = "Прадавнє лезо, яке ще належить викувати." }
    t[200234] = "Карбований Захист Врака"
    t[200236] = "Спогад про Нультерію"
    t[200237] = { name = "Полірований Щиток Берегині Життя", fen = "Reflections of red flame flicker across its surface.", fua = "Відблиски червоного полум'я мерехтять на його поверхні." }
    t[200241] = { name = "Ритуальна Сокирка Буревісника", fen = "An ancient relic imbued with the voice of a great Thorignir matriarch.", fua = "Прадавня реліквія, наповнена голосом великої матріархині Торігнір." }
    t[200242] = { name = "Громовідвід Спостерігача", fen = "Avoid use in high places.", fua = "Не використовуйте на висоті." }
    t[200243] = { name = "Парадне Вбрання Титанічного Книжника", fen = "Formal garb worn by professors at the Flamebeard Conservatory.", fua = "Урочистий одяг, що його носять професори Консерваторії Полум'яної Бороди." }
    t[200244] = { name = "Зачаровані Багнотопи", fen = "Mud and detritus slip right off. Convenient!", fua = "Бруд і твань зісковзують самі собою. Зручно!" }
    t[200245] = { name = "Принада на Левіафана", fen = "In the darkest of waters, the line between catch and bait blurs.", fua = "У найтемніших водах межа між здобиччю та принадою розмивається." }
    t[200246] = { name = "Загублений Ліхтар Розкопувача", fen = "In the world's deepest places, darkness is often a mercy.", fua = "У найглибших місцях світу темрява часто буває милістю." }
    t[200247] = { name = "Незгасима Булава", fen = "Even a great water elemental could not put out the burning core of this mace.", fua = "Навіть могутній водний елементаль не зміг загасити палке ядро цієї булави." }
    t[200248] = { name = "Засмажена Книга", fen = "A textbook example of 'well-done'.", fua = "Підручниковий приклад «добре пропеченого»." }
    t[200249] = "Погризена Чарівна Паличка Мага"
    t[200250] = "Глефа з Морозним Вістрям"
    t[200251] = { name = "Медальйон Предків", fen = "It depicts Warlord Jhakan unifying the Maruuk centaur.", fua = "Тут зображено воєначальника Джакана, який об'єднує кентаврів Маруук." }
    t[200252] = { name = "Розплавлена зенітна гармата", fen = "Runs on rubble.", fua = "Працює на уламках." }
    t[200253] = { name = "Ніж заклинача Снігового Джерела", fen = "Elegant carvings of Ursoc and Ursol adorn the blade.", fua = "Клинок прикрашають вишукані різьблення Урсока й Урсола." }
    t[200254] = "Тотемний Пояс"
    t[200256] = { name = "Ріг душ Темнобоїв", fen = "Gor'groth's necromantic experiments required ever greater sources of fuel.", fua = "Некромантські досліди Гор'гроса потребували дедалі більших джерел палива." }
    t[200257] = "Гілка, Сповнена Гниттям"
    t[200258] = { name = "Роги Арбоґа", fen = "Heavy and jagged with many scars from battles old and new.", fua = "Важкі й зазубрені, з безліччю шрамів від давніх і нових битв." }
    t[200259] = { name = "Щит лісового мешканця", fen = "Light enough for a fresh adventurer, but may catch fire.", fua = "Достатньо легкий для початківця, але може зайнятися." }
    t[200261] = "Наручі з Білого Хітину"
    t[200264] = "Палкий Любовний Роман: Хтива Драконіанська Магиня"
    t[200265] = { name = "Щаслива драконяча кігтя", fen = "You need to be lucky to not get killed wearing this.", fua = "Треба мати щастя, щоб не загинути, носячи її." }
    t[200266] = { name = "Ґнольський метач іграшок", fen = "Also works as a crossbow.", fua = "Працює також як арбалет." }
    t[200267] = { name = "Зміцнені садові рукавиці", fen = "Guaranteed to work against thorns, burrs, and other forms of hostile foliage.", fua = "Гарантовано діють проти колючок, реп'яхів та інших форм ворожого листя." }
    t[200268] = { name = "Розкришений елементальний камінь", fen = "This needs more glue to hold itself together.", fua = "Потрібно більше клею, аби він тримався купи." }
    t[200269] = { name = "Талісман драконячого скарбу", fen = "Wearing this, one might find the greatest of dragon hoards!", fua = "Носячи його, можна відшукати найбільші з драконячих скарбів!" }
    t[200270] = { name = "Громовий обладунок Мара'нара", fen = "Crackling with storm-infused energy.", fua = "Потріскує сповненою бурею енергією." }
    t[200271] = { name = "Безпомильний оберіг від горносвоґа", fen = "Full refund if it fails to keep you from being eaten whole by Hornswog!", fua = "Повне повернення коштів, якщо не вбереже вас від того, щоб горносвоґ проковтнув вас цілком!" }
    t[200272] = "Чоботи, Укріплені Кератином"
    t[200273] = { name = "Карта диверсанта", fen = "A detailed map of Valdrakken and the surrounding area. The Seat of the Aspects has a red X crossed through it. In addition, there's a circle around a nearby region marked as the Misty Vale.", fua = "Детальна карта Валдраккена й околиць. Престол Аспектів перекреслено червоним хрестом. Крім того, обведено колом сусідню місцевість, позначену як Туманна Долина." }
    t[200274] = "Чоботи Списолама"
    t[200275] = "Сандалі Гейзероходця"
    t[200277] = "Гаптовані Обмотки Ширококопитих"
    t[200278] = "Шаль Археолога Драконів"
    t[200279] = "Змагальні Метальні Латні Рукавиці"
    t[200280] = { name = "Зотлілий примарний перстень", fen = "Bits keep falling off, but the ring remains intact.", fua = "Шматочки раз у раз відпадають, але перстень лишається цілим." }
    t[200281] = { name = "Нагай Ґорджо", fen = "The secret of his success.", fua = "Секрет його успіху." }
    t[200282] = { name = "Палкий Любовний Роман: Хтива Драконіанська Магиня", fen = "Signed by the author, Noah Scribeson", fua = "Підписано автором, Ноа Скрайбсоном" }
    t[200283] = { name = "Погризені ґнолами штани", fen = "Still intact. Mostly.", fua = "Досі цілі. Здебільшого." }
    t[200284] = "Амулет із Пера Фенікса"
    t[200285] = "Відзнака Експедиції Драконячої Луски"
    t[200286] = { name = "Списа Драконьої Погибелі", fen = "Designed for dueling with dragons.", fua = "Створена для двобоїв із драконами." }
    t[200287] = "Відзнака Тускарів Іскаари"
    t[200288] = "Відзнака Кентаврів Маруук"
    t[200289] = "Відзнака Угоди Валдраккена"
    t[200291] = { name = "Промоклі гоночні рукавиці", fen = "If found, please return to Razzeric.", fua = "Якщо знайдете, поверніть, будь ласка, Раззеріку." }
    t[200292] = "Наплічники Скельної Кузні"
    t[200293] = "Парний Клинок Первісного Нащадка"
    t[200294] = { name = "Первісний кольчужний обладунок", fen = "Fortified with enchanted elementium.", fua = "Зміцнений зачарованим елементієм." }
    t[200295] = "Повний Щоденник Макко"
    t[200296] = "Наручі з Бивнів Мамонта"
    t[200297] = { name = "Поспіхом стулений молот", fen = "Innovative? No. Effective? Certainly.", fua = "Винахідливий? Ні. Дієвий? Безперечно." }
    t[200298] = "Великий Пояс із Тесаного Каменю"
    t[200299] = { name = "Дивний механічний гладіус", fen = "Gears within the hilt turn soundlessly. Somehow never loses its edge.", fua = "Шестерні в руків'ї обертаються безшумно. Якимось чином ніколи не тупиться." }
    t[200300] = { name = "Мішок награбованих скарбів", fen = "Loot too heavy for Trambladd to run away with.", fua = "Здобич надто важка, щоб Трамбладд утік з нею." }
    t[200301] = { name = "Віднайдений гарпун тускарів", fen = "Not designed to hunt proto-drakes.", fua = "Не призначений для полювання на протодраків." }
    t[200302] = { name = "Магмокований ятаган", fen = "Djaradin runes along the blade read \"from the heart of the volcano to the heart of a dragon\".", fua = "Руни джарадинів уздовж клинка промовляють: \"Від серця вулкана до серця дракона\"." }
    t[200303] = { name = "Посох послушника Сноткачів", fen = "Norgannon's legacy endures in the reverent words of dedicated arcanists.", fua = "Спадок Норганнона живе в шанобливих словах відданих арканістів." }
    t[200304] = { name = "Складені пайки драктирів", fen = "With only a ten-thousand-year shelf life, you'll need to eat these soon before they go bad.", fua = "Маючи термін придатності лише десять тисяч років, з'їсти їх доведеться скоро, доки не зіпсувалися." }
    t[200305] = { name = "Водяні пайки драктирів", fen = "Water. Water never changes.", fua = "Вода. Вода ніколи не змінюється." }
    t[200306] = { name = "Шаль бурі", fen = "Though remarkably light, its fabric can withstand the most bitter harsh winds.", fua = "Хоч і навдивовижу легка, її тканина витримує найлютіші суворі вітри." }
    t[200307] = "Лютий Гачкуватий Тесак"
    t[200308] = { name = "Спадок Реллена", fen = "His name echoes upon the keening whistle of every hunter's arrow.", fua = "Його ім'я лунає у пронизливому свисті стріли кожного мисливця." }
    t[200309] = "Нагрудник, Вкритий Камінням"
    t[200310] = { name = "Палантин Залізного Привида", fen = "Its coming is heralded by the clatter of chains and the wailing of lost souls.", fua = "Його прихід провіщають брязкіт ланцюгів і голосіння загублених душ." }
    t[200311] = "Молот Кістяних Шипів"
    t[200313] = { name = "Земляний плащ із протолуски", fen = "Drakes imbued with the might of the earth bear scales as hard as diamond.", fua = "Драки, сповнені могуттю землі, носять луску, тверду, мов діамант." }
    t[200314] = { name = "Конверт Небомовця", fen = "Bears the markings of one who has entreated with the children of wind.", fua = "Несе на собі знаки того, хто благав дітей вітру." }
