    t[200443] = { name = "Артефакт Драконячих Островів", fen = "A common artifact, but Cataloger Jakes at the Dragonscale Basecamp will reward any artifact returned.", fua = "Звичайний артефакт, але каталогізаторка Джейкс у Базовому Таборі Драконячої Луски винагородить за будь-який повернутий артефакт." }
    t[200444] = { name = "Оплічник Брамниці", fen = "Guarding the Great Tree was a vital but lonely duty. Whispers grow louder when one dreams alone.", fua = "Охороняти Великий Дерево було важливим, та самотнім обов'язком. Шепоти гучнішають, коли мариш на самоті." }
    t[200445] = "Щасливий Мисливський Амулет"
    t[200446] = { name = "Кристалізований сигіл", fen = "In the end, all of Shandaral paid the price for the mages' arrogance.", fua = "Зрештою весь Шандарал заплатив за пиху магів." }
    t[200447] = { name = "Мисливський трофей кентаврів", fen = "Can be turned in to Hunt Instructor Basku in Maruukai to increase your standing with the Maruuk Centaurs.", fua = "Можна віддати інструктору полювання Баску в Маруукаї, аби підвищити вашу репутацію серед кентаврів Маруук." }
    t[200448] = { name = "Безодній оберіг", fen = "The wise sailor protects both body and mind from that which lurks below.", fua = "Мудрий моряк захищає і тіло, і розум від того, що чаїться в глибині." }
    t[200449] = { name = "Священний тотем тускарів", fen = "Stolen from the Iskaara Tuskarr, Elder Poa would reward you if you returned it to them.", fua = "Викрадений в іскаарських тускарів. Старійшина Поа винагородить вас, якщо ви повернете його." }
    t[200450] = { name = "Реліквія титанів", fen = "The relic is very old and clearly of titan origin. This is the type of relic that Lead Titan Researcher Sorotis asked you to bring to her.", fua = "Реліквія дуже стара й вочевидь титанічного походження. Саме такі реліквії просила вас принести головна дослідниця титанів Соротіс." }
