    t[200628] = { name = "Сяк-Так Стабілізована Арканна Сила", fen = "Unstable energies are doing their best to pretend to be stable, because you expect them to.", fua = "Нестабільні енергії щосили вдають із себе стабільні, бо ти цього від них очікуєш." }
    t[200631] = { name = "Весела Тускарська Гульня", fen = "After an arduous day of saving lives, only one thing's left to do. Tuskarr dance party!", fua = "Після виснажливого дня рятування життів лишається одне. Танцювальна вечірка тускарів!" }
