    t[200648] = { name = "Стихійне Розколювання", fen = "Shatter an Awakened element to gain its power.\n\n\n\nCan only be performed in the Dragon Isles.", fua = "Розбий Пробуджену стихію, щоб дістати її силу.\n\n\n\nМожливо лише на Драконових Островах." }
