    t[200670] = { name = "Туманодотичний Камінь Брами", fen = "Cool to the touch. The sound of rushing water fills your ears as you hold onto this stone.", fua = "Прохолодний на дотик. Шум стрімкої води сповнює твої вуха, коли ти тримаєш цей камінь." }
    t[200671] = { name = "Земляний Камінь Брами", fen = "Sharp and rough. The sound of the earth splitting is deafening while holding this stone.", fua = "Гострий і шорсткий. Звук землі, що розколюється, оглушливий, коли тримаєш цей камінь." }
    t[200672] = { name = "Крижанокований Камінь Брами", fen = "Your hands want to recoil from the cold emanating from this stone.", fua = "Твої руки хочуть відсахнутися від холоду, що струмує з цього каменя." }
    t[200673] = "Ікла та Пазурі Беогоки"
    t[200674] = { name = "М'ясо Синьодзьоба", fen = "A firm slab of duck meat perfect for using in a trap.", fua = "Тверда пластина качиного м'яса, ідеальна для приманки в пастці." }
    t[200675] = "Скупчення Стихійного Надлишку"
    t[200676] = { name = "Наелектризована Луска", fen = "It's still sparking. What could go wrong?", fua = "Вона все ще іскрить. Що може піти не так?" }
    t[200677] = "Пелюстка Мрійоцвіту"
    t[200678] = { name = "Сноцвіт", fen = "You suspect it will be a while before you find a fully grown Dreambloom again.", fua = "Ти підозрюєш, що мине чимало часу, перш ніж ти знову знайдеш повністю розквітлий сноцвіт." }
    t[200679] = "Сутність Тіні Сомнікуса"
    t[200681] = { name = "Он Лайт", fen = "The Maruuk Centaur beer of choice. Traditionally served on a horn from the hunt.", fua = "Улюблене пиво кентаврів маруків. Традиційно подається в розі, здобутому на полюванні." }
    t[200682] = "Наплічники із Загартованої Луски"
    t[200683] = { name = "Поножі Глибинних Пластів", fen = "The deeper, the stronger.", fua = "Що глибше, то міцніше." }
    t[200684] = { name = "Смарагдовий Хвостовий Хребець", fen = "A portion of a green dragon's spine, once used by a giant as a dagger.", fua = "Частина хребта зеленого дракона, що її колись використовував велетень як кинджал." }
    t[200685] = { name = "Зачарований Компас", fen = "It doesn't point North, but stubbornly insists you head in a very specific direction.", fua = "Вона вказує не на північ, а вперто наполягає, щоб ви рушили в одному цілком конкретному напрямку." }
    t[200686] = { name = "Первісний Фокус", fen = "Used to make an Optional Reagent for crafting heroically powerful equipment.", fua = "Використовується для виготовлення опціонального реагенту для створення героїчно потужного спорядження." }
    t[200687] = "Наручі з Грозового Сланцю"
    t[200688] = "Штани Звивистих Вітрів"
    t[200689] = { name = "Перстень Інеїстого Кігтя", fen = "Elemental power sleeps within, awaiting a tarasek bearer.", fua = "Усередині дрімає стихійна сила, що чекає на носія-тарасека." }
    t[200690] = { name = "Пелюстки Ритереми", fen = "Ground into a fine powder the Ritherem Petals act as a natural clotting agent.", fua = "Перетерті на тонкий порошок, пелюстки ритереми діють як природний кровоспинний засіб." }
    t[200691] = { name = "Колючки Кігтистого Будяка", fen = "The barb tips have a natural numbing agent that is used by the Maruuk in medical treatments.", fua = "Кінчики колючок містять природний знеболювальний засіб, що його маруки використовують у лікуванні." }
    t[200692] = { name = "Дарунок Гаю", fen = "Extracts from the plant can be used to enhance the effectiveness of poultices, reducing the healing time for large cuts and abrasions.", fua = "Витяжки з рослини посилюють дію припарок, скорочуючи час загоєння глибоких порізів і саден." }
    t[200693] = { name = "Листя Терати", fen = "The oil in the leaves of the Terata plant can be used to sooth burns.", fua = "Олію з листя рослини терата можна використовувати, щоб гоїти опіки." }
    t[200694] = { name = "Цибулини Річкового Дзвоника", fen = "The rejuvenating waters of the Ohn'ahran River infuse the bulbs with natural minerals, used widely on the plains as vitamins.", fua = "Відживлювальні води ріки Он'агра наповнюють цибулини природними мінералами; на рівнинах їх широко вживають як вітаміни." }
    t[200695] = { name = "Пелюстки Іклоцвіту", fen = "Extremely poisonous, the centaur of the plains use a paste made from the flowers petals to poison their arrows for big game hunts.", fua = "Надзвичайно отруйні; кентаври рівнин роблять із пелюсток цієї квітки пасту, щоб отруювати стріли для полювання на велику дичину." }
    t[200696] = { name = "Зимові Ягоди", fen = "Thriving in the cold climate of the Azure Span, the berries are high in sugars and traded widely across the Dragon Isles.", fua = "Розквітають у холодному кліматі Лазурового Простору; багаті на цукри, ними широко торгують на Драконових Островах." }
    t[200697] = { name = "Гнилогриб", fen = "Born of blight, this mushroom is poisonous in large quantities, but when steeped in small doses it is a great pain reliever.", fua = "Народжений гниллю, цей гриб отруйний у великих кількостях, але заварений малими дозами — чудово втамовує біль." }
    t[200698] = { name = "Сила-Сфера", fen = "When picked near maturity, the orb can be ground into a powder that can produce a dazzling and distracting mist.", fua = "Зірвана незадовго до зрілості, сфера перетирається на порошок, що здатен здійняти сліпучу й відволікаючу імлу." }
    t[200699] = { name = "Волокна Ласкавця", fen = "Used to line winter clothes and insulating cold weather dwellings.", fua = "Ними підбивають зимовий одяг та утеплюють оселі в холодному кліматі." }
    t[200700] = { name = "Ягоди Купресси", fen = "The oils of the berry like cones are used commonly as a diuretic but can be distilled into a piney alcohol.", fua = "Олії з цих ягодоподібних шишок зазвичай уживають як сечогінний засіб, але з них можна перегнати алкоголь із сосновою ноткою." }
    t[200701] = { name = "Золотавий Екстракт", fen = "The hearty auburn gold pigment is used almost exclusively in Titan architecture and outdoor painting.", fua = "Насичений рудувато-золотий пігмент використовують майже виключно в архітектурі титанів і для зовнішнього розпису." }
    t[200702] = { name = "Багряний Золотавий Екстракт", fen = "A variety of the classic Titian Orchid, it must be bred to keep its deep purple hue.", fua = "Різновид класичної золотавої орхідеї; її треба виводити осібно, щоб зберегти глибокий пурпуровий відтінок." }
    t[200703] = { name = "Волокна Виткої Квітки", fen = "The fibers of the vine flower are stretchy but strong, enough wound together make a great rope material.", fua = "Волокна виткої квітки гнучкі, але міцні; якщо сплести їх достатньо, вийде чудовий матеріал для мотузки." }
    t[200704] = { name = "Насінина Гратони", fen = "Crushed into a paste, the oils are a great moisturizer for scaled beings.", fua = "Розтерті на пасту, олії з насіння чудово зволожують луската істот." }
    t[200705] = { name = "Корінь Талдраззуса", fen = "Ground and made into a tea it used as a sleeping draught, in higher doses as a sedative for medical treatment.", fua = "Перемелений і заварений у чай, він править за снодійне, а у вищих дозах — за заспокійливе для лікування." }
    t[200707] = { name = "Шафа Нескінченних Плащів", fen = "When meeting the Black Prince, you must present the proper image.", fua = "Зустрічаючи Чорного Принца, ти маєш справити належне враження." }
