    t[200862] = { name = "Експериментальний Корм для Качок", fen = "Causes peculiar behavior in small waterfowl while in Valdrakken. Definitely not for consumption by others.", fua = "Спричиняє дивну поведінку малих водоплавних птахів у Валдраккені. Точно не призначений для споживання іншими." }
    t[200863] = { name = "Мерехтливе Скупчення Ноздориту", fen = "A truly remarkable collection of magical gemstones. This is a crucial component for Jewelcrafters to create a Jeweled Amber Whelpling.", fua = "Воістину дивовижна добірка магічних самоцвітів. Це ключовий складник, з якого ювеліри створюють Самоцвітного Бурштинового Дракончика." }
