    t[200865] = { name = "Мерехтливе Скупчення Ізумруду", fen = "A truly remarkable collection of magical gemstones. This is a crucial component for Jewelcrafters to create a Jeweled Emerald Whelpling.", fua = "Воістину дивовижна добірка магічних самоцвітів. Це ключовий складник, з якого ювеліри створюють Самоцвітного Смарагдового Дракончика." }
    t[200866] = { name = "Мерехтливе Скупчення Малигіту", fen = "A truly remarkable collection of magical gemstones. This is a crucial component for Jewelcrafters to create a Jeweled Sapphire Whelpling.", fua = "Воістину дивовижна добірка магічних самоцвітів. Це ключовий складник, з якого ювеліри створюють Самоцвітного Сапфірового Дракончика." }
