    t[200929] = { name = "Незгасний Нектар", fen = "Used by denizens of the Dragon Isles as a light source, the glow will last for many days.", fua = "Мешканці Драконових Островів використовують його як джерело світла; сяйво триває багато днів." }
    t[200931] = { name = "Заклітнена Вогняна Душа", fen = "A fiery soul is detained within. You may crush the cage early to snuff out the elemental and receive its awakened essence, or wait until it becomes docile.", fua = "Усередині ув'язнена вогняна душа. Ви можете завчасно розтрощити клітку, щоб згасити стихію й отримати її пробуджену сутність, або зачекати, доки душа стане сумирною." }
    t[200932] = { name = "Заклітнена Повітряна Душа", fen = "An airy soul is detained within. You may crush the cage early to snuff out the elemental and receive its awakened essence, or wait until it becomes docile.", fua = "Усередині ув'язнена повітряна душа. Ви можете завчасно розтрощити клітку, щоб згасити стихію й отримати її пробуджену сутність, або зачекати, доки душа стане сумирною." }
