    t[201398] = { name = "Моґуанська Моцарела", fen = "Hailing from before the Pandaren Revolution, this cheese was a key component of an ancient Mogu favorite, Stuffed Lushrooms.", fua = "Цей сир походить із часів до Пандаренської революції й був ключовою складовою давнього улюбленого моґуанського наїдку — фаршированих ситогрибів." }
    t[201399] = { name = "Хребет Первісного Ведмедя", fen = "A hulking spine from the bears of the Dragon Isles.", fua = "Здоровенний хребет із ведмедів Драконових островів." }
    t[201400] = { name = "Водна Паща", fen = "A massive, toothy jaw obtained from large fish native to the Dragon Isles.", fua = "Велетенська зубата щелепа, здобута з великих риб, рідних для Драконових островів." }
    t[201401] = { name = "Райдужна Пір'їна", fen = "A brilliant feather plucked from the harpies and large birds of the Dragon Isles.", fua = "Блискуча пір'їна, висмикнута з гарпій та великих птахів Драконових островів." }
    t[201402] = { name = "Велика Міцна Стегнова Кістка", fen = "A hefty thigh bone retrieved from the bruffalon native to the Dragon Isles.", fua = "Важка стегнова кістка, здобута з бруффалонів, рідних для Драконових островів." }
    t[201403] = { name = "Бивень Мастодонта", fen = "A durable tusk taken from the mammoths of the Dragon Isles.", fua = "Міцний бивень, узятий від мамутів Драконових островів." }
    t[201404] = { name = "Сухожилля Високоступа", fen = "A bit of fibrous tissue gathered from the tallstriders of the Dragon Isles.", fua = "Шматочок волокнистої тканини, зібраний із високоступів Драконових островів." }
    t[201405] = { name = "Жмут Первісної Вовни", fen = "A tuft of fuzzy wool from the argali and musken that live on the Dragon Isles.", fua = "Жмут пухнастої вовни з аргалі та мускенів, що живуть на Драконових островах." }
    t[201406] = { name = "Сяйлива Сфера Титанів", fen = "A mysterious orb thrumming with energy found in possession of a titan watcher on the Dragon Isles.", fua = "Загадкова сфера, що пульсує енергією, знайдена у володінні охоронця титанів на Драконових островах." }
    t[201407] = { name = "Прилад: Дугосвітлові Життєві Коректори", fen = "Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.", fua = "Якість майстрування та спеціалізація в інженерії впливають на шанс успіху. Ця гарантія діє лише для спорядження Драконових Островів." }
    t[201408] = { name = "Прилад: Дугосвітлові Життєві Коректори", fen = "Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.", fua = "Якість майстрування та спеціалізація в інженерії впливають на шанс успіху. Ця гарантія діє лише для спорядження Драконових Островів." }
    t[201409] = { name = "Прилад: Дугосвітлові Життєві Коректори", fen = "Tinker quality and engineering specialization impact success chance. This warranty only applies to Dragon Isles equipment.", fua = "Якість майстрування та спеціалізація в інженерії впливають на шанс успіху. Ця гарантія діє лише для спорядження Драконових Островів." }
    t[201410] = { name = "Могутня Фіолетова Штука", fen = "It must be good... that's why it costs so much!", fua = "Воно мусить бути добрим... тому й коштує так дорого!" }
    t[201411] = { name = "Артефакт Стародавнього Сховища", fen = "This artifact appears to date back to the time of the Incarnates. Lillian Brightmoon of the Dragonscale Expedition would be interested in this item.", fua = "Цей артефакт, схоже, сягає часів Втілених. Ліліан Брайтмун із Драколускої експедиції зацікавиться цим предметом." }
    t[201412] = { name = "Артефакт Стародавнього Сховища", fen = "This artifact dates back to when the Incarnates were imprisoned. Lillian Brightmoon of the Dragonscale Expedition would be interested in this item.", fua = "Цей артефакт походить із часів, коли Втілених ув'язнили. Ліліан Брайтмун з Експедиції Драконячої Луски неодмінно ним зацікавиться." }
    t[201413] = { name = "Буррата, Просякнута Вічністю", fen = "Infused with water from the Well of Eternity itself, this treat was once highly prized amongst the Kaldorei. Prior to the Sundering, of course.", fua = "Просякнута водою із самого Джерела Вічності, ця ласощ колись високо цінувалася серед калдорай. Звісно, до Розколу." }
    t[201415] = { name = "Часовий Пармезан", fen = "Untethered from time, this Parmesan has a nifty habit of materalizing on your pasta ahead of schedule.", fua = "Не прив'язаний до часу, цей пармезан має кумедну звичку матеріалізуватися на вашій пасті завчасно." }
    t[201416] = { name = "Брунуст Чорної Імперії", fen = "If you hold this foul-smelling cheese up to your ear, you can hear a strange whispering. Plus, it's high in fat.", fua = "Якщо піднести цей смердючий сир до вуха, можна почути дивний шепіт. До того ж, він дуже жирний." }
    t[201417] = { name = "Сирне Очищення Стратгольма", fen = "This entire dairy must be purged! It's the only whey.", fua = "Усю цю молочарню треба очистити! Це єдиний сирний шлях." }
    t[201419] = { name = "Апексисовий Азіаго", fen = "Perfected by Anhari and Skalaxi scholars, the Apexis crystal containing this cheese's recipe has long since been lost.", fua = "Удосконалений дослідниками анхарі та скалаксі, апексисовий кристал із рецептом цього сиру давно втрачений." }
    t[201422] = { name = "Швидкозаморожене М'ясо", fen = "Frozen at the peak of freshness.", fua = "Заморожене на піку свіжості." }
