    t[202667] = { name = "Запечатаний Сувій про Артефакт", fen = "A magically sealed scroll regarding the location of a forgotten artifact in the Forbidden Reach, as catalogued by the blue dragon, Lapisagos. This may be of interest to the Dragonscale Expedition.", fua = "Магічно запечатаний сувій про місцезнаходження забутого артефакта в Забороненому Сягненні, як його занотував синій дракон Лапісагос. Це може зацікавити Драконолуску Експедицію." }
    t[202668] = { name = "Запечатаний Сувій про Духа", fen = "A magically sealed scroll regarding the location of a spirit beast in the Forbidden Reach, as catalogued by the blue dragon, Lapisagos. This may be of interest to the Maruuk Centaur.", fua = "Магічно запечатаний сувій про місцезнаходження звіра-духа в Забороненому Сягненні, як його занотував синій дракон Лапісагос. Це може зацікавити кентаврів Маруків." }
    t[202669] = { name = "Запечатаний Сувій про Рибу", fen = "A magically sealed scroll regarding the location of a rare fish within the Forbidden Reach, as catalogued by the blue dragon, Lapisagos. This may be of interest to the Iskaara Tuskarr.", fua = "Магічно запечатаний сувій про місцезнаходження рідкісної риби в Забороненому Сягненні, як його занотував синій дракон Лапісагос. Це може зацікавити тускарів Іскаари." }
    t[202670] = { name = "Запечатаний Сувій Знання", fen = "A magically sealed scroll regarding the location of hidden knowledge in the Forbidden Reach, as catalogued by the blue dragon, Lapisagos. This may be of interest to the Valdrakken Accord.", fua = "Магічно запечатаний сувій про місцезнаходження прихованого знання в Забороненому Сягненні, як його занотував синій дракон Лапісагос. Це може зацікавити Валдраккенський Договір." }
