    t[202690] = { name = "Декоративний Кущ", fen = "A nicely-shaped shrub with a certain pizzazz.", fua = "Гарно сформований кущ із певним шармом." }
    t[202691] = "Сумочка Генрі"
    t[202692] = { name = "Ціп Гнолячого Лиходія", fen = "Gnoll jaws break bones easy, they use these just for the fun of it.", fua = "Гнолячі щелепи легко трощать кістки — цим вони користуються лише задля забави." }
    t[202693] = { name = "Пиріг з Драконфрукта", fen = "Flame-baked with love.", fua = "Спечений на полум'ї з любов'ю." }
    t[202694] = { name = "Родючий Ґрунт", fen = "Enriched with nutrients from the Dream.", fua = "Збагачений поживними речовинами зі Сну." }
    t[202695] = { name = "Прадавня Вода", fen = "The water seems to stay the perfect, refreshing temperature.", fua = "Вода ніби завжди тримає ідеальну, освіжаючу температуру." }
    t[202696] = { name = "Заспокійливе Каченя", fen = "A soft plush that has been loved by many hatchlings.", fua = "М'яка плюшева іграшка, яку любило чимало малят." }
    t[202697] = { name = "Багряна Подушка", fen = "The pinnacle of whelp comfort.", fua = "Вершина драконячого затишку." }
    t[202698] = { name = "Голос Драконів 4: Сила і Право", fen = "The dragons have ruled us because theY're stronger than we. But together, in our great numbers, we're stronger than they. If might makes right, then we are right, if we haVe courage to riSe up together. - Instigator Belaphon", fua = "Дракони правили нами, бо вони сильніші за нас. Та разом, у своїй незліченності, ми сильніші за них. Якщо сила дає право, то ми маємо рацію — варто лиш набратися відваги повстати спільно. — Підбурювачка Белафон" }
    t[202699] = { name = "Голос Драконів 2: Сто Сторіч Покинутості", fen = "FoR 100 Years, theY left us alone, while we tended to \"their\" isles, guarded \"their\" cities and roads, and kept the peace. TheY haVe repeated that abandonment 99 more times. Should we welcome them with open arms, and obey as before? - Instigator Belaphon", fua = "Сто років вони лишали нас самих, поки ми дбали про «їхні» острови, боронили «їхні» міста й дороги та берегли мир. І вони повторювали цю зраду ще дев'яносто дев'ять разів. То чи маємо ми зустрічати їх із розпростертими обіймами й коритися, як раніше? — Підбурювачка Белафон" }
    t[202700] = { name = "Голос Драконів 3: Сто Сторіч Незалежності", fen = "The dragons returned expecting us to Be what we were, but in tHose 100 Centuries, we changed. We grew. We serve them no longer, and are serFs no longer. We've chosen our Path for 10,000 years, and we will do so again. - Instigator Belaphon", fua = "Дракони повернулися, гадаючи, що ми лишилися такими, як були, та за ці сто сторіч ми змінилися. Ми зросли. Ми більше їм не служимо й більше не кріпаки. Десять тисяч років ми самі обирали свій шлях — і знову так вчинимо. — Підбурювачка Белафон" }
    t[202701] = { name = "Голос Драконів 5: Кодекс Бунтаря", fen = "And so we Swear one and all to the rebel code. No ruler but one's selF. No purpose but independence. No flight but the flightless. - Instigator Belaphon", fua = "І так ми всі до одного присягаємо на кодекс бунтаря. Жодного володаря, крім себе самого. Жодної мети, крім незалежності. Жодного зграї, крім безкрилих. — Підбурювачка Белафон" }
    t[202702] = { name = "Голос Драконів 1: Чого Вартий Дракон", fen = "The dragons believE they're worth more than us. That's why Sendrax had to sacrifice herself, foR a dragon egg that might not even be viable. They say she's a herO, but she's really their victim. - Instigator Belaphon", fua = "Дракони вважають, що вони варті більше за нас. Тому Сендракс мусила пожертвувати собою заради драконячого яйця, яке, може, навіть нежиттєздатне. Кажуть, вона героїня, та насправді вона їхня жертва. — Підбурювачка Белафон" }
    t[202703] = { name = "Ефемерний Пісок", fen = "The grains of sand disappear as you watch it.", fua = "Піщинки зникають просто на ваших очах." }
    t[202705] = { name = "Слиз Равлика", fen = "Slime collected from snails that is perfect for making incense", fua = "Слиз, зібраний з равликів, ідеально підходить для виготовлення пахощів." }
    t[202711] = { name = "Загублений Компас", fen = "And though one foot sits firm and centered, the circle is complete as the other ends where it began.", fua = "І хоч одна ніжка стоїть твердо в центрі, коло замикається, коли друга завершує там, де почала." }
    t[202712] = "Гумова Рибка"
    t[202713] = { name = "Розкидані припаси", fen = "Some of Jeb and Tacha's expedition gear.", fua = "Дещо зі спорядження Джеба й Тачі для експедиції." }
