    t[202855] = { name = "Перстень Стихійного Сковування Малдри", fen = "Maldra has infused this ring with the elemental binding spell that was used against her in the Misty Vale.", fua = "Малдра наповнила цей перстень закляттям стихійного сковування, яке застосували проти неї в Імлистій Долині." }
