    t[202868] = "Сигнал Цілителя"
    t[202869] = { name = "Палючий Ключ", fen = "Heated by the corebeast's body. Almost too hot to hold!", fua = "Розжарений тілом ядрозвіра. Майже надто гарячий, щоб тримати!" }
    t[202870] = { name = "Таємничі Письмена", fen = "A transcription of coded secrets copied from a tome written by Neltharion. Can be traded to an envoy of the Valdrakken Accord in the Forbidden Reach.", fua = "Запис закодованих таємниць, переписаний із фоліанта, написаного Нелтаріоном. Можна обміняти в посланця Валдраккенського Договору у Забороненому Сягненні." }
    t[202871] = { name = "Драконівський Артефакт", fen = "A carefully packaged artifact related to the legacy of the dracthyr. Can be traded to an envoy of the Dragonscale Expedition in the Forbidden Reach.", fua = "Дбайливо запакований артефакт, пов'язаний зі спадщиною драктирів. Його можна обміняти в посланця Драколускої Експедиції у Заборонених Межах." }
    t[202872] = { name = "Жетон Благословення", fen = "A sign of fortune granted by Ohn'ahra. Can be traded to an envoy of the Maruuk Centaur in the Forbidden Reach.", fua = "Знак удачі, дарований Он'агрою. Можна обміняти в посланця кентаврів Маруків у Забороненому Сягненні." }
    t[202873] = { name = "Зрізок Похилого Гриба", fen = "This squishes in your hand as you transfer it to a bag, it will make an excellent poultice.", fua = "Він чавиться в руці, коли ви кладете його в торбу — з нього вийде чудовий припарок." }
    t[202874] = { name = "Цілющий Напій", fen = "'Pour directly down the throat for maximum effectiveness.'", fua = "«Для якнайбільшої дієвості вливай просто в горлянку.»" }
    t[202875] = "Ласо для Слимаків"
    t[203012] = { name = "Зелений Серцекристал", fen = "It is warm to the touch, and hums with a delicate tone.", fua = "Теплий на дотик, гуде ніжним переливом." }
    t[203013] = { name = "Ладан Ніффенів", fen = "Take a whiff to find the trail!", fua = "Понюхайте, щоб натрапити на слід!" }
    t[203183] = { name = "Незгасла Сутність Синдрагоси", fen = "You hear screams of agony and rage from this small essence. The last remnants of Sindragosa are within, crying out for her torment to be quelled.", fua = "З цієї маленької сутності лунають крики муки та люті. Усередині — останні рештки Синдрагоси, що благають угамувати її муку." }
    t[203184] = { name = "Незгасла Сутність Малігоса", fen = "You hear screams of agony and rage from this small essence. Malygos, the former aspect of magic, still remains trapped in his fury.", fua = "З цієї маленької сутності лунають крики муки та люті. Малігос, колишній аспект магії, досі лишається в полоні своєї нестями." }
    t[203206] = { name = "Витончений Пензель для Полотна", fen = "With long flowing bristles framed by sculpted gold, even a novice can tell that this was crafted by a true master.", fua = "З довгими спадними щетинками в оправі з різьбленого золота — навіть новачок збагне, що цей пензель створив справжній майстер." }
    t[203210] = { name = "Скриня Припасів Драконолускої Експедиції", fen = "Contains Dragon Isles Supplies and other rewards for assisting the Dragonscale Expedition in the Forbidden Reach.", fua = "Містить припаси Драконових Островів та інші нагороди за допомогу Драконолускій Експедиції у Забороненому Сягненні." }
