    t[203222] = { name = "Лишковий Згорток Маруків", fen = "Contains Dragon Isles Supplies and other rewards for assisting the Maruuk Centaur in the Forbidden Reach.", fua = "Містить припаси Драконових Островів та інші нагороди за допомогу кентаврам Маруків у Забороненому Сягненні." }
    t[203223] = { name = "Скринька Припасів Валдраккена", fen = "Contains Dragon Isles Supplies and other rewards for assisting the Valdrakken Accord in the Forbidden Reach.", fua = "Містить припаси Драконових Островів та інші нагороди за допомогу Валдраккенській Згоді у Заборонених Межах." }
    t[203224] = { name = "Скриня Надлишків Валдраккена", fen = "Contains Dragon Isles Supplies and other rewards for assisting the Valdrakken Accord in the Forbidden Reach.", fua = "Містить припаси Драконових Островів та інші нагороди за допомогу Валдраккенській Згоді у Заборонених Межах." }
    t[203226] = { name = "Грозозлитий Саламандер", fen = "Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location.", fua = "Навчає викликати цей засіб пересування. Цей засіб пересування змінюється залежно від вашої навички верхової їзди та місцезнаходження." }
    t[203228] = { name = "Дика Блакитна Далечінь", fen = "Brilliant and unfathomably blue, these flowers radiate an energy that fills you with joy and hope.", fua = "Осяйні й неосяжно блакитні, ці квіти випромінюють енергію, що сповнює тебе радістю й надією." }
    t[203229] = { name = "Слиз Равлика", fen = "Smells... like nothing, actually. To you.", fua = "Пахне... насправді нічим. Для тебе." }
