    t[203378] = { name = "Техніка: Медальйон Багряного Бійця", fen = "Teaches you how to craft Crimson Combatant's Medallion.", fua = "Навчає тебе виготовляти Медальйон Багряного Бійця." }
    t[203379] = { name = "Техніка: Відзнака Запалу Багряного Бійця", fen = "Teaches you how to craft Crimson Combatant's Insignia of Alacrity.", fua = "Навчає тебе виготовляти Відзнаку Запалу Багряного Бійця." }
    t[203380] = { name = "Техніка: Емблема Багряного Бійця", fen = "Teaches you how to craft Crimson Combatant's Emblem.", fua = "Навчає тебе виготовляти Емблему Багряного Бійця." }
    t[203381] = { name = "Запечатаний Лист до Нелтаріона", fen = "A perfumed scent emanates from the letter... centuries old... yet oddly familiar.", fua = "Від листа лине запах парфумів... віком у століття... і все ж дивно знайомий." }
    t[203382] = "Проектори Бічного Зору"
    t[203383] = { name = "Нотатки про Рівноправ'я Драконідів", fen = "Shows the dragonkin that Alexstrasza is planning to make changes.", fua = "Показують драконідам, що Алекстраза планує впровадити зміни." }
    t[203385] = { name = "Руна Вогнезору", fen = "The totem dims as you remove this rune. They seem to be attuned to each other.", fua = "Тотем тьмяніє, коли ти знімаєш цю руну. Схоже, вони налаштовані одне на одного." }
    t[203386] = { name = "Коробка Крекерів зі Стрибучої Кукурудзи", fen = "A box of crackers branded with The Roasted Ram.", fua = "Коробка крекерів з маркою «Смаженого Барана»." }
    t[203387] = { name = "Дивно Знайома Тренувальна Зброя", fen = "You're pretty sure you discarded this ages ago when trying to make more room in your bags. It was a trusty old friend.", fua = "Ти майже впевнений, що викинув це сто років тому, намагаючись звільнити більше місця в торбах. То був надійний старий друг." }
    t[203388] = { name = "Брудна Відзнака", fen = "The symbol has almost completely faded, but maybe the Kirin Tor will find it historically significant.", fua = "Символ майже повністю стерся, але, можливо, Кірін-Тор визнає його історично значущим." }
    t[203389] = { name = "Блискучий Камінь", fen = "It's shiny, so it must be important, right?!", fua = "Він блискучий, отже, мабуть, важливий, чи не так?!" }
    t[203390] = { name = "Перстень Стихійного Сковування Малдри", fen = "Maldra has infused this ring with the elemental binding spell that was used against her in the Misty Vale.", fua = "Малдра наповнила цей перстень закляттям стихійного сковування, яке застосували проти неї в Імлистій Долині." }
    t[203391] = { name = "Пом'ятий Дворфійський Кишеньковий Годинник", fen = "An engraving on the back bears the name \"Professor Lichenrock\".", fua = "Гравірування на звороті містить ім'я «Професор Лікенрок»." }
    t[203392] = { name = "Стара Скалка Дзеркала", fen = "It's still you, despite everything.", fua = "Це все ще ти, попри все." }
    t[203393] = { name = "Губчастий Землегриб", fen = "The pores on this mushroom make it ideal for soaking up toxins, for good or for ill.", fua = "Пори цього гриба роблять його ідеальним для всотування токсинів, на добро чи на зло." }
    t[203394] = { name = "Стихійно Заряджена Сфера", fen = "A curious orb-shaped artifact that appears to be of titanic origin. However, a glow of elemental power emanates from within.", fua = "Цікавий артефакт у формі сфери, що видається титанічного походження. Однак зсередини променіє сяйво стихійної сили." }
    t[203395] = { name = "Дослідницький Журнал", fen = "The journal is in remarkable condition given its age. The notes within will no doubt keep Dragonscale scholars busy for years to come.", fua = "Як на свій вік, щоденник у разюче доброму стані. Нотатки в ньому, поза сумнівом, не один рік даватимуть роботу книжникам Драконолускової експедиції." }
    t[203396] = { name = "Виставлений Елемент Обладунку", fen = "This appears to be of black dragon design, but is much smaller than expected. Could it be an early example of dracthyr armor?", fua = "Схоже, це виріб чорних драконів, але набагато менший, ніж очікувалося. Чи може це бути ранній зразок обладунку драктирів?" }
    t[203398] = { name = "Приглушувальний Порошок", fen = "Dropped from creatures in the Forbidden Reach. Only a skilled alchemist could figure out how to use this ingredient for something useful.", fua = "Випадає зі створінь у Заборонених Межах. Лише вправний алхімік міг би придумати, як використати цей інгредієнт для чогось корисного." }
    t[203399] = { name = "Пошкоджений Тризуб", fen = "Dropped from creatures in the Forbidden Reach. Only a skilled blacksmith could restore this trident.", fua = "Випадає зі створінь у Заборонених Межах. Лише вправний коваль міг би відновити цей тризуб." }
    t[203400] = { name = "Несмачні Спеції", fen = "Dropped from creatures in the Forbidden Reach. A skilled chef might be able to save these flavors.", fua = "Випадають зі створінь у Заборонених Межах. Вправний кухар, можливо, зміг би врятувати ці смаки." }
    t[203401] = { name = "Тьмяний Кристал", fen = "Dropped from creatures in the Forbidden Reach. A skilled enchanter might find a use for this gem.", fua = "Випадає зі створінь у Заборонених Межах. Вправний зачарувальник міг би знайти застосування цьому самоцвіту." }
    t[203402] = { name = "Зламаний Гномський Голосник", fen = "Dropped from creatures in the Forbidden Reach. A skilled engineer might be able to repair this.", fua = "Випадає зі створінь у Заборонених Межах. Вправний інженер, можливо, зміг би це полагодити." }
    t[203403] = { name = "Нашвидкуруч Накреслена Руна", fen = "Dropped from creatures in the Forbidden Reach. A skilled scribe could clean up the linework and make this rune functional.", fua = "Випадає зі створінь у Заборонених Межах. Вправний писар міг би підправити лінії й зробити цю руну дієвою." }
    t[203404] = { name = "Кристалева Виделка", fen = "Dropped from creatures in the Forbidden Reach. A skilled jewelcrafter could make this tuning fork sing.", fua = "Випадає зі створінь у Заборонених Межах. Вправний ювелір міг би змусити цей камертон заспівати." }
    t[203405] = { name = "Бездоганна Шкура", fen = "Dropped from creatures in the Forbidden Reach. A skilled leatherworker might be able to turn this into something useful.", fua = "Випадає зі створінь у Заборонених Межах. Вправний чинбар, можливо, зміг би перетворити її на щось корисне." }
    t[203406] = { name = "Подертий Повітряний Змій Морквату", fen = "Dropped from creatures in the Forbidden Reach. A skilled tailor could mend this kite.", fua = "Випадає зі створінь у Заборонених Межах. Вправний кравець міг би полагодити цього змія." }
    t[203407] = { name = "Драконівський Приборкувальний Порошок", fen = "This solution is capable of countering certain efforts of Primalists in the Forbidden Reach. May trigger a special encounter.", fua = "Цей розчин здатен протидіяти певним зусиллям первісників у Заборонених Межах. Може спричинити особливу зустріч." }
    t[203408] = { name = "Стародавній Церемоніальний Тризуб", fen = "This trident isn't made of materials fit for combat--it seems ritualistic. Be careful where you place it in the Forbidden Reach. May trigger a special encounter.", fua = "Цей тризуб виготовлений з матеріалів, непридатних для бою, — він видається ритуальним. Будь обережний, де ти його кладеш у Заборонених Межах. Може спричинити особливу зустріч." }
    t[203409] = { name = "Мішечок Іскристих Спецій", fen = "The missing ingredient was love! The aroma is sensational. This is a wonderful taste from the Forbidden Reach. May trigger a special encounter.", fua = "Бракувало інгредієнта любові! Аромат сенсаційний. Це чудовий смак Заборонених Меж. Може спричинити особливу зустріч." }
    t[203410] = { name = "Сяйлива Кристалева Закладка", fen = "This glimmering bookmark is begging to be placed in a good book, like those found in the Forbidden Reach. May trigger a special encounter.", fua = "Ця мерехтлива закладка благає, щоб її поклали в добру книжку, як ті, що знаходять у Заборонених Межах. Може спричинити особливу зустріч." }
    t[203411] = { name = "Гномський Голосник", fen = "How did gnome tech even get to the Forbidden Reach? You'll need a buzzspire to play this on. May trigger a special encounter.", fua = "Як гномська техніка взагалі потрапила до Заборонених Меж? Щоб відтворити це, тобі знадобиться гудошпиль. Може спричинити особливу зустріч." }
    t[203412] = { name = "Чародійна Руна Розсіювання", fen = "After cleaning up the lines, you see this is a rune meant to dispel wards, like those used in the Forbidden Reach. May trigger a special encounter.", fua = "Підправивши лінії, ти бачиш, що це руна, призначена розсіювати обереги, як ті, що використовують у Заборонених Межах. Може спричинити особливу зустріч." }
    t[203413] = { name = "Кристалевий Камертон", fen = "Hitting the right crystal in the Forbidden Reach with this might produce a melodious note. May trigger a special encounter.", fua = "Якщо вдарити ним по правильному кристалу в Заборонених Межах, можна видобути мелодійну ноту. Може спричинити особливу зустріч." }
    t[203414] = { name = "Зміцнена Бездоганна Шкіра", fen = "These strengthened leather patches are often used by Morqut Tuskarr to fix up some damaged hides in the Forbidden Reach. May trigger a special encounter.", fua = "Ці латки зі зміцненої шкіри часто використовують тускари Морквату, щоб лагодити пошкоджені шкури в Заборонених Межах. Може спричинити особливу зустріч." }
    t[203415] = { name = "Традиційний Повітряний Змій Морквату", fen = "Some say the tuskarr kites tied to posts in the Forbidden Reach fly on the wings of spirits. May trigger a special encounter.", fua = "Дехто каже, що тускарські повітряні змії, прив'язані до стовпів у Заборонених Межах, ширяють на крилах духів. Може спричинити особливу зустріч." }
    t[203416] = { name = "Сплячі Насінини Життєцвіту", fen = "Gathered in the Forbidden Reach. Local insects are attracted to aroma of this special flower's bloom. May trigger a special encounter.", fua = "Зібрані в Заборонених Межах. Місцевих комах приваблює аромат цвіту цієї особливої квітки. Можуть спричинити особливу зустріч." }
    t[203417] = { name = "Гостра, як Бритва, Тваринна Кістка", fen = "Skinned from creatures in the Forbidden Reach. This bone should be useful for cutting rough pelts from beasts in the Reach. May trigger a special encounter.", fua = "Знята зі створінь Заборонених Меж. Ця кістка стане в пригоді для зрізання грубих шкур із бестій у Межах. Може спричинити особливу зустріч." }
    t[203418] = { name = "Підсилений Тремтливий Камінь", fen = "Gathered in the Forbidden Reach. This volatile stone could be used to push a rumbling mineral deposit in the Reach to its limit. May trigger a special encounter.", fua = "Зібраний у Заборонених Межах. Цей нестабільний камінь можна використати, щоб довести гуркітливе родовище мінералів у Межах до межі. Може спричинити особливу зустріч." }
    t[203419] = { name = "Невловний Квакаючий Краб", fen = "Caught in the Forbidden Reach. This noisy critter would make a good lure if you could find a local trap to put it in. May trigger a special encounter.", fua = "Спійманий у Заборонених Межах. Ця галаслива істотка стала б добрим принадою, якби ти знайшов місцеву пастку, куди її посадити. Може спричинити особливу зустріч." }
    t[203420] = { name = "Рецепт: Драконівський Приборкувальний Порошок", fen = "Teaches you how to craft a Forbidden Reach artisan curio.", fua = "Навчає тебе виготовляти ремісничу дивовижу Заборонених Меж." }
