    t[203432] = { name = "Мішок Гострих Ласощів для Улюбленців", fen = "Only a pet with a very strong constitution could enjoy one of these biscuits.", fua = "Лише улюбленець з дуже міцним здоров'ям зможе насолодитися одним із цих печивок." }
    t[203433] = { name = "Головка Брі «Драконячий Шепіт»", fen = "A light buttery cheese with hints of nuttiness.", fua = "Легкий вершковий сир з горіховими нотками." }
