    t[203442] = { name = "Слиз Равлика", fen = "Potent slime from an incense snail. This is used as the base ingredient for niffen incense.", fua = "Сильнодійний слиз равлика-кадильника. Він править за основу для ніффенських пахощів." }
    t[203443] = { name = "Коробка Крекерів зі Стрибучої Кукурудзи", fen = "A box of crackers from The Roasted Ram.", fua = "Коробка крекерів із «Смаженого барана»." }
    t[203444] = { name = "Бездонний Мішок Загальних Товарів Драконових Островів", fen = "Contains many common reagents shared between all professions. Still missing something? Check a nearby vendor!", fua = "Містить багато звичайних реагентів, спільних для всіх професій. Усе ще чогось бракує? Завітай до найближчого торговця!" }
    t[203445] = { name = "М'яка Лялька", fen = "A stuffed doll for any pet to enjoy.", fua = "М'яка лялька, що порадує будь-якого улюбленця." }
    t[203446] = { name = "Заспокійливі Пахощі", fen = "A range of comforting smells for the home.", fua = "Набір затишних ароматів для дому." }
    t[203447] = { name = "Бездонний Мішок Необов'язкових Товарів", fen = "Contains all of the stuff you could choose to ignore, but decided not to.", fua = "Містить усе те, що ти міг би й проігнорувати, але вирішив цього не робити." }
    t[203448] = { name = "Бездонний Мішок Руди", fen = "Contains plenty of ore, and nothing more.", fua = "Містить багато руди й нічого більше." }
    t[203449] = { name = "Бездонний Мішок Трав", fen = "Contains a shower of flowers.", fua = "Містить цілу зливу квітів." }
    t[203450] = { name = "Бездонний Мішок Шкур", fen = "Contains lots of skins, to help ensure your inevitable wins!", fua = "Містить багато шкур, щоб забезпечити твої неминучі перемоги!" }
    t[203451] = { name = "Декоративний Кущ", fen = "A nicely-shaped shrub with a certain pizzazz.", fua = "Гарно сформований кущ із певним шармом." }
    t[203453] = { name = "Тотем із Драконячої Кістки", fen = "Djaradin runes are carved into the bone.", fua = "У кістці вирізьблено руни джарадинів." }
    t[203454] = { name = "Спорядження Закалі", fen = "The accoutrements of ritualistic dragonkillers, meant for ceremony as much as for warfare.", fua = "Реманент ритуальних драконоборців, призначений як для церемоній, так і для війни." }
    t[203455] = { name = "Фетиш із Драконячих Зубів", fen = "A full set of young dragon teeth strung on a leather cord.", fua = "Повний набір зубів молодого дракона, нанизаних на шкіряний шнурок." }
    t[203456] = { name = "Обсидіанові Молитовні Чотки", fen = "A string of dark beads that leave the smell of smoke on your hands.", fua = "Низка темних намистин, що лишають на руках запах диму." }
    t[203457] = { name = "Мішечок Вулканічних Трав", fen = "The crushed herbs emit a faint crackling sound.", fua = "Подрібнені трави видають ледь чутне потріскування." }
    t[203458] = { name = "Роба з Луски Чорного Дракона", fen = "Thick vestments made from stitched layers of black dragonhide.", fua = "Цупке вбрання зі зшитих шарів шкіри чорного дракона." }
    t[203459] = { name = "Тотемні Руїни", fen = "Hacked pieces of petrified wood, iron, and fur.", fua = "Порубані шматки скам'янілого дерева, заліза та хутра." }
    t[203460] = { name = "Оніксовий Перстень", fen = "Forged of elementium, this enigmatic ring has three vacant slots.", fua = "Цей загадковий перстень, викуваний з елементію, має три порожні гнізда." }
    t[203461] = { name = "Хронологічно Перерозподілені Пайки", fen = "Sold at pre-inflation prices.", fua = "Продаються за цінами до інфляції." }
    t[203463] = { name = "Щоденник Атреноша", fen = "This rugged leatherbound tome contains rants about a soldier's life, violent descriptions of combat, and aspirational writing about weapons.", fua = "Цей міцний фоліант у шкіряній оправі містить тиради про солдатське життя, жорстокі описи боїв і захоплені роздуми про зброю." }
    t[203465] = { name = "Драконівський Артефакт", fen = "A carefully packaged artifact related to the legacy of the dracthyr. Can be traded to an envoy of the Dragonscale Expedition in the Forbidden Reach.", fua = "Дбайливо запакований артефакт, пов'язаний зі спадщиною драктирів. Його можна обміняти в посланця Драколускої Експедиції у Заборонених Межах." }
    t[203466] = { name = "Ящик Надлишків Драколускої Експедиції", fen = "Contains Dragon Isles Supplies and other rewards for assisting the Dragonscale Expedition in the Forbidden Reach.", fua = "Містить припаси Драконових Островів та інші нагороди за допомогу Драконолускій Експедиції у Забороненому Сягненні." }
