    t[203653] = { name = "Порожнє Стихійне Ядро", fen = "The dormant stone cools rapidly in your hand, waiting to bind to new magical energies.", fua = "Сплячий камінь швидко холоне у твоїй руці, чекаючи, щоб зв'язатися з новими магічними енергіями." }
