    t[203655] = { name = "Розмоклий Ключ", fen = "A wet and slimy key.", fua = "Мокрий і слизький ключ." }
    t[203656] = { name = "Дивний Пристрій", fen = "This device looks like a rod with a crystal on the end, with a handle to hold it by. It looks old, but is slightly familiar to you, like you have seen it in passing. Maybe it's of interest to Voraxian.", fua = "Цей пристрій схожий на стрижень із кристалом на кінці й руків'ям, за яке його тримають. Виглядає старим, але видається вам трохи знайомим, наче ви бачили його мимохідь. Можливо, це зацікавить Вораксіана." }
    t[203657] = { name = "Протиотрута від Токсину", fen = "A small bottle of antidote to combat the effects of the gasses rampant within the Support Creche.", fua = "Маленька пляшечка протиотрути, щоб подолати дію газів, що шаленіють у Допоміжному Виводку." }
