    t[203680] = "Кидок Тотема"
    t[203681] = { name = "Штормовий Сховок Первісників", fen = "Contains a Storm Sigil, Dragon Isles Supplies, Primalist treasures, and a chance for cosmetic Primalist weapons and armor.", fua = "Містить Сигіл Шторму, Припаси Драконових Островів, скарби первісників і шанс на оздобну зброю та броню первісників." }
    t[203682] = { name = "Затемнене Стихійне Осердя", fen = "Hissed voices tickle the back of your mind, half-words and hushed secrets.", fua = "Сичливі голоси лоскочуть закутки вашого розуму напівсловами й тихими таємницями." }
    t[203683] = { name = "Оберіг Фіракка", fen = "This series of customized fire protection tools will grant the wielder protection to interact with a Suffusion Mold. The wards are consumed upon use.", fua = "Цей набір особливих знарядь захисту від вогню дарує власнику захист, щоб взаємодіяти з Пронизливою Формою. Обереги зникають після використання." }
