    t[204249] = { name = "Перекладене Листування Чорних Драконів", fen = "A communication recorded over great distance between Adamanthia and Neltharion.", fua = "Спілкування, записане на великій відстані, між Адамантією та Нелтаріоном." }
    t[204250] = { name = "Камінь Прийому: Останнє Попередження", fen = "Tablet used to receive messages over great distances from a sending stone. Scalecommanders may find this of great interest.", fua = "Табличка для отримання послань на велику відстань від каменя надсилання. Лускокомандувачів це може вельми зацікавити." }
    t[204251] = { name = "Камінь Відправлення: Протест", fen = "Tablet used to send messages over great distances to a receiving stone. Scalecommanders may find this of great interest.", fua = "Табличка, яку використовують для надсилання повідомлень на велику відстань до каменя прийому. Може дуже зацікавити лускокомандувачів." }
    t[204252] = { name = "Камінь Відправлення: Перший Звіт", fen = "Tablet used to send messages over great distances to a receiving stone. Scalecommanders may find this of great interest.", fua = "Табличка, яку використовують для надсилання повідомлень на велику відстань до каменя прийому. Може дуже зацікавити лускокомандувачів." }
    t[204253] = { name = "Камінь Відправлення: Полонянка", fen = "Tablet used to send messages over great distances to a receiving stone. Scalecommanders may find this of great interest.", fua = "Табличка, яку використовують для надсилання повідомлень на велику відстань до каменя прийому. Може дуже зацікавити лускокомандувачів." }
    t[204254] = { name = "Прохання Сонови", fen = "A copy of the letter Sonova Snowden sent informing you of his breakthrough with the Winterpelt language.", fua = "Копія листа, який надіслала Сонова Сноуден, повідомляючи вас про свій прорив у вивченні мови Зимохутрих." }
    t[204255] = { name = "Тріснутий Самоцвіт Титанів", fen = "This gem has a familiar energy to it. You feel drawn to it, almost as if it was pulling on your very will itself.", fua = "Цей самоцвіт має знайому енергію. Вас тягне до нього, наче він смикає за саму вашу волю." }
    t[204256] = "Голопроєктор: Багряна Королева"
    t[204257] = "Голопроєктор: Володарка Снів"
    t[204262] = "Голопроєктор: Позачасовий"
    t[204263] = { name = "Часовий Бруд", fen = "The sands of time, stuck in slime and turned to grime.", fua = "Піски часу, загрузлі в слизі й обернуті на бруд." }
    t[204271] = { name = "Напалм Чорного Пазура", fen = "The extreme heat caused by this custom formula will ensure that nothing remains.", fua = "Надзвичайний жар, спричинений цією особливою формулою, забезпечить, що нічого не залишиться." }
    t[204273] = { name = "Викрадені припаси", fen = "Contains various pastes and polishes for taking care of snails.", fua = "Містить різноманітні пасти й мазі для догляду за слимаками." }
    t[204274] = { name = "Стародавні Спогади", fen = "You hold the memories of how to craft different parts of a different version of Oathbinder.", fua = "Ви володієте спогадами про те, як виготовити різні частини іншої версії Скріплювача Клятв." }
    t[204276] = { name = "Незужите Заборонене Знання", fen = "A potent tome found within the Forbidden Reach. Used to enhance Primal Storm gear to its greatest potential.", fua = "Потужний фоліант, знайдений у Заборонених Краях. Використовується, щоб розкрити спорядження Первісної Бурі до його найбільшого потенціалу." }
    t[204277] = "Ласощі для Рубінового Дракончика"
    t[204278] = { name = "Набір Інструментів Нелтаріона", fen = "A set of tools helpful in repairing ancient devices such as a waygate.", fua = "Набір інструментів, корисних для лагодження стародавніх пристроїв, як-от шляхопроводу." }
    t[204279] = "Бойова Сокирка Скелелаза для Вторгнення"
    t[204281] = { name = "Нашийник Тисячозубої Піраньї", fen = "Muscular, flavorful meat, made from the piranha's powerful biting muscles.", fua = "М'язисте, смачне м'ясо, узяте з потужних кусючих м'язів піраньї." }
    t[204282] = { name = "Шматочки Здоровила", fen = "Assorted bits of unknowable fish. Often kept in a sack and fed to small pets as treats.", fua = "Різноманітні шматочки невідомої риби. Часто зберігаються в мішку й даються маленьким улюбленцям як ласощі." }
    t[204283] = { name = "Олія з Печінки Скроґа", fen = "The elders say it's good for you.", fua = "Старійшини кажуть, що це корисно для вас." }
    t[204284] = { name = "\"Універсальний\" Рибний Порошок Норукка", fen = "Norukk claims this can be used as a flavoring agent, shark repellent, lubricant, lamp fuel, shark attractant, or even just to clean your glasses.", fua = "Норукк стверджує, що його можна використовувати як приправу, відлякувач акул, мастило, паливо для лампи, принаду для акул чи навіть просто для чищення окулярів." }
    t[204285] = { name = "Ферментована Паста зі Скумбрії", fen = "Only mackerel that have been dried in the sun for a very long time can achieve a smell like this. Ottuks love it.", fua = "Лише скумбрія, що дуже довго сохла на сонці, може набути такого запаху. Оттуки її обожнюють." }
    t[204286] = { name = "Чорнило Глибинного Кальмара", fen = "Equally useful for dying armor or flavoring soups.", fua = "Однаково придатне як для фарбування обладунків, так і для приправлення супів." }
    t[204287] = { name = "В'ялене М'ясо Острівного Краба", fen = "Dried, preserved, and good for taking on the road. Its concentrated flavor is almost overpowering!", fua = "Сушене, законсервоване й зручне в дорозі. Його насичений смак мало не приголомшує!" }
    t[204288] = { name = "Око Окуня", fen = "Gooey and slippery. Some Iskaara warriors eat them raw, believing they grant strength.", fua = "Слизьке й ковзке. Деякі воїни Іскаари їдять їх сирими, вірячи, що вони дарують силу." }
    t[204289] = { name = "Бруффалон на Семи Прянощах", fen = "It's very spicy.", fua = "Вона дуже гостра." }
    t[204290] = { name = "Драконополум'яний Аргалі", fen = "It's extremely spicy.", fua = "Вона надзвичайно гостра." }
    t[204291] = { name = "Тричі Обвуглені Реберця Мамонта", fen = "The burnt meat is bitter, but undeniably tasty.", fua = "Підгоріле м'ясо гірке, але безперечно смачне." }
    t[204292] = { name = "\"Вулканічна\" Качка", fen = "It's not as spicy as some other centaur dishes (but still quite spicy).", fua = "Вона не така гостра, як деякі інші страви кентаврів (але все одно доволі гостра)." }
    t[204293] = { name = "Зелена Ягода", fen = "Commonly used for flavoring curries.", fua = "Зазвичай використовується для приправлення карі." }
    t[204294] = { name = "Свіжий Драконів Фрукт", fen = "Full of sugar. Dragon Isles natives eat them for a quick energy boost.", fua = "Повний цукру. Місцеві мешканці Драконових Островів їдять його заради швидкого приливу енергії." }
    t[204295] = { name = "Соковита Кущова Ягода", fen = "A cool burst of mint and the perfect amount of crunch.", fua = "Прохолодний сплеск м'яти й ідеальна хрумкість." }
    t[204296] = { name = "Сушена Стрілолистка Холодного Подиху", fen = "These tea leaves grow exclusively in the coldest parts of the Azure Span.", fua = "Це чайне листя росте виключно в найхолодніших куточках Лазурового Простору." }
    t[204297] = { name = "Вишукана Картопля Он'агри", fen = "It's not clear what makes this potato exquisite, but it is.", fua = "Не ясно, що робить цю картоплю вишуканою, але вона саме така." }
    t[204298] = { name = "Листкове Тісто", fen = "Extra butter makes it extra flaky.", fua = "Більше масла робить його ще більш листковим." }
    t[204299] = { name = "Темне Какао Талдраззуса", fen = "This heavily aromatic powder pairs well with sweet or savory dishes.", fua = "Цей надзвичайно ароматний порошок добре пасує як до солодких, так і до пікантних страв." }
    t[204300] = { name = "Суміш Чотирьох Сирів", fen = "The strong stink means it's good.", fua = "Різкий сморід означає, що вона добра." }
    t[204301] = { name = "Пайок: Скорпідовий Сюрприз", fen = "The surprise is it tastes OK.", fua = "Сюрприз у тому, що смак нічогенький." }
    t[204302] = { name = "Пайок: Юшка з Молюсками з Підкопа", fen = "Not all that different from the chowder the tuskarr make.", fua = "Не дуже й відрізняється від юшки, яку готують тускари." }
    t[204303] = { name = "Пайок: Печеня Західного Краю", fen = "Humans love this stuff.", fua = "Люди обожнюють цю штуку." }
    t[204304] = { name = "Пайок: Чилі Драконячого Подиху", fen = "The Dragonscale Expedition thought it would be poetic to bring this chili among their rations.", fua = "Експедиція Драконячої Луски визнала за поетичне взяти це чилі до свого пайка." }
    t[204305] = { name = "Нотатки з Підписом Нелтаріона", fen = "Random research notes bearing Neltharion's signature.", fua = "Випадкові дослідницькі нотатки з підписом Нелтаріона." }
    t[204306] = { name = "Випадкові Карлючки", fen = "Rough drawings by Neltharion... are those the Aspects?", fua = "Грубі малюнки Нелтаріона... це що, Аспекти?" }
