    t[204311] = "Флуоресцентна Завіса"
    t[204312] = { name = "Шкіра Еттіна", fen = "The skin of an ettin is thicker than that of a dragon, and half as pliable.", fua = "Шкіра еттіна товстіша за драконячу й удвічі менш гнучка." }
    t[204313] = "Жменя Луски"
    t[204314] = { name = "Шкура Вогнегончого Пса", fen = "Still smoldering.", fua = "Усе ще тліє." }
    t[204315] = { name = "Кістяна Голка Закалі", fen = "A thin piece of sharpened bone, able to pierce corehound hides without breaking... or melting.", fua = "Тонкий уламок загостреної кістки, здатний пробивати шкуру вогнегончих псів, не ламаючись... і не плавлячись." }
    t[204316] = { name = "Щоденник Солдата", fen = "Mottled and worn, this tome has somehow survived the ages. It seems almost as if its fragile pages were once stained by tears.", fua = "Поплямований і потертий, цей фоліант якимось дивом пережив століття. Здається, наче його крихкі сторінки колись були зрошені слізьми." }
    t[204317] = { name = "Слова Драконоборця", fen = "Scrawled by an indelicate hand, the words on these pages read like the author is shouting at you.", fua = "Накидані недбалою рукою слова на цих сторінках читаються так, наче автор кричить на вас." }
    t[204318] = "Непостійний Арканотрод Тадріона"
