    t[204320] = "Тактичний Тесак Наглядача"
    t[204321] = { name = "Нотатки Зниклої Експедиції", fen = "Notes taken by an enthusiastic explorer. Smells vaguely of cheese.", fua = "Нотатки, зроблені захопленим дослідником. Ледь чути запах сиру." }
