    t[204325] = { name = "Уламок Грубого Ключа", fen = "A piece of a broken key.", fua = "Частина зламаного ключа." }
    t[204326] = "Дивний Артефакт"
    t[204327] = "Деталь Машини Титанів"
    t[204328] = { name = "Повернення Нічного Шквалу", fen = "Stained by saltwater and smelling of rum and... bananas?", fua = "Заплямований солоною водою й пахне ромом та... бананами?" }
    t[204329] = { name = "Скам'яніла Лапа Павука", fen = "Ew. Ew, ew, ew, ew, ew, ew, ew, ew.", fua = "Бр-р. Бр-р, бр-р, бр-р, бр-р, бр-р, бр-р, бр-р, бр-р." }
    t[204330] = { name = "Неактивні Первісні Уламки", fen = "The digestive juices of the slime has drained this gem of any power.", fua = "Травні соки слизі висмоктали з цього самоцвіту всю силу." }
    t[204331] = "Скалка Колони Джарадинів"
    t[204334] = { name = "Нотатки про Утилізацію Відходів", fen = "This timeworn ledger contains grisly notes on numbered experiment subjects and their ultimate end.", fua = "Ця потерта часом облікова книга містить моторошні нотатки про пронумерованих піддослідних та їхній остаточний кінець." }
    t[204335] = { name = "Пісня Глибин", fen = "A chilling missive written from the deep.", fua = "Моторошне послання, написане з глибин." }
    t[204338] = { name = "Тягар Лапісагоса", fen = "A book scribed with shifting arcane runes holding ancient magic.", fua = "Книга, списана мінливими тайнознавчими рунами, що містить стародавню магію." }
    t[204339] = { name = "Торба Згущеного Хаосу", fen = "A satchel sold by Rabul of the Artisan's Consortium. It rumbles in agitation and expands with limitless possibility.", fua = "Торба, яку продає Рабул із Консорціуму Ремісників. Вона неспокійно гуркоче й розпирається безмежними можливостями." }
    t[204340] = "Подертий Клапоть Рецепта"
    t[204342] = { name = "Сумнівне В'ялене М'ясо", fen = "The smell alone is enough to tell you that eating this would likely be a bad idea.", fua = "Самого лиш запаху досить, щоб зрозуміти, що їсти це, певно, кепська ідея." }
    t[204343] = { name = "Надійні Граблі Драконородних", fen = "Sturdy, well-worn, and surprisingly aerodynamic.", fua = "Міцні, добряче зношені й напрочуд аеродинамічні." }
    t[204344] = { name = "Провідний Магнетит", fen = "The polished stone tugs you towards sources of great elemental power.", fua = "Полірований камінь тягне вас до джерел великої стихійної сили." }
    t[204345] = { name = "Записка на Місце Утилізації", fen = "This note contains orders sent to the Gaze of Neltharion.", fua = "Ця записка містить накази, надіслані Погляду Нелтаріона." }
    t[204346] = { name = "Коробка Фольги Arclight Rumble", fen = "What could be inside?", fua = "Що ж там усередині?" }
    t[204347] = "Забруднювач Водойми"
    t[204348] = { name = "Зім'ята в Кульку Фольга Rumble", fen = "Flatten this out.", fua = "Розрівняйте її." }
    t[204349] = "Більший Гайковий Ключ"
    t[204351] = "Оживлена Кристалічна Скалка"
    t[204352] = { name = "Залишки Стихійної Слизі", fen = "Squirming elemental slime gathered off of powerful primalist leaders. This mass seems to want to pull itself back together.", fua = "Звивиста стихійна слиз, зібрана з могутніх ватажків первісників. Ця маса наче прагне знову зібратися докупи." }
    t[204353] = { name = "Первісний Набір Ювеліра", fen = "A collection of unique tools. Mastery of them would take years to learn.", fua = "Зібрання унікальних інструментів. Опанувати їх можна лише за роки." }
    t[204354] = "Спорожнілий Харчовий Пакунок Фурболгів"
    t[204355] = "Спорожнілий Харчовий Пакунок Зимошкурих"
    t[204359] = { name = "Гаманець Гонщика Дальніх Країв", fen = "Filled with gold, Dragon Isles Supplies, and a chance for a Drakewatcher's Manuscript.", fua = "Наповнений золотом, Припасами Драконячих Островів і шансом на Фоліант Дракоглядача." }
    t[204360] = { name = "Дивна Скам'яніла Сфера", fen = "Trapped in the vaults for thousands of years, this object is completely rock hard. Perhaps a powerful source of earth magic could restore it.", fua = "Замкнена у сховищах тисячі років, ця річ стала твердою, мов камінь. Можливо, потужне джерело магії землі здатне її відновити." }
    t[204361] = { name = "Звивистий Зміїстий Дрейк", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[204363] = { name = "Геть Звичайне Яйце", fen = "There seems to be nothing unique about this egg at all. Maybe it can be empowered by something found within the vaults.", fua = "Здається, у цьому яйці немає геть нічого особливого. Можливо, його вдасться підсилити чимось зі сховищ." }
    t[204364] = { name = "Магічно Змінене Яйце", fen = "An egg that has been enhanced with mysterious blue dragon magic. If only you could find something in the vaults that could hatch it.", fua = "Яйце, посилене загадковою магією синього дракона. Якби ж то ви могли знайти в сховищах щось, що здатне його висидіти." }
    t[204365] = { name = "Оберемок Чорних Списів", fen = "A collection of spears wielded by the black dragonflight, still as sharp as the day they were forged.", fua = "Зібрання списів, якими орудував чорна зграя драконів, досі гострих, як у день викування." }
    t[204366] = { name = "Яйце Невідомого Вмісту", fen = "The mysterious egg has finally hatched, but you can't make out what creature is inside. Maybe it will look better when it's grown up. Something in the vaults should speed it along.", fua = "Загадкове яйце нарешті проклюнулося, але ви не можете розгледіти, яка істота всередині. Можливо, вона матиме кращий вигляд, коли підросте. Щось у сховищах має пришвидшити це." }
    t[204367] = { name = "Сплячий Стародавній Мамонт", fen = "Your altered egg grew into a mammoth? That doesn't seem right, but there's no use stopping now. Find a way to wake it up and claim your prize!", fua = "З вашого зміненого яйця виріс мамонт? Це наче й не до ладу, але зупинятися вже немає сенсу. Знайдіть спосіб розбудити його й заберіть свою винагороду!" }
    t[204369] = { name = "Уламок Луски Чорних Драконів", fen = "A glimmer of earth magic still resides within these molted black dragon scales. It might be able to reverse minor petrifications.", fua = "У цих скинутих лусках чорного дракона досі жевріє відблиск магії землі. Він, можливо, здатен скасувати незначні скам'яніння." }
    t[204370] = { name = "Смердюче Осяйне Зілля", fen = "Mix two parts crushed saxifrage, one part pure decay, and throw in some mysterious spores to keep the imbiber on their toes.", fua = "Змішайте дві частини товченого ломикаменю, одну частину чистого тліну й додайте трохи загадкових спор, щоб тримати того, хто його вип'є, у напрузі." }
    t[204371] = { name = "Крапля Магії Синього Дракона", fen = "The picture on the vial is hard to make out, but you're sure it's a dragon. They should consider relabeling these.", fua = "Малюнок на флаконі важко розгледіти, але ви певні, що це дракон. Їм варто було б оновити етикетки." }
    t[204372] = { name = "Дрібка Бронзового Пилу", fen = "Nobody would hide dust in a treasure vault. This is likely a potent bronze dragon catalyst for time magic. Be careful not to use too much!", fua = "Ніхто не ховав би звичайний пил у скарбниці. Це, найпевніше, потужний каталізатор бронзових драконів для магії часу. Стережіться використати забагато!" }
    t[204373] = { name = "Пожмакана Фольга Rumble", fen = "Flatten this out.", fua = "Розрівняйте її." }
    t[204374] = { name = "Брошка Смарагдового Дракона", fen = "Though cracked, you can feel the power of the Emerald Dream hidden within. This should wake any creature.", fua = "Хоч і тріснута, ви відчуваєте приховану в ній міць Смарагдового Сну. Це має пробудити будь-яку істоту." }
    t[204375] = { name = "Вічногорюче Рубінове Вугілля", fen = "A handful of coals that are warm to the touch. This must be from the healing fires of an ancient Red Dragon. Maybe this can help grant life in something small.", fua = "Жменя вугликів, теплих на дотик. Воно, мабуть, узяте з цілющого вогню стародавнього червоного дракона. Можливо, з ним вдасться вдихнути життя в щось невелике." }
    t[204377] = { name = "Сяйливі Спори", fen = "Glowing fungus that sniffing mice have a particular aptness to track down.", fua = "Сяйливий гриб, який рознюхувальні миші особливо вправно вистежують." }
    t[204378] = { name = "Повний Пакунок Постачання Експедиції Драконячої Луски", fen = "Contains a variety of rewards for those who have proven themselves true allies of the Dragonscale Expedition.", fua = "Містить різноманітні нагороди для тих, хто довів, що є справжнім союзником Експедиції Драконячої Луски." }
    t[204379] = { name = "Повний Пакунок Постачання Іскаари", fen = "Contains a variety of rewards for those who have proven themselves true allies of the Iskaara Tuskarr.", fua = "Містить різноманітні нагороди для тих, хто довів, що є справжнім союзником Тускарів Іскаари." }
    t[204380] = { name = "Повна Торба Постачання Кентаврів Маруук", fen = "Contains a variety of rewards for those who have proven themselves true allies of the Maruuk Centaur.", fua = "Містить різноманітні нагороди для тих, хто довів, що є справжнім союзником Кентаврів Маруук." }
    t[204381] = { name = "Повний Пакунок Постачання Угоди Валдраккена", fen = "Contains a variety of rewards for those who have proven themselves true allies of the Valdrakken Accord.", fua = "Містить різноманітні нагороди для тих, хто довів, що є справжнім союзником Угоди Валдраккена." }
    t[204382] = { name = "Шляхетний Бруффалон", fen = "Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location.", fua = "Навчає викликати цей засіб пересування. Цей засіб пересування змінюється залежно від вашої навички верхової їзди та місцезнаходження." }
    t[204383] = { name = "Мішок Дивовиж", fen = "The Dragonscale Expedition collect such a wide assortment of trinkets and baubles even they aren't certain what's inside.", fua = "Експедиція Драконячої Луски зібрала такий широкий асортимент дрібничок і брязкалець, що навіть її члени не певні, що там усередині." }
    t[204386] = { name = "Кишенькове Затемнене Стихійне Ядро", fen = "Even at this size, elemental cores can syphon enough of the surrounding Shadowflame energy to turn into a small but deadly explosive.", fua = "Навіть такого розміру стихійні ядра здатні висмоктати достатньо тіньополум'яної енергії з довкілля, щоб обернутися на невеликий, але смертоносний вибуховий заряд." }
    t[204387] = { name = "Дзижчаче Ядро Сфери", fen = "This titan artifact stores energy that can be used to power the carrier's abilities.", fua = "Цей артефакт титанів зберігає енергію, якою можна живити здібності того, хто його носить." }
