    t[204434] = { name = "Гартований Лавою Клинок", fen = "The glowing heat lingering in the blade makes it almost unbearable to hold.", fua = "Розжарений жар, що тримається в клинку, робить його майже нестерпним у руці." }
    t[204435] = { name = "Обсидіанова Таблиця", fen = "Djaradin runes cut deeply into the volcanic glass.", fua = "Руни джарадинів глибоко вирізьблені у вулканічному склі." }
    t[204436] = { name = "Надщерблений Перстень-Печатка з Рогу", fen = "The metal is polished in places, tarnished in others, as if someone has spent a lot of time running their fingers over it.", fua = "Метал подекуди відполірований, а подекуди потьмянілий, наче хтось довго водив по ньому пальцями." }
    t[204439] = { name = "Ключ від Дослідницької Скрині", fen = "A key to a locked chest within the Zskera Vaults.", fua = "Ключ від замкненої скрині в Сховищах Зскера." }
    t[204440] = { name = "Іскра Тіньополум'я", fen = "A powerful spark touched by Shadowflame, this unique crafting material can help an item achieve expertise beyond that of mortal ability.", fua = "Могутня іскра, торкнута Тіньополум'ям; цей унікальний матеріал для ремесла може наділити предмет вправністю, що перевершує можливості смертних." }
