    t[204459] = "Чарівна Паличка Мінливого Каменю"
    t[204460] = { name = "Сяйвоспори Заралека", fen = "Commonly found by gatherers while exploring Zaralek Cavern. Can be bought and sold on the auction house.", fua = "Часто знаходяться збирачами під час дослідження Печери Заралек. Можна купувати й продавати на аукціоні." }
    t[204461] = { name = "Пам'ять Шалкіла", fen = "A token of gratitude for your assistance with the burial of Shalkeel, brave warrior of the centaur clan Shikaar, first to combat Fyrakk the Blazing.", fua = "Знак вдячності за твою допомогу в похованні Шалкіла, відважного воїна кентаврського клану Шикаар, першого, хто став на бій із Фіракком Палаючим." }
    t[204462] = { name = "Скалка Дракотиста", fen = "Powerless and unusable in its current state.", fua = "Безсилий і непридатний до використання у своєму нинішньому стані." }
    t[204463] = { name = "Дракотист", fen = "A potent crystal capable of holding magical energies. Acquired through Alchemy transmutations and can be bought and sold on the auction house.", fua = "Потужний кристал, здатний утримувати магічну енергію. Здобувається через алхімічні трансмутації, можна купувати й продавати на аукціоні." }
    t[204464] = { name = "Сутність Тіньополум'я", fen = "A shard that exudes a menacing presence. Rarely obtained from extremely powerful foes. Can be bought and sold on the auction house.", fua = "Скалка, що випромінює грізну присутність. Рідко здобувається з украй могутніх ворогів. Можна купувати й продавати на аукціоні." }
    t[204465] = "Голос Безмовної Зорі"
    t[204466] = "Висмоктувальний Перстень-Печатка Мучителя"
    t[204467] = { name = "Плащ Драктирських Випробувань", fen = "'Many of you will perish. And yet, the master demands perfection.'", fua = "«Багато хто з вас загине. І все ж володар вимагає досконалості.»" }
    t[204469] = { name = "Загублені Креслення Стоків Аберруса", fen = "A crude but nonetheless detailed series of drawings depicting the lava outflows of Aberrus and the basic machinery that controls them.", fua = "Грубий, але водночас докладний набір малюнків, що зображують лавові стоки Аберруса й основні механізми, які ними керують." }
    t[204470] = { name = "Недбало Викинута Бомба", fen = "Rigged with a thirty second fuse.", fua = "Споряджена ґнотом на тридцять секунд." }
    t[204471] = { name = "Несправний Набір для Виживання", fen = "Intended to allow the wearer to swim in lava. There is probably a good reason why it was left behind.", fua = "Призначений, щоб дати власникові змогу плавати в лаві. Напевно, є вагома причина, чому його покинули." }
    t[204473] = { name = "Викачувач Стихій", fen = "A gadget that detects and extracts unwavery powers collected by creatures underground.", fua = "Пристрій, що виявляє й видобуває непохитні сили, зібрані підземними створіннями." }
    t[204475] = { name = "Зламаний Генератор Зміїної Нори", fen = "It would still be functional if its previous owner had taken two steps to the left.", fua = "Він би й досі працював, якби попередній власник ступив два кроки ліворуч." }
    t[204480] = { name = "Непримітний Збирач Даних", fen = "Was this supposed to be hidden?", fua = "Хіба це мало бути приховано?" }
