    t[204686] = { name = "Стримувальний Пристрій Титанів", fen = "Warning: Uneducated utilization of this device could result in self-entrapment. Please do not use without supervision.", fua = "Увага: невміле використання цього пристрою може призвести до самозамкнення. Будь ласка, не використовуй без нагляду." }
    t[204687] = { name = "Обсидіановий Бойовий Ріг", fen = "An ancient horn used to signal attacks!", fua = "Стародавній ріг, яким сповіщали про атаку!" }
    t[204691] = { name = "Жива Книга", fen = "This tome's cover looks like blue leather, but feels like... wait. That's not leather. The pages are... what is that? Is this book breathing?", fua = "Обкладинка цього фоліанта схожа на синю шкіру, але на дотик... стривай. Це не шкіра. А сторінки... що це таке? Невже ця книга дихає?" }
    t[204694] = { name = "Велика Руна Вогняного Зору", fen = "Holding this rune fills your mind with visions of distant places.", fua = "Тримаючи цю руну, ти наповнюєш розум видіннями далеких місць." }
    t[204695] = { name = "Рецепт: Котел Видобутого Гниття", fen = "Teaches you how to craft Cauldron of Extracted Putrescence.", fua = "Навчає тебе виготовляти Котел Видобутого Гниття." }
