    t[204796] = { name = "Пил Глибинного Білувальника", fen = "A strange combination of what feels like a softer dust, with hard bits of crystal. Strangely pleasant to touch.", fua = "Дивна суміш чогось на дотик схожого на м'якший пил із твердими крихтами кристалів. Напрочуд приємна на дотик." }
    t[204797] = { name = "Хвальні Таблиці Джарадинів", fen = "I have faced many stronger foes than you, weakling!", fua = "Я стикався з куди сильнішими ворогами за тебе, слабаче!" }
    t[204798] = { name = "Пекельний Бронедон", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[204800] = { name = "Луската Кам'яна Шкіра", fen = "Hide from the subterranean snakes endemic to Zaralek Cavern.", fua = "Шкіра підземних змій, що мешкають у Печері Заралек." }
    t[204801] = { name = "Спори Драглистого Гриба", fen = "Spores collected from Gelcap Mushrooms. Slightly gooey.", fua = "Спори, зібрані з драглистих грибів. Трохи слизькі." }
