    t[204803] = { name = "Відлунена Плоть Причаєнця", fen = "A succulent cut of farmed fish, packed with essential nutrients and ideal for picky retired-predators of the underground.", fua = "Соковитий шматок вирощеної риби, повний поживних речовин, ідеальний для вибагливих підземних хижаків на спочинку." }
    t[204805] = { name = "Зависла Сірчана Краплина", fen = "It burns AND it stinks!", fua = "Вона пече І смердить!" }
    t[204808] = { name = "Підсилена Темпоральна Павутинка", fen = "These firmly bound strands reverberate when near Ancient Memories.", fua = "Ці міцно сплетені нитки відлунюють поблизу Прадавніх Спогадів." }
