    t[204811] = "Камені Дрогбарів"
    t[204812] = { name = "Обпалена Книга", fen = "Scorch marks line the ornate frames of the red binding while the inside has lost all color to a coat of ash.", fua = "Сліди опіків укривають візерунчасті рамки червоної оправи, а всередині все втратило барву під шаром попелу." }
    t[204813] = { name = "Порожній Фоліант", fen = "While the blue binding seems worn and the pages wrinkled from constant use, all of the pages are blank.", fua = "Хоч синя оправа й здається потертою, а сторінки зім'яті від постійного користування, усі вони порожні." }
    t[204814] = { name = "Старий Щоденник", fen = "The colors of a once gilded journal are now discolored, with pages filled with faded words.", fua = "Барви колись визолоченого щоденника нині збляклі, а сторінки рясніють вицвілими словами." }
    t[204815] = { name = "Заплутаний Збірник", fen = "An extensive, yet jumbled list of names, species, and families.", fua = "Розлогий, але безладний перелік імен, видів і родин." }
    t[204816] = { name = "Загадковий Альманах", fen = "Every page is filled with a clutter of indecipherable entries, many with differing handwriting styles.", fua = "Кожна сторінка заповнена безладом нерозбірливих записів, багато з яких зроблено різними почерками." }
    t[204817] = { name = "Волокна Підсвітлового Кокона", fen = "Silk fibers from the cocoons of underlight moths.", fua = "Шовкові волокна з коконів підсвітлових метеликів." }
