    t[205213] = { name = "Підозріла Цвіль", fen = "You can feel it slithering on your hand whenever you look away.", fua = "Ви відчуваєте, як вона ковзає по вашій руці щоразу, коли відводите погляд." }
    t[205214] = { name = "Зневажені Слимачі Мушлі", fen = "Nobody wants these boring husks when bejeweled shells are the pinnacle of snail fashion!", fua = "Нікому не потрібні ці нудні шкаралупи, коли оздоблені самоцвітами мушлі — вершина слимачої моди!" }
    t[205216] = { name = "Легенько Струшені Коштовності", fen = "It is the polite way to describe a bunch of worthless gem shards. At least they are pretty!", fua = "Так чемно називають жменю нікчемних уламків самоцвітів. Принаймні вони гарні!" }
    t[205217] = { name = "Корм Гостродзьоба", fen = "This hearty grain sits heavily in your bag. The smell wafting from it reminds you of golden fields.", fua = "Це поживне зерно важко лежить у вашій торбі. Запах, що від нього лине, нагадує вам золоті лани." }
    t[205219] = { name = "Розбитий Торговий Валун", fen = "Not enough rough edges to be considered a barter brick, but far too many to be accepted as a barter boulder.", fua = "Замало нерівних граней, щоб вважатися торговою цеглиною, але занадто багато, щоб його прийняли за торговий валун." }
