    t[205970] = { name = "Лазурний Летокамінь", fen = "Once this contained the power of flightstones. Now it's a beautiful paperweight.", fua = "Колись він містив силу летокаменів. Тепер це гарне прес-пап'є." }
    t[205971] = { name = "Породолам", fen = "Bedrock is no match for this pickaxe.", fua = "Скельна основа не встоїть проти цієї кирки." }
    t[205972] = { name = "Декоративний Меч Ніффенів", fen = "To no one's surprise, this shovel was not made by the Niffen.", fua = "Як і слід було очікувати, цю лопату зробили зовсім не ніффени." }
