    t[205980] = { name = "Ласо для Слимаків", fen = "Throw this lasso to wrangle the finest-smelling snails Zaralek has to offer!", fua = "Кинь це ласо, щоб упіймати найзапашніших слимаків, яких лише має Заралек!" }
