    t[205983] = { name = "Запахущі Скарби Ніффенів", fen = "Contains the finest (and smelliest!) gifts the niffen have to offer their friends.", fua = "Містить найкращі (і найзапашніші!) дарунки, які ніффени мають для своїх друзів." }
