    t[205985] = "Відзнака Ніффенів Лоамму"
    t[205986] = { name = "Добряче Зношена Піч", fen = "A kiln fit for a Kilnmaster.", fua = "Піч, гідна Майстра Печі." }
    t[205987] = { name = "Сірчаний Рятувальний Круг", fen = "Even Dragonkin need a little help sometimes.", fua = "Навіть драконородним часом потрібна крихта допомоги." }
    t[205988] = { name = "Спис Старійшини Закалі", fen = "A mighty spear crafted by a Zaqali Master Blacksmith.", fua = "Могутній спис, викуваний майстром-ковалем Закалі." }
    t[205989] = { name = "Символ Дружби", fen = "You can tell how much the niffen like you based on how nice this smells.", fua = "Те, як приємно це пахне, підкаже, наскільки ти до вподоби ніффенам." }
    t[205990] = { name = "Лютий Ключ", fen = "With the key acquired, you can now open the treasure!", fua = "Тепер, маючи ключ, ви можете відкрити скарб!" }
    t[205991] = { name = "Блискучий Жетон Вдячності", fen = "Found by Tubberos in a cave near Nal ks'kol, it means a lot to him for you to have this.", fua = "Знайдений Тубберосом у печері поблизу Нал кс'кол. Йому дуже важливо, щоб ти отримав це." }
    t[205992] = { name = "Відригнута Напівперетравлена Риба", fen = "Dropped at your feet by a thankful slitherdrake.", fua = "Кинута тобі під ноги вдячним повзкодраком." }
    t[205994] = { name = "Фоліант Землехранителя", fen = "A tome taken from Neltharion's Sanctum in Aberrus, the Shadowed Crucible on Normal Difficulty.", fua = "Фоліант, здобутий у Святилищі Нелтаріона в Аберрусі, Тіньовому Горнилі, на Звичайній складності." }
    t[205996] = { name = "Фоліант Землехранителя", fen = "A tome taken from Neltharion's Sanctum in Aberrus, the Shadowed Crucible on Heroic Difficulty.", fua = "Фоліант, здобутий зі Святилища Нелтаріона в Аберрусі, Затіненому Горнокипі, на героїчній складності." }
    t[205997] = { name = "Фоліант Землехранителя", fen = "A tome taken from Neltharion's Sanctum in Aberrus, the Shadowed Crucible on Mythic Difficulty.", fua = "Фоліант, здобутий зі Святилища Нелтаріона в Аберрусі, Затіненому Горнокипі, на міфічній складності." }
    t[205998] = { name = "Знак Шани", fen = "A symbol of respect for laying down your life for the Dragon Isles and its inhabitants.", fua = "Символ шани за те, що ти ризикуєш життям заради Драконових Островів та їхніх мешканців." }
    t[205999] = "Вулканічний Різьбяр"
    t[206000] = { name = "Ключ Мороз-Вогню", fen = "Scorching hot, but somehow covered in a fine layer of ice.", fua = "Розпечений до краю, але чомусь укритий тонким шаром криги." }
    t[206001] = { name = "Закутий у Кригу Уламок Ключа", fen = "Freezing cold.", fua = "Морозний холод." }
    t[206002] = { name = "Охоплений Полум'ям Уламок Ключа", fen = "Smoking with inner heat.", fua = "Димить від внутрішнього жару." }
    t[206006] = { name = "Подяка Землехранителя", fen = "A flower, grown from the earth that the Earth-Warder has sworn to protect, as well as a gift to you for your heroism.", fua = "Квітка, що зросла із землі, яку Землехранитель присягнувся берегти, а також дарунок тобі за твою звитягу." }
    t[206009] = { name = "Табличка Уробороса", fen = "Complex diagrams coat the surface, with four designs stretching past the stone's edges. An eloquently designed ouroboros lies engraved in the center.", fua = "Складні діаграми вкривають поверхню, а чотири візерунки виходять за краї каменя. У центрі вигадливо вигравіюваний уроборос." }
    t[206010] = { name = "Візерунки Плоті", fen = "Decorated in ancient symbols of blood and water.", fua = "Оздоблено прадавніми символами крові й води." }
    t[206011] = { name = "Візерунки Кістки", fen = "Decorated in ancient symbols of bone and earth.", fua = "Оздоблено прадавніми символами кістки й землі." }
    t[206012] = { name = "Візерунки Розуму", fen = "Decorated in ancient symbols of mind and fire.", fua = "Оздоблено прадавніми символами розуму й вогню." }
    t[206013] = { name = "Візерунки Душі", fen = "Decorated in ancient symbols of soul and air.", fua = "Оздоблено прадавніми символами душі й повітря." }
    t[206014] = { name = "Табличка Уробороса", fen = "Circular designs show a large spiral pattern starting from the left side. Symbols of water and blood flow into it and the missing spaces along the bottom.", fua = "Кругові візерунки утворюють велику спіраль, що бере початок зліва. У неї стікаються символи води й крові та порожні місця вздовж нижнього краю." }
    t[206015] = { name = "Табличка Уробороса", fen = "Symbols of bone and earth line the pathway of the spiral design as it continues up from the bottom and into the missing right side.", fua = "Символи кістки й землі облямовують спіральний візерунок, що в'ється знизу вгору й тягнеться до відсутнього правого краю." }
    t[206016] = { name = "Табличка Уробороса", fen = "As symbols of mind and fire wrap around the carved spiral, they move inward and up into the open space at the top.", fua = "Символи розуму й вогню обвивають вирізьблену спіраль, рухаючись усередину й угору, до вільного простору на вершині." }
    t[206017] = { name = "Табличка Уробороса", fen = "Delicately drawn symbols of soul and air decorate the top as the spiral continues inward. The ouroboros in the center glows brightly as a violet energy is siphoned through the spiral and into the center.", fua = "Витончено накреслені символи душі й повітря оздоблюють верх, а спіраль звивається далі всередину. Уроборос у центрі яскраво сяє, поки крізь спіраль до осердя струмує фіалкова енергія." }
    t[206019] = { name = "Покинутий Запасний Парашут", fen = "Luckily for someone it's just the reserve chute. You could learn a lot from studying the stitchwork!", fua = "Комусь пощастило — це лише запасний парашут. Вивчаючи ці шви, можна багато чого навчитися!" }
    t[206021] = { name = "Сяйлива Луска Коб'рока", fen = "A suitable sacrifice.", fua = "Гідна жертва." }
    t[206022] = { name = "Щаслива Карта Hearthstone Андуїна", fen = "An old-looking Common card depicting a Stormwind Guard with lightly tattered edges.", fua = "Стара на вигляд звичайна карта зі злегка пошарпаними краями, на якій зображено Вартового Стормвінда." }
    t[206025] = { name = "Використаний Похідний Медичний Набір", fen = "Most of the supplies have been used, but some of the medical bandages remain.", fua = "Більшість запасів використано, але кілька медичних бинтів іще лишилося." }
    t[206027] = { name = "Повіддя Скверно-Кристалічного Скорпіона", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[206028] = { name = "Скриня золота", fen = "Contains 1000 gold.", fua = "Містить 1000 золота." }
    t[206030] = { name = "Вишукано Гаптований Стяг", fen = "The quality of this banner is positively breathtaking. This was crafted by quite the artisan.", fua = "Якість цього стяга просто захоплює подих. Його створив справжній майстер." }
    t[206031] = { name = "Вигадливі Руни Закалі", fen = "Ancient magic emanates from the runes carved upon the surface.", fua = "Від рун, вирізьблених на поверхні, віє прадавньою магією." }
    t[206034] = { name = "Сичливий Накид Руни", fen = "A low hissing fills your mind. Is it the rock vipers nearby, or the rune?", fua = "Тихе сичання сповнює твій розум. Це скельні гадюки неподалік чи руна?" }
    t[206035] = { name = "Прадавні Дослідження", fen = "Surprisingly well preserved, this text documents research into various runes and magics.", fua = "Напрочуд добре збережений, цей текст описує дослідження різноманітних рун і магії." }
    t[206037] = { name = "Рубіновий Летокамінь", fen = "Once this contained the power of flightstones. Now it's a beautiful paperweight.", fua = "Колись він містив силу летокаменів. Тепер це гарне прес-пап'є." }
