    t[206046] = { name = "Дивовижа, Торкнута Порожнечею", fen = "A fascinating and menacing omen. Kaitalla at the Obsidian Rest in Zaralek Cavern may know how to unlock the secrets that lay within.", fua = "Захопливе й загрозливе знамення. Кайталла біля Обсидіанового Спочинку в Печері Заралек, можливо, знає, як розкрити приховані в ньому таємниці." }
    t[206135] = { name = "Трофейна Скриня Героїчного Дослідника Підземель", fen = "Contains a piece of Champion 1/8 (item level 415) gear.", fua = "Містить предмет спорядження рівня Чемпіон 1/8 (рівень предмета 415)." }
    t[206136] = { name = "Трофейний Герб Героїчного Дослідника Підземель", fen = "Contains fifteen Drake's Shadowflame Crest Fragments.", fua = "Містить п'ятнадцять уламків Драконового герба тіньового полум'я." }
