    t[206353] = { name = "Свисток Вартової", fen = "A small runewood whistle that produces a sharp, warbling tune.", fua = "Маленький свисток з рунічного дерева, що видає різкий, переливчастий звук." }
    t[206354] = { name = "Смердюча Свічка", fen = "Perfect for those days when you want everyone to leave you alone.", fua = "Ідеальна для тих днів, коли хочеться, щоб усі дали вам спокій." }
    t[206355] = { name = "Свічка, Начинена Тютюном", fen = "When the courier is running late, sometimes you must take matters into your own hands.", fua = "Коли посланець запізнюється, іноді доводиться брати справу у власні руки." }
    t[206356] = { name = "Свічка проти Привидів", fen = "Supposedly keeps the ghosts away, but evidently that is just a child's story.", fua = "Нібито відлякує привидів, але це, звісно, лише дитяча байка." }
    t[206357] = { name = "Справжня Свічка з Андоргала", fen = "A candle so ordinary it is actually quite suspicious.", fua = "Свічка така звичайна, що насправді це навіть підозріло." }
    t[206358] = { name = "Привізна Свічка", fen = "The most impressive detail of this candle is how someone managed to fully carve out \"Corin's Crossing\" on the bottom.", fua = "Найбільше вражає в цій свічці те, як комусь вдалося повністю вирізьбити «Перехрестя Коріна» на її денці." }
    t[206359] = { name = "Вода з Фонтана Каер-Дарроу", fen = "Far too viscous to evaporate.", fua = "Надто густа, щоб випаруватися." }
    t[206360] = { name = "Недоставлена Партія Курива", fen = "A crate of the finest cigars Ezra Grimm had to offer.", fua = "Ящик найкращих сигар, які тільки міг запропонувати Езра Грімм." }
    t[206361] = { name = "Затоптана Лялька", fen = "A crumpled note shoved into one of the doll's pockets reads: 'To my bestest friend, from Pamela.'", fua = "На зім'ятій записці, запханій до однієї з кишеньок ляльки, написано: «Моїй найкращій подружці, від Памели»." }
    t[206362] = { name = "Грамота на Андоргал", fen = "Carries a faded seal.", fua = "Несе на собі вицвілу печатку." }
    t[206363] = { name = "Дорога Попереду", fen = "A gorgeous painting of the road leading out of Corin's Crossing. The signature \"Renfray\" is carefully inscribed on a corner.", fua = "Чудова картина дороги, що веде з Перехрестя Коріна. У кутку дбайливо виведено підпис «Ренфрей»." }
    t[206364] = { name = "Стегнова Кістка Еви", fen = "Probably not what Eva was expecting you to use for the ritual, but it gets the job done.", fua = "Напевно, не зовсім те, що Ева очікувала побачити для ритуалу, але справу робить." }
    t[206365] = { name = "Інертна Примарна Сутність", fen = "Allowed communication with the deceased of Caer Darrow, long ago.", fua = "Колись давно дозволяла спілкуватися з померлими Каер-Дарроу." }
