    t[206563] = { name = "Давня Викрійка: Покров Забороненої Магії", fen = "Teaches you how to craft Shroud of Forbidden Magic.", fua = "Навчає виготовляти Покров Забороненої Магії." }
    t[206564] = { name = "Зміщений у Часі Титанічний Диск", fen = "This item is clearly of titan origin. Despite the saliva dripping from it, it still appears to be functional.", fua = "Цей предмет вочевидь титанічного походження. Попри слину, що з нього стікає, він, схоже, досі справний." }
    t[206565] = { name = "Заражене Зерно", fen = "A crate postmarked for Light's Hope Chapel. Fortunately, it never arrived.", fua = "Ящик, адресований до Каплиці Надії Світла. На щастя, він так і не дійшов." }
