    t[206577] = { name = "Вкритий Слизом Сувій", fen = "No refunds!", fua = "Без повернення коштів!" }
    t[206578] = { name = "Череп із Рогами", fen = "Despite the timeline this came from, this skull remains inexplicably free of fel energy. You feel an odd sense of calm while holding it.", fua = "Попри часову лінію, з якої він походить, цей череп незбагненно вільний від скверни. Тримаючи його, ти відчуваєш дивний спокій." }
    t[206579] = { name = "Філактерна Тканина", fen = "Its soul-absorbent properties make it a crucial component for purifying Desecrated items.", fua = "Її властивість поглинати душі робить її ключовою складовою для очищення осквернених предметів." }
    t[206584] = "Архівні Ремісничі Техніки"
    t[206585] = { name = "Повід Звитяги", fen = "Teaches you how to summon Valiance.", fua = "Навчає прикликати Звитягу." }
    t[206586] = { name = "Видобувач Епох", fen = "A device that allows you to steal the essence of time-lost creatures.", fua = "Пристрій, що дозволяє викрасти сутність загублених у часі істот." }
    t[206598] = { name = "Тліюча Квітка", fen = "Eternally burning, yet unable to die. The Aspects will want to see this.", fua = "Горить вічно, та не здатна загинути. Аспекти захочуть це побачити." }
    t[206599] = { name = "Азмерлотський Пісковий Годинник", fen = "The sands of this hourglass appear to float in place, suspended in time. The iconography decorating it is nearly identical to the more familiar bronze dragonflight hourglasses you are used to, only with more murlocs.", fua = "Пісок у цьому годиннику ніби завис на місці, застиглий у часі. Символіка, що його оздоблює, майже не відрізняється від звичних тобі пісокових годинників бронзової зграї драконів, хіба що з більшою кількістю мурлоків." }
    t[206602] = { name = "Механізована Шестерня", fen = "This cog seems to whirl back and forth a bit, despite no longer being part of a mechanism. Into its side is etched \"Mechanization is the only way to true peace.\"", fua = "Ця шестерня ніби трохи обертається туди-сюди, хоча вже не є частиною механізму. На її боці викарбувано: \"Механізація — єдиний шлях до справжнього миру.\"" }
    t[206638] = { name = "Зіпсутий Ешбрінгер Азморна", fen = "In this weapon's timeway, it was never cleansed of corruption. Best take care not to touch it directly.", fua = "У часовому шляху цієї зброї її так і не очистили від зіпсуття. Краще стережися торкатися її напряму." }
