    t[206679] = { name = "Досконалий Колос", fen = "Teaches you how to summon Perfected Juggernaut. This is a ground mount.", fua = "Навчає вас прикликати Досконалого Колоса. Це наземний засіб пересування." }
    t[206680] = { name = "Повід Полоненого Плітью Звитяжця", fen = "Teaches you how to summon this mount. This is a flying mount.", fua = "Навчає вас прикликати цей засіб пересування. Це летючий засіб пересування." }
    t[206681] = "Лист від Омана"
    t[206683] = { name = "Рахунок Гнівіона", fen = "Wrathion's (rather pricy) tab, featuring enough firewine for a banquet.", fua = "(Доволі чималий) рахунок Гнівіона, де значиться досить вогневина на цілий бенкет." }
    t[206695] = { name = "Бліда Сутінкоцвітка", fen = "A favorite flower of Tyrande Whisperwind, remembered fondly from her youth in Val'sharah.", fua = "Улюблена квітка Тіранди Віспервінд, що залишила теплі спогади з її юності у Вал'шарі." }
    t[206696] = { name = "Хитромудрий Мислильний Ковпак", fen = "Equipped with a Cogs-and-Bolts-o-Meter.", fua = "Оснащений шестерне-болто-метром." }
    t[206749] = { name = "Просочений Оливою Судновий Журнал", fen = "Despite the oil dripping from it, there is enough legible text to provide some clue as to the nature of the timeline this came from.", fua = "Попри оливу, що з нього скрапує, лишилося досить розбірливого тексту, щоб дати певну підказку про природу часової лінії, з якої він походить." }
