    t[206957] = { name = "Боффінс", fen = "This little robot happily jumped into your arms as you picked it up. It buzzes happily in your pack and almost sounds like it's purring.", fua = "Цей маленький робот радо стрибнув тобі в обійми, коли ти його підняв. Він весело гуде у твоєму наплічнику, майже наче муркоче." }
    t[206958] = "Паракаузальний Уламок Вал'аніра"
    t[206959] = { name = "Іскра Снів", fen = "A powerful spark influenced by the Dream, this unique crafting material can help an item achieve expertise beyond that of mortal ability.", fua = "Потужна іскра, що зазнала впливу Сну. Цей унікальний матеріал для ремесла здатен надати предмету майстерності, що перевершує можливості смертних." }
    t[206960] = { name = "Сновидний Герб Зачарованого Вірма", fen = "A powerful reagent created by enchanters.", fua = "Могутній реагент, створений зачарувальниками." }
    t[206961] = { name = "Сновидний Герб Зачарованого Аспекта", fen = "A powerful reagent created by enchanters.", fua = "Могутній реагент, створений зачарувальниками." }
    t[206962] = { name = "Журнал Спостерігача", fen = "This has clearly been chewed on, potentially eaten, and likely... what comes after being eaten. Incredibly, it appears to still be functional.", fua = "Його явно жували, можливо, навіть з'їли і, скоріш за все... ну, те, що буває після того, як щось з'їдять. Неймовірно, але він, схоже, ще робочий." }
