    t[206977] = { name = "Сновидний Герб Зачарованого Дракончика", fen = "A powerful reagent created by enchanters.", fua = "Могутній реагент, створений зачарувальниками." }
    t[206983] = "Паракаузальний Уламок Фростморна"
    t[206984] = { name = "Просочена Кров'ю Книга", fen = "The blood has long since dried. Oddly, the text in this book appears to have been written after the blood dried, not prior to it being soaked in blood.", fua = "Кров давно засохла. Дивно, але текст у цій книзі, схоже, написали вже після того, як кров висохла, а не до того, як її просочили нею." }
    t[206993] = { name = "Кишеньковий Годинник Слідознавця", fen = "Sand is released when the second hand moves.", fua = "Коли секундна стрілка рухається, висипається пісок." }
    t[206997] = { name = "Позолочені Сонцезахисні Окуляри", fen = "The future's so bright, I gotta wear shades.", fua = "Майбутнє таке яскраве, що доводиться носити окуляри." }
    t[206998] = { name = "Бурштиновий Меч", fen = "There are chips, dents, and scratches along this blade. It has clearly seen battle for a very long time, against what is unclear.", fua = "На лезі видно щербини, вм'ятини й подряпини. Цей меч явно довго бачив бій — а ось проти кого, незрозуміло." }
    t[207002] = { name = "Заключена Доля", fen = "A fragment of possibility, made tangible by the timeways' collapse.", fua = "Уламок можливості, втілений у дійсність крахом часових шляхів." }
    t[207003] = { name = "Позолочена Ваза", fen = "A large golden vase. It's empty, and a quick glance inside indicates a black dirt-like substance. An odd find at the top of Icecrown.", fua = "Велика золота ваза. Вона порожня, а швидкий погляд усередину виявляє чорну, схожу на бруд речовину. Дивна знахідка на вершині Крижаної Корони." }
    t[207004] = { name = "Фоліант Заклинача", fen = "Laying a hand on the tome causes a gentle thrumming in your ears. Immense power is contained within these pages.", fua = "Коли кладеш руку на фоліант, у вухах лунає тихе гудіння. У цих сторінках криється неосяжна сила." }
    t[207005] = "Паракаузальний Уламок Громоплавця, Вологого Клинка Шукача Припливу"
    t[207008] = { name = "Риба", fen = "Just a big fish. As fish go, it does look like a nice fish.", fua = "Просто велика риба. Як на рибу, вона й справді має непоганий вигляд." }
    t[207011] = { name = "Бойові Клинки Хаккарі, Відроджені", fen = "Legends state that these blades can only be forged at the edge of madness, by a soul whose anger burns brighter than the seething flames of hatred.", fua = "Легенди кажуть, що ці клинки можна викувати лише на межі безумства душею, чий гнів палає яскравіше за люті полум'я ненависті." }
