    t[207026] = { name = "Згусток Сну", fen = "Solidified motes of energy slipping into Azeroth from the Emerald Dream. Celestine of the Harvest near Dreamsurge Investigations will trade for these.", fua = "Затверділі крихти енергії, що проникають до Азероту зі Смарагдового Сну. Целестина Жнив поблизу Дослідження Прориву Сну обмінює їх на товари." }
    t[207027] = { name = "Велика Заключена Доля", fen = "One can not manipulate destiny. But perhaps the path can be influenced.", fua = "Долею не можна керувати. Та, можливо, на її шлях можна вплинути." }
    t[207030] = { name = "Розтягнута Часова Капсула", fen = "Capturing a moment in time is a simple task, but preserving it is a feat.", fua = "Спіймати мить нескладно, але зберегти її — справжній подвиг." }
