    t[208202] = { name = "Настанови Агента Нельтаріона", fen = "This ancient, barely intact scroll is stamped with Neltharion's signet.", fua = "Цей прадавній, ледь цілий сувій скріплений печаткою Нельтаріона." }
    t[208203] = { name = "Сяйлива Зоря", fen = "The yellow shard of the sundered Ata'mal crystal, a sacred draenei relic. Holding it seems to focus your mind, honing your concentration to a razor-sharp edge.", fua = "Жовта скалка розколотого кристала Ата'мал, священної реліквії дренеїв. Тримаючи її, ти відчуваєш, як зосереджується твій розум, загострюючи увагу до гостроти леза." }
    t[208206] = { name = "Кристал Телепортації", fen = "A smooth arkonite shard attuned to the Vindicaar's beacon matrix.", fua = "Гладка скалка арконіту, налаштована на матрицю маяка Віндікаара." }
    t[208207] = "Зношені Часом Наплічники Морчі"
    t[208212] = { name = "Сновидна Сутність", fen = "An amalgamation of the flowing energy of the Dream. No matter how you manipulate it, it always seems to return to its original form. Rarely obtained from extremely powerful foes in Amirdrassil. Can be bought and sold on the auction house.", fua = "Сплав плинної енергії Сну. Хоч як ти її змінюєш, вона завжди, схоже, повертається до своєї первісної форми. Зрідка здобувається з надзвичайно могутніх ворогів в Амірдрассілі. Можна купити й продати на аукціоні." }
    t[208216] = { name = "Повіддя Квантового Скакуна", fen = "A being from beyond the boundaries of any single timeway. When observed, its form collapses into a single shape.", fua = "Істота з-поза меж будь-якого окремого часоплину. Коли за нею спостерігають, її образ згортається в одну форму." }
    t[208217] = { name = "Ілюзорний Сувій Молодості - NOT USED", fen = "Casts an illusory cover over adult umbraclaws to make them look like baby cubs.", fua = "Накладає ілюзорну подобу на дорослих тіньолапів, щоб ті виглядали наче малі дитинчата." }
    t[208221] = { name = "Ґрунт Сновидного Гаю", fen = "This soil is rich and fragrant, perfect for fostering new growth.", fua = "Цей ґрунт багатий і запашний, ідеальний для плекання нових паростків." }
    t[208226] = "Таємничий Лист"
    t[208227] = "Таємничий Лист"
    t[208230] = { name = "Підвіска Анаї", fen = "A worn, ancient pendant that has obviously been treasured.", fua = "Зношена прадавня підвіска, якою вочевидь дуже дорожили." }
    t[208231] = { name = "Талісман Надії", fen = "A druidic charm attached to a beaded braid of leather.", fua = "Друїдський оберіг, прикріплений до плетеної шкіряної стрічки з намистинами." }
    t[208232] = { name = "Обпалена Дарнаська Накидка", fen = "Faded purple, silver, and gold are woven through the cloth, though the edges are blackened.", fua = "Крізь тканину виткані вицвілі пурпур, срібло й золото, хоча краї почорніли." }
