    t[208461] = { name = "Якась Книга Медіва", fen = "This book of Medivh contains vast forbidden records of... the Guardian's party supplies?", fua = "Ця книга Медіва містить безліч заборонених записів про... святкові припаси Опікуна?" }
    t[208462] = { name = "Флакон Веселоджерела", fen = "A powerful orange energy drink. Considered a healthier alternative to its purple variant.", fua = "Потужний помаранчевий енергетик. Вважається здоровішою альтернативою фіолетовому різновиду." }
    t[208463] = { name = "Шолом Сноваладарювання", fen = "This spiky, metal nightcap is rumored to be capable of controlling those in the deepest slumber. If only the wearer would stop falling asleep...", fua = "Подейкують, що цей шипастий металевий нічний ковпак здатен керувати тими, хто поринув у найглибший сон. Якби ж тільки власник перестав засинати..." }
    t[208464] = { name = "Глек для Утримання Вогнекаменя", fen = "This once contained the Firestone, an object prone to spontaneously igniting. Repeatedly. The jar now seems empty.", fua = "Колись тут зберігався Вогнекамінь — предмет, схильний до спонтанного займання. Знову й знову. Тепер глек, схоже, порожній." }
    t[208465] = { name = "Здравиці Елуни", fen = "A pair of ornate goblets said to bless the drinkers when they clink together.", fua = "Пара оздоблених кубків, що нібито благословляють тих, хто п'є, коли дзенькнути ними одне об одне." }
    t[208466] = { name = "Небесна Морквина", fen = "Known to have blessed the hastiest mounts in the cosmos. Why is it on a stick?", fua = "Кажуть, вона благословила найпрудкіших їздових створінь у космосі. Чому ж вона на палиці?" }
    t[208467] = { name = "Личинкова Квінтесенція", fen = "This container of squirming grubs should be used to douse... something. But you're fairly certain you don't want to know what that is.", fua = "Цей контейнер із звивистими личинками має чимось... щось окропити. Але ви майже певні, що не хочете знати, чим саме." }
    t[208468] = { name = "Мехаключ З4К0Н0Д4В3Ц", fen = "Bestows wheels of fury upon the rider. Four of them to be specific.", fua = "Дарує вершникові колеса люті. А точніше — чотири." }
    t[208469] = { name = "Загайний Кристал", fen = "Your drive to keep moving just vanishes as you hold this multicolored gemstone.", fua = "Ваше прагнення рухатися просто зникає, щойно ви берете цей різнобарвний самоцвіт." }
    t[208482] = { name = "Серце Часокузні", fen = "Within its temporal shell lies a radiant spark born from time itself.", fua = "У його часовій оболонці лежить сяйна іскра, народжена самим часом." }
