    t[208564] = { name = "Малий Зелений Трофей Завоювання", fen = "A testament to your notable victories on the battlefield.", fua = "Свідчення ваших визначних перемог на полі бою." }
    t[208565] = { name = "Зелений Трофей Завоювання", fen = "A testament to your incredible victories on the battlefield.", fua = "Свідчення ваших неймовірних перемог на полі бою." }
    t[208566] = { name = "Великий Зелений Трофей Завоювання", fen = "A testament to your monumental victories on the battlefield.", fua = "Свідчення ваших грандіозних перемог на полі бою." }
    t[208567] = "Тріснута Медаль Завоювання"
    t[208571] = { name = "Листівка Ремісничого Консорціуму", fen = "A special notice for eager competitors of all ranks!", fua = "Особливе оголошення для завзятих суперників усіх рангів!" }
    t[208576] = { name = "Буйна Частинка Відновлення", fen = "A mote capable of restoring the Tattered Dreamleaf a large amount.", fua = "Частинка, здатна значно відновити Подертий сонолист." }
    t[208578] = { name = "Концентрований Мудрий Пергамент", fen = "This vellum details incantations that can guide shadowflame away from the wielder. Crafted in tandem with Master Enchantress Shalasar.", fua = "Цей пергамент описує заклинання, що відводять тіньове полум'я від власника. Створено разом із чаклункою-майстринею Шаласар." }
    t[208581] = { name = "Сяйна Цяточка Попелу", fen = "Coarse ash that finds itself binding to various pieces of equipment. Can only be removed by disenchanting.", fua = "Грубий попіл, що чіпляється до різних предметів спорядження. Прибрати його можна лише розчаклуванням." }
    t[208592] = { name = "Руна Тіньового Зв'язування", fen = "A powerful rune that strengthens as it's damaged. Crafted in tandem with Master Scribe Lydiara.", fua = "Потужна руна, що міцнішає від ушкоджень. Створено разом із писарем-майстринею Лідіарою." }
    t[208597] = { name = "Нотатки Едварда", fen = "A stack of journals that detail anything important to the crafting of Fyr'alath.", fua = "Стос щоденників, що описують усе важливе для створення Фір'алата." }
    t[208599] = { name = "Буйнозелене Зерня Сну", fen = "A glowing seed from the Dream's flora. It pulses faintly with wild magic.", fua = "Сяйне зерня з флори Сну. Воно ледь помітно пульсує дикою магією." }
    t[208600] = "Часотканні Наплічники Хромі"
    t[208606] = { name = "Серце Сомнаґори", fen = "A sap-covered Mandragora heart. It smells like peaches and fresh soil.", fua = "Вкрите соком серце мандрагори. Пахне персиками та свіжою землею." }
    t[208614] = { name = "Віщування Первісного Полум'я", fen = "A vision of endless flame.", fua = "Видіння нескінченного полум'я." }
    t[208615] = "Розплутувальне Веретено Німуе"
    t[208616] = "В'язень Снів, Кросна Великого Циклу"
    t[208619] = { name = "Трагедія Еринетрії", fen = "May her name, and her lesson, be ever remembered.", fua = "Нехай її ім'я та її урок назавжди залишаться в пам'яті." }
    t[208649] = { name = "Про Природу Сну", fen = "Written by an unnamed dragon. Note: Contains speculation not to be shared with the keepers.", fua = "Написано безіменним драконом. Примітка: містить припущення, якими не варто ділитися з охоронцями." }
    t[208658] = "Дзеркало Смирення"
    t[208662] = { name = "Загартований Світлом Шукач", fen = "An ordinary weapon to the Army of the Light, a cursed bane to the demons remaining on Argus.", fua = "Звичайна зброя для Армії Світла й проклятий згуб для демонів, що лишилися на Аргусі." }
    t[208676] = { name = "Пророслий Паросток", fen = "Dug up seed of a violet forget-me-not that has already begun to sprout.", fua = "Викопане зерня фіолетового незабудька, що вже почало проростати." }
    t[208677] = { name = "Кристалевий Молот Ередату", fen = "A common weapon used by many in the greatest city of the eredar.", fua = "Звичайна зброя, якою користувалися багато хто в найбільшому місті ередарів." }
    t[208680] = "Вітроносний Велоцідракон: Броня Дня Всіх Святих"
    t[208683] = { name = "Ритуальний Жезл Арінору", fen = "None of the Arinor groundskeeper ritualists survive, but their tools remain.", fua = "Жоден з ритуалістів-доглядачів Арінору не вцілів, але їхні знаряддя зосталися." }
    t[208684] = { name = "Скорбота Анахорета", fen = "An anchorite forced to rely on a blade has already failed at least once.", fua = "Анахорет, змушений покладатися на клинок, уже хоч раз зазнав поразки." }
    t[208685] = { name = "Віднайдений Клинок Каариносу", fen = "Few relics of the lost peaks of Kaarinos remain, but are precious to those who remember that land.", fua = "Збереглося мало реліквій із втрачених вершин Каариносу, та вони безцінні для тих, хто пам'ятає ці землі." }
    t[208686] = { name = "Веленітський Дворучний Меч", fen = "Once carried by those eredar sworn to Velen's service before darkness came to Argus.", fua = "Колись його носили ередари, що присягнули на службу Велену, перш ніж темрява прийшла на Аргус." }
    t[208688] = { name = "Гірницька Кирка Телаасті", fen = "Few remember the rich mines of the Telaasti Reaches, consumed by the construction of Antorus millennia ago.", fua = "Мало хто пам'ятає багаті шахти Телаастійських просторів, поглинуті будівництвом Анторуса тисячоліття тому." }
    t[208690] = { name = "Ключ зі Сплетіння Коренів", fen = "An odd tangle of roots shaped like a key. What could it unlock?", fua = "Дивне сплетіння коренів у формі ключа. Що ж він може відмикати?" }
    t[208691] = { name = "Скупчення Аргуніту", fen = "A gift from one of Arzaal's allies remaining on Argus. Contains Veiled Argunite and other materials.", fua = "Подарунок від одного зі союзників Арзаала, що лишилися на Аргусі. Містить завуальований аргуніт та інші матеріали." }
    t[208692] = { name = "Прадавній Фоліант у Сплетінні Коренів", fen = "What seems to be an ancient herbalist's journal, complete with hand-drawn diagrams of floral anatomy. Vinna would want to see this.", fua = "Схоже на прадавній щоденник травника з намальованими від руки схемами анатомії рослин. Вінна захотіла б його побачити." }
    t[208702] = { name = "Сутність Спогаду", fen = "Essence of one of Gracus' most difficult memories.", fua = "Сутність одного з найважчих спогадів Ґракуса." }
    t[208732] = { name = "Серце Батожника", fen = "The dense core of a lasher. A reddish-green ooze coats the exterior with a pungent smell.", fua = "Щільне осердя батожника. Зовні вкрите червонясто-зеленим слизом із різким запахом." }
    t[208733] = { name = "Сопілка з Драконячого Рога", fen = "A three-holed flute, roughly carved out of dragon horn.", fua = "Сопілка з трьома отворами, грубо вирізана з драконячого рога." }
    t[208734] = { name = "Промоклий Гросбух", fen = "So soaked, the ink is nearly running off the page.", fua = "Настільки промок, що чорнило ось-ось стече зі сторінок." }
    t[208736] = { name = "Домашнє Завдання Учня Астролога", fen = "The star charts documented here appear... off.", fua = "Зоряні карти, накреслені тут, виглядають... дивно." }
    t[208737] = { name = "Продірявлений Зуб Бакара", fen = "Someone has carefully whittled a hole through this baby bakar tooth.", fua = "Хтось обережно проробив отвір у цьому молочному зубі бакара." }
    t[208738] = { name = "Ефемерна Груша", fen = "When squeezed the juices released have magical properties.", fua = "При стисканні її сік набуває магічних властивостей." }
    t[208742] = "Оновлений Протодракон: Броня Хмільного Свята"
