    t[208752] = "Ріг Кенаріуса"
    t[208755] = { name = "Посох Прадавнього Жерця Душ", fen = "An ornate tool for a forgotten holy ritual, unperformed for millennia.", fua = "Оздоблене знаряддя для забутого священного ритуалу, не виконуваного тисячоліттями." }
    t[208757] = "Рецепти Еш для Втіхи та Живлення Ваших Друзів-Рослин"
    t[208770] = { name = "Камінь Духа Листя", fen = "This stone vibrates with life. A faint vision of the Dream flashes in your mind as a low muffled voice calls for you to release it.", fua = "Цей камінь пульсує життям. Слабке видіння Сну спалахує у вашому розумі, а приглушений голос благає звільнити його." }
    t[208775] = { name = "Дослідницькі Нотатки про Асфодель", fen = "The slightly singed parchment is scribbled with observational notes and ink smudges.", fua = "Злегка обпалений пергамент списаний спостережними нотатками й чорнильними плямами." }
    t[208781] = { name = "Симбіотичні Рукавиці Сяйних Спор", fen = "Notes detailing the properties of Zaralek Glowspores and their various uses. Written by Master Leatherworker Erden.", fua = "Нотатки про властивості Заралекських сяйних спор та їхні різноманітні застосування. Написані шкіряником-майстром Ерденом." }
    t[208782] = { name = "Симбіотичні Рукавиці Сяйних Спор", fen = "This grip is capable of adapting to the unpredictable temperament of Shadowflame.", fua = "Це руків'я здатне пристосовуватися до непередбачуваної вдачі Тіньополум'я." }
