    t[208798] = { name = "Записані Спогади Сторожі Тіра", fen = "The disc emanates holy energy. A vessel to the recorded history of a new age of silver.", fua = "Диск випромінює священну енергію. Вмістилище записаної історії нової срібної доби." }
    t[208801] = { name = "Жменя Уламків", fen = "Something interesting may lie within the rocks and mud.", fua = "Серед каміння та бруду може ховатися щось цікаве." }
