    t[208937] = { name = "Брудний Щоденник", fen = "You found this journal in the grass, its pages are covered with mud. The very last pages of its content is a window to a broken soul.", fua = "Ви знайшли цей щоденник у траві, його сторінки вкриті багном. Самі останні сторінки - це вікно у зламану душу." }
    t[208938] = { name = "Метаморфна Сажа", fen = "The lingering embers in this ash seem to change shape as you watch them.", fua = "Жевріючі вуглинки в цьому попелі немовби змінюють форму, коли ви на них дивитеся." }
    t[208945] = { name = "Параказуальний Ящик", fen = "Unfortunately, for the health of the timeline, it is recomended this be opened after being sent.", fua = "На жаль, заради здоров'я часової лінії рекомендується відкривати його після відправлення." }
    t[208946] = { name = "Палаюча Руна", fen = "A mysterious etching that emanates an uncomfortable heat.", fua = "Загадкове різьблення, що випромінює неприємний жар." }
    t[208947] = { name = "Зачарована Лійка", fen = "More powerful than an average watering can.", fua = "Потужніша за звичайну лійку." }
    t[208949] = { name = "Нагрітий Камінь Повернення", fen = "Warm and inviting, great for heating up hands.", fua = "Теплий і затишний, чудово підходить для зігрівання рук." }
    t[208950] = { name = "Смарагдове Волокно", fen = "A hearty fiber that possesses remarkable tensile strength.", fua = "Міцне волокно, що має надзвичайну міцність на розрив." }
    t[208951] = { name = "Параказуальне Скупчення", fen = "A crystal formation emerging just before the collision of two timeways, made of compressed sands of time.", fua = "Кристалічне утворення, що виникає саме перед зіткненням двох часоплинів, складене зі стиснених пісків часу." }
    t[208952] = { name = "Похвальний Лист Соридормі", fen = "A letter of recognition signed by Soridormi.", fua = "Лист про визнання, підписаний Соридормі." }
    t[208955] = "Викрадена Скалка Сну"
    t[208956] = { name = "Неушкоджене Вбрання Первісника", fen = "It is a good thing blood on the clothes was optional. It may have taken a very long time otherwise.", fua = "Добре, що кров на одязі була необов'язковою. Інакше це могло б тривати дуже довго." }
    t[208977] = { name = "Дуже Важливі Дерев'яні Припаси", fen = "Lady Moonberry insists retrieving these crates of supplies is of the highest priority for setting up camp.", fua = "Леді Мунбері наполягає, що повернення цих ящиків із припасами - найвищий пріоритет для облаштування табору." }
