    t[208985] = { name = "Кумедний Капелюх", fen = "A fun party hat brought to the Emerald Dream by Lady Moonberry for the purpose of hatting druids.", fua = "Веселий святковий капелюх, принесений у Смарагдовий Сон леді Мунбері, щоб одягати його на друїдів." }
