    t[209018] = { name = "Цукор Сяйнокраплі", fen = "Soft, airy pollen collected from Shaded Glowdrops. Intensely sweet smelling, vanilla forward, with a hint of cinnamon, hence the name. However, it is exceedingly unsafe to ingest.", fua = "М'який, легкий пилок, зібраний із Затінених Сяйнокрапель. Інтенсивно солодкий аромат, ванільний на передньому плані, з ноткою кориці, звідки й назва. Однак він украй небезпечний для вживання." }
    t[209019] = "Чарований Безцукровий Сорбет з Вогневоди"
    t[209021] = { name = "Скинуте Велике Пір'я", fen = "Long, soft feathers shed from a great somnowl.", fua = "Довге, м'яке пір'я, скинуте великою дрімучою совою." }
    t[209033] = { name = "Зношений Молитовний Жезл зі Скверносталі", fen = "Etched into the rod are the words 'His might is our faith. His word is our might. His will is the rebirth of the Burning Crusade.'", fua = "На жезлі викарбувано слова: «Його міць - наша віра. Його слово - наша міць. Його воля - відродження Палаючого Хрестового Походу.»" }
    t[209034] = { name = "Напівскладені Плани Вторгнення", fen = "Incomplete plans for a new Legion invasion of a distant world you've never heard of.", fua = "Неповні плани нового вторгнення Легіону на далекий світ, про який ви ніколи не чули." }
    t[209036] = { name = "Сховок Скарбів Амірдрассілу", fen = "Rewards a piece of equipment for your Loot Specialization.", fua = "Винагороджує предметом спорядження для вашої спеціалізації здобичі." }
    t[209037] = { name = "Сховок Скарбів Амірдрассілу", fen = "Rewards a piece of equipment for your Loot Specialization.", fua = "Винагороджує предметом спорядження для вашої спеціалізації здобичі." }
    t[209048] = { name = "Обпалена Листівка", fen = "Parchment smelling strongly of sulfur and ash, covered in scrawled writings and smudged charcoal.", fua = "Пергамент, що сильно пахне сіркою й попелом, укритий нашкрябаними написами й розмазаним вугіллям." }
    t[209049] = { name = "Сутність Нескінченного Полум'я", fen = "The tiny shard looks fragile but ever bright. It is not too hot to touch, but its warmth fades.", fua = "Крихітна скалка здається крихкою, але незмінно сяйливою. Вона не надто гаряча на дотик, але її тепло згасає." }
    t[209055] = "Третя Частина Прискорювача"
    t[209060] = { name = "Зелений Панцеродон", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
