    t[209316] = { name = "Козяче Молоко в Кухлі-Черепі", fen = "A true adventurer's go-to beverage for all things awesome and wholesome.", fua = "Улюблений напій справжнього шукача пригод на всі випадки — смачний і поживний." }
    t[209317] = { name = "Каражанська Родзинка", fen = "The twist is the spirit of kiwi haunting the glass.", fua = "Родзинка - це дух ківі, що витає над келихом." }
    t[209318] = { name = "Даларанський Сліпучник", fen = "Mildly enchanted to make the imbiber dazzle, too.", fua = "Злегка зачарований, щоб і той, хто п'є, теж засліплював." }
    t[209319] = { name = "Подих Хорнсвога", fen = "A colorful and bitter concoction that puts a spring in one's step.", fua = "Барвиста й гірка суміш, що додає бадьорості ході." }
    t[209322] = { name = "Гострочуйне Темне Пиво Ніффенів", fen = "Pungent and deep like the Sulfur Wastes in Zaralek Cavern.", fua = "Різке й глибоке, наче Сірчані Пустки в Печері Заралек." }
    t[209323] = { name = "Смарагдовий Час Снів", fen = "Balanced tea with relaxing herbal notes.", fua = "Збалансований чай із заспокійливими трав'яними нотками." }
    t[209324] = { name = "Лазурове Силовинне Вино", fen = "Not strong enough to get anyone drunk, but it's delicious all the same.", fua = "Не досить міцне, щоб когось сп'янити, та від цього не менш смачне." }
    t[209326] = { name = "Світлий Ель Маруків", fen = "A uniquely light and rich ale perfect for a grand feast.", fua = "Винятково легкий і насичений ель, ідеальний для пишного бенкету." }
