    t[209416] = { name = "Уламки Черепашачої Шкаралупи", fen = "Eggshell fragments from the turtles living in the area.", fua = "Уламки шкаралупи яєць черепах, що мешкають у цій місцевості." }
    t[209419] = { name = "Обвуглені Рештки Стихійного", fen = "These large fragments were found amongst powerful Druids of the Flame within the Dreamsurge. They appear to be drawn to each other.", fua = "Ці великі уламки знайдено серед могутніх Друїдів Полум'я у Сплеску Сну. Здається, вони притягуються одне до одного." }
    t[209428] = { name = "Камінь Духа Вовка", fen = "This stone is sharp at its edges. It gives you a sense of confidence, patience, and focus--all the properties of an apex hunter.", fua = "Цей камінь гострий по краях. Він дарує вам відчуття впевненості, терпіння й зосередженості -- усіх рис найвищого мисливця." }
    t[209429] = { name = "Камінь Духа Місяця", fen = "This brittle stone has nothing unique about it--until you touch it and feel the heavy weight of the past creeping in on you.", fua = "У цьому крихкому камені немає нічого особливого -- доки ви не торкнетеся його й не відчуєте, як на вас насувається важкий тягар минулого." }
    t[209430] = { name = "Камінь Духа Ведмедя", fen = "This stone is warm to the touch. You can feel raw rage emanating from it. The spirit inside might be dangerous.", fua = "Цей камінь теплий на дотик. Ви відчуваєте, як від нього виходить чиста лють. Дух усередині може бути небезпечним." }
    t[209431] = { name = "Грибковий Скребок", fen = "A device made specifically to scrape away fungal mold from items. Usually sold by the mushroom expert Finneas Fungulf.", fua = "Пристрій, створений спеціально для зчищання грибкової плісняви з предметів. Зазвичай продається експертом із грибів Фіннеасом Фангалфом." }
