    t[210002] = { name = "Попеляста лозоходна паличка", fen = "A dowsing rod that allows the user the ability to disenchant powerful pieces of equipment in order to find Radiant Fleck of Ash.", fua = "Лозоходна паличка, що дає власнику здатність розчаровувати потужне спорядження, щоб відшукати Осяйну крихту попелу." }
    t[210003] = { name = "Мудрий пергамент Шаласар", fen = "Crafted in tandem with Shalasar Glimmerdusk.", fua = "Виготовлено разом із Шаласар Мерехтливосутінь." }
    t[210008] = { name = "Жевріюча руна зв'язування", fen = "Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location.", fua = "Навчає викликати цей засіб пересування. Цей засіб пересування змінюється залежно від вашої навички верхової їзди та місцезнаходження." }
    t[210009] = { name = "Прототип рукояті сновидного листя", fen = "A prototype rune made by Erden from leathery Shadowed Dreamleaf.", fua = "Прототип руни, зроблений Ерденом із шкірястого затіненого сновидного листя." }
    t[210010] = { name = "Нотатки Ердена про симбіотичні спори", fen = "Notes detailing the necessities to craft an experimental Symbiotic Glowspore Grip. Written by Master Leatherworker Erden.", fua = "Нотатки з переліком того, що потрібно для виготовлення експериментальної симбіотичної рукояті осяйних спор. Написані майстром-чинбарем Ерденом." }
    t[210011] = { name = "Нотатки Шаласар про мудру магію", fen = "Notes detailing the necessities to craft an experimental Sophic Vellum. Written by Master Enchantress Shalasar Glimmerdusk.", fua = "Нотатки з переліком того, що потрібно для виготовлення експериментального мудрого пергаменту. Написані майстринею-чарувальницею Шаласар Мерехтливосутінь." }
    t[210012] = { name = "Симбіотична рукоять осяйних спор Ердена", fen = "An untested Glowspore Grip.", fua = "Неперевірена рукоять осяйних спор." }
    t[210014] = { name = "Загадкове позачасове насіння", fen = "Dreamseeds waiting to be awakened.", fua = "Сновидне насіння, що чекає на пробудження." }
    t[210016] = { name = "Запона сонної сови", fen = "Call upon somnowl Bodwin to give you a temporary stealth aura.", fua = "Прикличте сонну сову Бодвіна, щоб вона дарувала вам тимчасову ауру непомітності." }
    t[210023] = { name = "Клапоть пергаменту", fen = "A note that might shed light on how the Prophet of the Flame is blocking our reinforcements.", fua = "Записка, що може пролити світло на те, як Пророк Полум'я перешкоджає нашим підкріпленням." }
    t[210024] = { name = "Комплект: Часові тягарі", fen = "Emblems of the infinite and bronze dragonflights, suitable for wearing on one's shoulders.", fua = "Емблеми безкінечного й бронзового драконових роїв, придатні для носіння на плечах." }
    t[210027] = { name = "Видобутий попелястий пил", fen = "Your lack of expertise has irreversibly destroyed the previous item.", fua = "Брак вашого вміння безповоротно знищив попередній предмет." }
