    t[210174] = { name = "Формула: Ілюзорна оздоба: Сновидіння", fen = "Teaches you how to perform the Illusory Adornment: Dreams enchantment.", fua = "Навчає вас накладати чари Ілюзорна оздоба: Сновидіння." }
    t[210175] = { name = "Формула: Чари зброї — Сновидна відданість", fen = "Teaches you how to perform the Dreaming Devotion enchantment.", fua = "Навчає вас накладати чари Сновидна відданість." }
    t[210180] = { name = "Смарагдовий летокамінь", fen = "Contains 100 Flightstones.", fua = "Містить 100 летокаменів." }
    t[210184] = { name = "Напівпорожнє зілля сну без сновидінь", fen = "In here, it is much easier to simply call it \"water\".", fua = "Тут набагато простіше називати це просто \"водою\"." }
    t[210185] = { name = "Зілля-бризкалка нарколепсії", fen = "Given the apparent goal of putting an enemy to sleep, it seems counterintuitive to douse them in the process.", fua = "Зважаючи на очевидну мету приспати ворога, видається дивним обливати його при цьому." }
    t[210189] = { name = "Реміснича лінза екзарха Гатаару", fen = "A small golden lens, worn with age and use. The precisely-carved facets allow artificers to see the energy channels running through the crystals used in their work.", fua = "Маленька золота лінза, потерта віком і використанням. Точно вирізьблені грані дозволяють майстрам бачити канали енергії, що пронизують кристали, з якими вони працюють." }
    t[210190] = { name = "Жаркорінь", fen = "Smoldering to the touch. It would make for a fantastic catalyst for your concoctions, but good luck convincing any herbalist to play with fire.", fua = "Жевріє на дотик. Це був би неперевершений каталізатор для ваших мікстур, та спробуй ще переконати хоч якогось травника гратися з вогнем." }
    t[210193] = { name = "Експериментальний ловець снів", fen = "Bringing a magnet into the Emerald Dream does not inherently make it a dreamcatcher, but someone had to try it.", fua = "Магніт, принесений до Смарагдового Сну, не стає сам собою ловцем снів, але комусь же треба було спробувати." }
    t[210194] = { name = "Безсоннятрон", fen = "A carefully calibrated device which emits a high-pitched sound only audible to sleeping druids.", fua = "Ретельно налаштований пристрій, що видає високий звук, чутний лише сплячим друїдам." }
    t[210197] = { name = "Невилуплена батарея", fen = "Although seemingly mistaken for a misplaced egg, one might wonder what might have emerged if its incubation had not been interrupted.", fua = "Хоч це, схоже, помилково сприйняли за загублене яйце, можна замислитися, що вилупилося б, якби його інкубацію не перервали." }
    t[210198] = { name = "Виснажена Батарея", fen = "What were you expecting, anyway?", fua = "А чого ви взагалі сподівалися?" }
    t[210199] = { name = "Подертий Сонцелист", fen = "Remnant of a Shadowed Dreamleaf.", fua = "Залишок затіненого сонцелиста." }
    t[210200] = { name = "Скам'яніла надія", fen = "A pristine gemstone born from the husk of a thoroughly desecrated tree.", fua = "Бездоганний самоцвіт, народжений з оболонки дощенту осквернілого дерева." }
    t[210201] = { name = "Жменя дрібних камінців", fen = "Ordinary rocks, significant only to you as a memoire to the time you scraped a few rocks off of a statue.", fua = "Звичайні камінці, цінні лише для вас як згадка про той час, коли ви зішкребли кілька камінців зі статуї." }
    t[210202] = { name = "Згущений сновидний камінь", fen = "An incredible feat of gemcutting that bears a striking resemblance to your own lauded handiwork. How did it end up here?", fua = "Неймовірний витвір гранування самоцвітів, що разюче схожий на вашу власну прославлену роботу. Як він тут опинився?" }
    t[210203] = "Наручі Джерела"
    t[210204] = "Наручі Згасаючого Полум'я"
    t[210205] = "Наручі Пильного Захисника"
    t[210206] = "Наручі Зеленого Святилища"
    t[210207] = { name = "Підсилений відновний симбіот", fen = "The Glowspore Symbiotes grow stronger.", fua = "Симбіоти осяйних спор стають сильнішими." }
    t[210208] = { name = "Жмут хутра снохода-шаблезуба", fen = "While too small a sample to do anything with, this dreamsaber fur is a fascinating material to study the properties of.", fua = "Зразок надто малий, щоб щось із ним зробити, але це хутро снохода-шаблезуба — захопливий матеріал для вивчення його властивостей." }
    t[210211] = { name = "Скинута луска чарівного дракона", fen = "Shimmering and iridescent, these scales could be used in decorative armor. However, they likely wouldn't stand up well to combat.", fua = "Мерехтлива й переливчаста, ця луска згодилася б для оздобного обладунку. Утім, у справжньому бою вона навряд чи витримала б." }
    t[210214] = "Намисто Уробороса"
    t[210215] = { name = "Кіготь сновидного пазуряки", fen = "Extremely sharp, remarkably durable, and still in fantastic condition! There is a little tree bark stuck to it, though.", fua = "Надзвичайно гострий, на диво міцний і досі у чудовому стані! Щоправда, до нього прилипла дрібка кори." }
    t[210217] = { name = "Малий сновидний дарунок", fen = "Contains a unique cosmetic or a small amount of profession reagents.", fua = "Містить унікальний косметичний предмет або невелику кількість реагентів професій." }
    t[210218] = { name = "Пухкий сновидний дарунок", fen = "Contains a unique battle pet or a medium amount of profession reagents.", fua = "Містить унікального бойового улюбленця або середню кількість реагентів професій." }
    t[210219] = { name = "Велетенський сновидний дарунок", fen = "Contains a unique mount or a large amount of profession reagents.", fua = "Містить унікального їздового або велику кількість реагентів професій." }
    t[210222] = { name = "Втихомирений елемент", fen = "A quelled element capable of being rebound to the Concentrated Sophic Vellum.", fua = "Приборканий елемент, здатний знову зв'язатися з Концентрованим мудрим пергаментом." }
    t[210223] = { name = "Нестабільний елемент", fen = "An element still needing to be stabilized.", fua = "Елемент, який ще потрібно стабілізувати." }
    t[210224] = { name = "Мале смарагдове суцвіття", fen = "Contains a small amount of Dragon Isles Supplies and Flightstones. Includes a minute chance to get the Winter Night Dreamsaber mount.", fua = "Містить невелику кількість Припасів Драконових Островів і летокаменів. Включає мізерний шанс отримати їздового зимовнічного снохода-шаблезуба." }
    t[210225] = { name = "Середнє смарагдове суцвіття", fen = "Contains a medium amount of Dragon Isles Supplies and Flightstones. Includes a very small chance to get the Winter Night Dreamsaber mount.", fua = "Містить середню кількість Припасів Драконових Островів і летокаменів. Включає дуже невеликий шанс отримати їздового зимовнічного снохода-шаблезуба." }
    t[210226] = { name = "Велике смарагдове суцвіття", fen = "Contains a large amount of Dragon Isles Supplies and Flightstones. Includes a small chance to get the Winter Night Dreamsaber mount.", fua = "Містить велику кількість Припасів Драконових Островів і летокаменів. Включає невеликий шанс отримати їздового зимовнічного снохода-шаблезуба." }
    t[210227] = { name = "Чарівне перо Кьонзу", fen = "A small feather of Q'onzu. Strange, its markings changed to look like a Faerie Dragon's.", fua = "Маленьке перо Кьонзу. Дивно, але його візерунок змінився й тепер схожий на візерунок чарівного дракона." }
