    t[210575] = { name = "Камінь Пам'яті Гатууна", fen = "Early morning in the Conservatory. Birdsong.", fua = "Рано-вранці в оранжереї. Пташиний спів." }
    t[210576] = { name = "Камінь Пам'яті Ромуула", fen = "The defense crystal had one broken condenser. Just one.", fua = "У захисному кристалі був один зламаний конденсатор. Лише один." }
    t[210577] = { name = "Камінь Пам'яті Атаані", fen = "Ink stains on his tendrils where they touched his schematics.", fua = "Плями чорнила на його щупальцях там, де вони торкалися його креслень." }
    t[210578] = { name = "Камінь Пам'яті Арзаала", fen = "I stepped away from their blood when it touched my hooves.", fua = "Я відступав від їхньої крові, коли вона торкалася моїх копит." }
    t[210579] = { name = "Камінь Пам'яті Бороса", fen = "It was easier to flee a planet than defend it. I agreed. Again and again.", fua = "Утекти з планети було легше, ніж захищати її. Я погоджувався. Знову й знову." }
    t[210580] = { name = "Камінь Пам'яті Нобундо", fen = "In that moment, I was empty. I wished to live. I hoped to die.", fua = "Тієї миті я був порожнім. Я хотів жити. Я сподівався вмерти." }
    t[210581] = { name = "Камінь Пам'яті Ішани", fen = "I saw his face when I awoke. There were tears in his eyes. Then the light went out of them.", fua = "Я бачила його обличчя, коли прокинулася. У його очах були сльози. Тоді світло згасло в них." }
    t[210582] = { name = "Камінь Пам'яті Джадаара", fen = "Clearing away the broken walls. There were children.", fua = "Розчищаючи зруйновані мури. Там були діти." }
    t[210583] = "Камінь Пам'яті Куроса"
    t[210584] = { name = "Камінь Пам'яті Наїель", fen = "They had catapults. We should have seen their tracks outside the walls.", fua = "У них були катапульти. Ми мали б помітити їхні сліди за мурами." }
    t[210585] = "Камінь Пам'яті Аесома"
    t[210586] = { name = "Камінь Пам'яті Аками", fen = "I was something, not someone. Trading chains, again and again.", fua = "Я був чимось, а не кимось. Міняв кайдани, знову й знову." }
    t[210587] = "Камінь Пам'яті Немураана"
    t[210588] = { name = "Камінь Пам'яті Омана", fen = "The passing of Hespera, lost to the wreck of the Genedar.", fua = "Загибель Геспери, що згинула в уламках Генедара." }
    t[210591] = { name = "Камені Пам'яті Тішамаат", fen = "A smooth, palm-sized stone inscribed with a painful memory. It is deceptively heavy.", fua = "Гладенький камінь завбільшки з долоню, на якому викарбувано болісний спогад. Він оманливо важкий." }
