    t[210944] = { name = "Смарагдовий Знак Майстерності", fen = "Awarded for outstanding service to Dragonkind. Bring it to Theozhaklos the Curious at the Wellspring Overlook in the Emerald Dream to receive powerful equipment for your efforts.", fua = "Вручається за визначну службу драконячій зграї. Принесіть його Теозаклосу Допитливому біля Виступу Першоджерела у Смарагдовому Сні, щоб отримати потужне спорядження за свої зусилля." }
    t[210945] = { name = "Зорепас", fen = "Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.", fua = "Навчає вас прикликати цього їздового звіра. Цей звір змінюється залежно від вашого вміння верхової їзди та місцеперебування." }
    t[210946] = { name = "Мамміф", fen = "Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.", fua = "Навчає вас прикликати цього їздового звіра. Цей звір змінюється залежно від вашого вміння верхової їзди та місцеперебування." }
    t[210947] = { name = "Спотворена Полум'ям Дивовижа", fen = "A reminder of the fiery future Fyrakk sought. Kirasztia at the Wellspring Overlook in the Emerald Dream may know how to unlock the secrets that lay within.", fua = "Нагадування про вогняне майбутнє, якого прагнув Фіракк. Кірасзтія біля Виступу Першоджерела у Смарагдовому Сні, можливо, знає, як розкрити приховані всередині таємниці." }
    t[210948] = { name = "Уявокрил", fen = "Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.", fua = "Навчає вас прикликати цього їздового звіра. Цей звір змінюється залежно від вашого вміння верхової їзди та місцеперебування." }
    t[210950] = { name = "Прозріння Кьонзу", fen = "Who needs material possessions when you've witnessed Q'onzu?", fua = "Кому потрібні матеріальні статки, коли ви побачили Кьонзу?" }
