    t[211372] = { name = "Втішний Приз Кьонзу", fen = "Next time answer a thousand!", fua = "Наступного разу відповідай на тисячу!" }
    t[211373] = { name = "Торба Багатьох Див", fen = "Awarded to one who would answer Q'onzu's one hundred questions.", fua = "Винагорода для того, хто відповів на сто запитань Кьонзу." }
    t[211374] = { name = "Заплутаний Клубок Таємниць", fen = "Finally, a chance to learn the wisdom of Q'onzu.", fua = "Нарешті нагода осягнути мудрість Кьонзу." }
    t[211375] = { name = "Вічножевріюча Жарина", fen = "The pure heat radiating from its core leaves it almost too hot to handle.", fua = "Чистий жар, що випромінюється з її осердя, робить її майже надто гарячою, щоб брати в руки." }
    t[211376] = { name = "Насіннєцвіт", fen = "The bloom of a plant infused with lifebloom essence. These rare sprouts have powerful aesthetic and revitalizing properties.\n\n\n\nUsed to procure items from Talisa Whisperbloom in the Central Encampment.", fua = "Цвіт рослини, насиченої сутністю життєцвіту. Ці рідкісні паростки мають потужні окрасні й відживні властивості.\n\n\n\nСлугує для придбання предметів у Таліси Шепітоцвіт у Центральному Таборі." }
    t[211377] = { name = "Заплутаний Клубок Таємниць", fen = "Finally, a chance to learn the wisdom of Q'onzu.", fua = "Нарешті нагода осягнути мудрість Кьонзу." }
