    t[211394] = { name = "Сховок Зібраних Насінин Сну", fen = "Contains Flightstones, Bloomed treasures, and Dragon Isles Supplies", fua = "Містить летокамені, Розквітлі скарби та припаси Драконових Островів" }
    t[211395] = { name = "Дослідницькі Нотатки про Асфодель", fen = "The slightly singed parchment is scribbled with observational notes and ink smudges.", fua = "Злегка обпалений пергамент списаний спостережними нотатками й чорнильними плямами." }
