    t[212646] = { name = "Надщерблена Бронепластина", fen = "This small punched piece of metal was once strung together to make armor. Some of the holes still have remnants of string.", fua = "Цей маленький пробитий шматок металу колись зв'язували разом, щоб зробити обладунок. У деяких отворах ще лишилися рештки шнура." }
    t[212647] = { name = "Шкіряний Черевик Розміру Бакара", fen = "The remnants of this leather shoe is lined with fleece, to protect bare paws from the cold.", fua = "Залишки цього шкіряного черевика підбиті руном, щоб захистити голі лапи від холоду." }
    t[212648] = { name = "Голка з Риб'ячої Кістки", fen = "Made from the bones of a fish commonly harvested by the Tuskarr of Azure Span.", fua = "Зроблена з кісток риби, яку зазвичай виловлюють бивнерогі Лазурового Простору." }
    t[212649] = { name = "Клапоть Стьобаного Намету", fen = "This fragment of quilted fabric once made up the side of a tent. It would have been well-insulated against the elements.", fua = "Цей шматок стьобаної тканини колись складав стіну намету. Він добре захищав від негоди." }
    t[212650] = { name = "Горщик Чорнила для Татуювань", fen = "While the ink has long dried up, this little clay pot is covered in scratch-marks from tattooing needles.", fua = "Хоча чорнило давно висохло, цей маленький глиняний горщик укритий подряпинами від голок для татуювань." }
    t[212682] = { name = "Серце Води, Що Б'ється", fen = "When held the curio slowly pulses, as water begins enveloping and tightening around your heart, slowing your heartbeat.", fua = "Коли тримаєш цю дивовижу, вона повільно пульсує, а вода починає огортати й стискати ваше серце, сповільнюючи його биття." }
    t[212683] = "Куля Зубчастого Льоду"
    t[212684] = "Розколоте Серце Умбрелскула"
    t[212685] = "Фоліант Нестабільної Сили"
    t[212687] = { name = "Грубувата Іграшкова Качечка", fen = "Amidst other treasures and necessities, someone thought this was very important to keep safe.", fua = "Серед інших скарбів і потрібних речей хтось вважав вкрай важливим зберегти саме це." }
    t[212688] = { name = "Висушене в Солі Коріння", fen = "These desiccated root vegetables were likely preserved for food at once point.", fua = "Це висушене коренеплідне овочеве коріння колись, певно, заготовляли як їжу." }
    t[212692] = "Темний Капелюх Розкопувача"
    t[212756] = "Невблаганний Резонатор"
    t[212757] = "Витривала Луска Ґраніта"
    t[212761] = { name = "Мішечок Монет", fen = "Someone must have hidden these for safekeeping long, long ago.", fua = "Хтось, певно, заховав їх для збереження дуже-дуже давно." }
    t[212762] = { name = "Потьмянілий Роговий Перстень-Печатка", fen = "It seems the dracthyr got the idea for horn jewelry from the dragonkin who lived here before them.", fua = "Схоже, дратири перейняли ідею прикрас із рогів у драконідів, що жили тут до них." }
    t[212763] = { name = "Зіпсований Медовий Напій", fen = "The liquid in this bottle is cloudy and dull. While not good for drinking, it may be worth studying.", fua = "Рідина в цій пляшці каламутна й тьмяна. Хоч пити її й не варто, її, можливо, варто вивчити." }
    t[212764] = { name = "Уламок Рибальської Сітки", fen = "This bit of net was torn and repaired dozens of times before finally being stowed away.", fua = "Цей шматок сітки рвали й латали десятки разів, перш ніж нарешті відклали." }
    t[212765] = { name = "Риб'ячі Кістки", fen = "Covered in marks from draconic teeth, as if someone had enjoyed every last bite.", fua = "Вкриті слідами драконячих зубів, наче хтось смакував кожен останній шматочок." }
    t[212766] = { name = "Уламок Амфори", fen = "If you look closely, you can see clawed thumbprints preserved in the clay.", fua = "Якщо придивитися, можна побачити відбитки пазуристих великих пальців, що збереглися в глині." }
    t[212767] = { name = "Розбита Колба", fen = "The neck has been broken off this beaker, so that it may better serve as a drinking vessel.", fua = "Горло цієї колби відбили, щоб вона краще слугувала посудиною для пиття." }
    t[212768] = { name = "Кинджал Розміру Ніффена", fen = "This dagger is the perfect shape to be held in wide, clawed hands.", fua = "Цей кинджал має ідеальну форму, щоб його тримали широкі, пазуристі руки." }
    t[212769] = { name = "Подертий Розшуковий Плакат", fen = "The print has been rendered illegible, but someone has made rude drawings over the picture.", fua = "Друк став нечитабельним, але хтось намалював поверх зображення непристойні малюнки." }
    t[212770] = { name = "Розбитий Глиняний Посуд", fen = "Rather than worn by time, this appears to have been smashed by throwing knives.", fua = "Радше за все, не час його зруйнував, а метання ножів." }
    t[212771] = { name = "Обвуглені Мушлі Слимаків", fen = "The remnants of herbs suggest these made a hearty fire-roasted meal.", fua = "Залишки трав свідчать, що з них готували ситну страву, засмажену на вогні." }
    t[212772] = { name = "Фальшива Срібна Монета", fen = "Who could say if this bent coin was part of a trick, or looted by a disappointed bandit?", fua = "Хто скаже, чи ця погнута монета була частиною шахрайства, чи нею поживився розчарований бандит?" }
    t[212773] = { name = "Іржавий Медальйон", fen = "Was this stolen, or were the bandits sentimental? Either way, the inside is inaccessible.", fua = "Його вкрали чи бандити були сентиментальними? Так чи інакше, нутрощі недоступні." }
    t[212774] = { name = "Загострені Кістки Сланцекрила", fen = "The wear on these sharpened bones suggest they were used as toothpicks.", fua = "Сліди зношення на цих загострених кістках свідчать, що їх використовували як зубочистки." }
    t[212782] = { name = "Погано Збережена Реліквія", fen = "Archivists may be able to gleam some value from this relic, but it may fetch a better price in gold.", fua = "Архіваріуси, можливо, знайдуть у цій реліквії певну цінність, але за неї можна виручити більше золота." }
    t[212784] = { name = "Знищена Реліквія", fen = "Whatever value this once held for archivists has been lost with time.", fua = "Хоч би яку цінність вона колись мала для архіваріусів, її втрачено з часом." }
    t[212793] = "Торба Знахідок Розкопувача"
    t[212794] = "Важкий Заплічник Історика"
