    t[212941] = "«Легкий Доторк» Архіваріуса"
    t[212976] = { name = "Драконідське Різьблення Качки", fen = "Nothing expresses the technological advancements of a civilization more than their ability to accurately recreate a duck.", fua = "Ніщо так не виражає технологічний поступ цивілізації, як її здатність точно відтворити качку." }
    t[212977] = { name = "Драконідська Вивіска", fen = "While the words themselves are lost with time, the very presence of a sign implies a system of writing and civilization dating back countless generations.", fua = "Хоча самі слова загубилися в часі, сама лише наявність вивіски передбачає систему письма й цивілізацію, що сягає незліченних поколінь у минуле." }
    t[212978] = { name = "Палітра Драконячого Художника", fen = "Anyone can slather colors on a canvas, but the presence of a palette shows a level of deliberate intention that tickles an archivist's imagination.", fua = "Будь-хто може намазати фарби на полотно, але наявність палітри свідчить про навмисний задум, що бентежить уяву архіваріуса." }
