    t[213012] = "Спис Нічних Ельфів"
    t[213013] = "Підзорна Труба Калдорейської Вартової"
    t[213020] = { name = "Прадавня Драконідська Лопата", fen = "Through careful scrutiny, it can be determined the date of this shovel's creation. More importantly, that will reveal when agriculture was introduced.", fua = "Ретельний огляд дає змогу встановити час виготовлення цієї лопати. Що важливіше, це розкриє, коли зародилося землеробство." }
    t[213021] = { name = "Закоркований Драконідський Флакон", fen = "The cork seems to have fused with the bottle over an eternity of decay. There's as much to be learned from opening it as there is from not.", fua = "Корок, схоже, зрісся з пляшкою за вічність занепаду. З того, щоб відкрити його, можна дізнатися стільки ж, скільки і з того, щоб залишити закритим." }
    t[213022] = { name = "Драконідський Ковальський Молот", fen = "While almost impossible to determine the age of this particular hammer, the materials used to forge it can reveal much of the civilization's technology.", fua = "Хоча визначити вік саме цього молота майже неможливо, матеріали, з яких його викували, можуть розповісти чимало про технології цивілізації." }
    t[213023] = { name = "Просочений Олією Смолоскип Джарадинів", fen = "Once the djaradin discovered oil, there was nothing they wouldn't use it in. Fires, weapons, recreation, all were impacted by this new discovery.", fua = "Щойно джарадини відкрили нафту, вони почали застосовувати її геть усюди. Вогнища, зброя, розваги — усе зазнало впливу цього нового відкриття." }
    t[213024] = { name = "Закривавлений Кухоль Джарадинів", fen = "Little is known about the djaradin's specific culture, but one has to come to certain conclusions when they discover mugs stained in blood.", fua = "Про культуру джарадинів відомо небагато, але дещо можна виснувати, коли натрапляєш на кухлі, заплямовані кров'ю." }
    t[213025] = { name = "Прадавній Болт Джарадинів", fen = "As cruel a century ago as they are today, djaradin weapons have advanced little since their rise to power.", fua = "Така ж жорстока століття тому, як і нині, зброя джарадинів мало розвинулася відтоді, як цей народ здобув владу." }
    t[213026] = { name = "Величезний Драконідський Пензель", fen = "Large drakonkin wield these brushes with surprising dexterity, from painting homes to intricate murals.", fua = "Великі драконіди орудують цими пензлями з дивовижною спритністю — від фарбування домівок до вигадливих настінних розписів." }
    t[213027] = { name = "Надщерблений Драконідський Кубок", fen = "Worth a small fortune in its heyday, this poorly preserved chalice will fetch only a meager price at a local vendor.", fua = "Цей погано збережений келих за свого розквіту коштував цілий статок, але сьогодні в місцевого торгівця за нього дадуть лише жалюгідні гроші." }
    t[213028] = { name = "Тріснутий Креслярський Циркуль", fen = "Used to create vast archives of maps and sea charts, finding a compass is only the first step in discovering an ancient civilization's technological prowess.", fua = "Циркулі використовують для створення великих архівів суходільних і морських карт, і знахідка такого предмета — лише перший крок до пізнання технологічної майстерності прадавньої цивілізації." }
    t[213029] = { name = "Погнута Драконідська Виделка", fen = "A drakonid fork may seem mundane to the untrained eye, but this tool belies the sophistication of its manufacturer.", fua = "Драконідська виделка може здатися буденною недосвідченому оку, але цей інструмент видає вправність свого виготовлювача." }
    t[213030] = { name = "Іржаві Садові Ножиці", fen = "A small dot of blood marking the tip of the shears may explain why a frustrated gardener discarded this tool long ago.", fua = "Маленька крапля крові на кінчику ножиць, можливо, пояснює, чому роздратований садівник давним-давно викинув цей інструмент." }
    t[213031] = { name = "Спотворений Келих Драконідів", fen = "The years have done their damage to this goblet, but a keen eye can still learn much from the remains.", fua = "Роки добряче пошкодили цей келих, та пильне око й досі може чимало почерпнути з того, що лишилося." }
    t[213032] = { name = "Покривлений Глек Драконідів", fen = "The accompanying lid no longer fits the jar, but now can be used as a tiny saucer.", fua = "Кришка, що йде до нього, вже не пасує до глека, та тепер її можна вживати як крихітне блюдце." }
    t[213033] = { name = "Крихкі Ковальські Кліщі", fen = "This battlescarred pair of tongs have stoked fires for centuries. Tiny imperfections and knicks in the metal reveal much of what they handled.", fua = "Ці пошарпані боями кліщі роздмухували вогнища століттями. Дрібні вади й зазублини в металі чимало розповідають про те, що вони тримали." }
    t[213034] = { name = "Тріснута Миска Драконідів", fen = "Unsuitable for practical use, this lovely bowl would make an excellent centerpiece in any archaeologist's gallery.", fua = "Непридатна для практичного вжитку, ця чарівна миска стала б чудовою окрасою галереї будь-якого археолога." }
    t[213035] = { name = "Закоренілий Пензель Драктирів", fen = "Caked in a myriade of dried paints, this brush is a treasure trove of specimen samples from various pigments and solutions.", fua = "Укритий незліченними шарами засохлої фарби, цей пензель — справжня скарбниця зразків різноманітних пігментів і розчинів." }
    t[213037] = { name = "Зазублена Садова Лопатка", fen = "Years of use have seen this trowel become damaged beyond repair. Oh the stories it could tell.", fua = "Роки використання довели цю лопатку до невиправного стану. Ох і історії вона могла б розповісти." }
    t[213038] = { name = "Тріснута Лупа", fen = "This may have been helpful for reading the fine print in Neltharion's plans for the dracthyr.", fua = "Вона могла стати в пригоді для читання дрібного шрифту в планах Нелтаріона щодо драктирів." }
    t[213039] = { name = "Тонка Ложка Драконідів", fen = "Everything from utensils to cutlery serve to tell the stories of the local people in their day to day lives.", fua = "Усе, від начиння до столових приборів, слугує для оповіді про повсякденне життя місцевого народу." }
    t[213040] = { name = "Потьмянілий Амулет Джарадинів", fen = "Weathering has rendered much of the intricacies of this amulet indecipherable, but the general shape may shed some light on djaradin customs.", fua = "Через негоду більшість тонких деталей цього амулета стали нерозбірливими, та загальна форма може дещо прояснити про звичаї джарадинів." }
    t[213041] = { name = "Висохлий Сувій Джарадинів", fen = "After painstakingly collecting enough scraps to piece together this rare find, it turns out that this scroll is covered in meaningless doodles.", fua = "Після того як ви ретельно зібрали достатньо клаптів, щоб скласти докупи цю рідкісну знахідку, виявилося, що сувій укрито безглуздими каракулями." }
    t[213042] = { name = "Зотлілий Прапор Джарадинів", fen = "Flown during peacetime and war, a djaradin banner shows its age through the rips and tears it endures over a long life.", fua = "Здіймаючись у мирні часи й під час війни, прапор джарадинів виказує свій вік розривами й розривинами, яких зазнав за довге життя." }
    t[213043] = { name = "Крихка Шкіра Джарадинів", fen = "Hardly useful for crafting anymore, this leather comes from an unidentifiable source that is better left to the imagination.", fua = "Навряд чи ще придатна для ремесла, ця шкіра походить з неможливого для впізнання джерела, яке краще лишити уяві." }
    t[213044] = { name = "Потертий Амулет з Ікла", fen = "Upon closer inspection, the fang for this amulet appears to be from a djaradin. Perhaps a battle trophy?", fua = "Ближчий огляд показує, що ікло для цього амулета, схоже, належить джарадину. Можливо, бойовий трофей?" }
    t[213045] = { name = "Розірване Намисто Джарадинів", fen = "Little can be learned from this broken amulet, as half of its pieces have gone missing throughout the years.", fua = "З цього розбитого амулета мало що можна дізнатися, бо половина його частин загубилася за роки." }
    t[213089] = { name = "Античний Бронзовий Зливок", fen = "A peculiar alloy, forged in futures past. Of great interest to Iszinormi and her associates at The Parting Glass.", fua = "Незвичайний сплав, викуваний у минулих майбуттях. Становить велику цікавість для Ізінорми та її спільників у \"Прощальній Чарці\"." }
    t[213160] = "Калдорейський Місячний Лук"
    t[213175] = { name = "Запорошений Фоліант Джарадинів", fen = "A small archive of djaradin history.", fua = "Невеликий архів історії джарадинів." }
    t[213176] = { name = "Збережений Фоліант Островів", fen = "A large archive of history on the centaur and the niffen.", fua = "Великий архів історії кентаврів і ніффенів." }
    t[213177] = { name = "Бездоганний Фоліант", fen = "An enormous archive of Dragon Isles history!", fua = "Величезний архів історії Драконових Островів!" }
    t[213179] = { name = "Тріснутий Драконячий Зуб", fen = "The damage indicates this tooth was knocked out by a blow. Its owner must have had a disagreement with something.", fua = "Ушкодження вказують, що цей зуб вибили ударом. Його власник, вочевидь, мав із чимось незгоду." }
    t[213180] = { name = "Зім'ята Карта", fen = "Someone began plotting a battlefield on this parchment... only to scribble the whole thing out and throw it away", fua = "Хтось почав креслити на цьому пергаменті поле бою... тільки щоб усе закреслити й викинути." }
    t[213182] = { name = "Камінь від Тривоги", fen = "A clawed hand has rubbed quite a deep indent in this stone.", fua = "Кігтиста рука втерла в цей камінь доволі глибоку западину." }
    t[213183] = { name = "Саморобний Браслет з Намистин", fen = "The beads consist of scraps of wire and scavenged stones. The string has been repaired many times.", fua = "Намистини складено зі шматків дроту й підібраних камінців. Шнурок ремонтували безліч разів." }
    t[213184] = { name = "Камінь зі Жуйкою", fen = "Students never change. At least the gum is interesting, made from the sap of a local tree.", fua = "Студенти ніколи не змінюються. Принаймні жуйка цікава — зроблена із соку місцевого дерева." }
    t[213185] = { name = "Запорошений Фоліант Кентаврів", fen = "A small archive of centaur history.", fua = "Невеликий архів історії кентаврів." }
    t[213186] = { name = "Запорошений Фоліант Ніффенів", fen = "A small archive of niffen history.", fua = "Невеликий архів історії ніффенів." }
    t[213187] = { name = "Запорошений Фоліант Драконідів", fen = "A small archive of drakonid history.", fua = "Невеликий архів історії драконідів." }
    t[213188] = { name = "Запорошений Фоліант Драктирів", fen = "A small archive of dracthyr history.", fua = "Невеликий архів історії драктирів." }
    t[213189] = { name = "Збережений Фоліант Драконідів", fen = "A large archive of history on the drakonids and the dracthyr.", fua = "Великий архів історії драконідів і драктирів." }
    t[213190] = { name = "Збережений Фоліант Джарадинів", fen = "A large archive of history on the djaradin.", fua = "Великий архів історії джарадинів." }
    t[213192] = { name = "Закреслений Список Імен", fen = "Someone made sure that each name was rendered illegible before discarding the list.", fua = "Хтось подбав, щоб кожне ім'я стало нерозбірливим, перш ніж викинути список." }
    t[213194] = { name = "Скам'янілі Пайки", fen = "This clump of hardened foodstuffs could offer insight into what was eaten on this island.", fua = "Цей грудок затверділих харчів міг би пролити світло на те, що їли на цьому острові." }
    t[213195] = { name = "Обвуглений Малюнок", fen = "Most of this paper has been destroyed, but the parts you can make out depict horns and angry eyebrows.", fua = "Більшу частину паперу знищено, але на вцілілих частинах видно роги й сердиті брови." }
    t[213196] = { name = "Засушена Квітка", fen = "This bloom was dried and pressed, preserved between the pages of a now-lost book.", fua = "Цю квітку висушили й сплющили, зберігши між сторінками нині втраченої книги." }
    t[213200] = { name = "Книга Гороскопів", fen = "It's a marvel a book this flimsy has survived. The scribbles within suggest that someone took this nonsense very seriously.", fua = "Дивно, що така крихка книга вціліла. Нотатки в ній свідчать, що хтось сприймав ці дурниці дуже серйозно." }
    t[213201] = { name = "Викинуті Кістки Водоплавних Птахів", fen = "The dragonkin here were fond of ducks, but these bones suggest they were at times used for food.", fua = "Тутешні драконоїди полюбляли качок, але ці кістки вказують, що часом їх вживали в їжу." }
    t[213203] = { name = "Оксамитовий Нічний Ковпак", fen = "This fine hood must have belonged to someone important. It has two holes cut out for horns.", fua = "Цей вишуканий каптур, певно, належав комусь важливому. У ньому прорізано два отвори для рогів." }
    t[213204] = { name = "Медальйон, Оздоблений Рубінами", fen = "Inside, there is a sketch of a red drakonid guard with a handsome grin.", fua = "Усередині — замальовка червоного вартового-драконіда з привабливою усмішкою." }
    t[213205] = { name = "Божевільні Каракулі", fen = "These star charts go far afield of reality. Studying the stars isn't for the faint of heart.", fua = "Ці зоряні карти далеко відірвані від дійсності. Вивчення зірок не для слабких духом." }
    t[213206] = { name = "Обвуглений Лист", fen = "The legible bits suggest this was once an angry rebuttal from a fellow scholar.", fua = "Розбірливі частини вказують, що колись це була гнівна відповідь від колеги-книжника." }
    t[213208] = { name = "Горщик Маринованих Анчівок", fen = "Someone must have been saving these for a special occasion that never arose.", fua = "Хтось, певно, беріг їх для особливої нагоди, яка так і не настала." }
    t[213210] = { name = "Закривавлений Клапоть Прапора", fen = "This torn bit of banner fabric was used as a bandage at some point.", fua = "Цей подертий шматок прапорної тканини колись послужив за пов'язку." }
    t[213211] = { name = "Скам'янілі Пелюстки Квітів", fen = "These flower petals were picked off one-by-one and discarded into cooling magma.", fua = "Ці пелюстки квітів обривали одну за одною й кидали в магму, що остигала." }
    t[213212] = { name = "Ніж з Китового Вуса", fen = "These were carried by Tuskarr fisherman and are useful for cutting rope.", fua = "Такі носили рибалки-роарти, і вони зручні для різання канатів." }
    t[213213] = { name = "Сушений Печерний Гриб", fen = "Though dessicated, these resemble the fungi that are cultivated in Zaralek Cavern today.", fua = "Хоч і висохлі, вони нагадують гриби, які вирощують у Печері Заралек нині." }
    t[213214] = { name = "Плетений Кошик з Лавового Очерету", fen = "Made from heat-resistant grasses, the design resembles a Tuskarr woven crab trap.", fua = "Зроблений з жаростійких трав, своїм виглядом нагадує плетену пастку для крабів роартів." }
    t[213215] = { name = "Різьблений Вотивний Камінь", fen = "A face has been carved into this stone, to be offered to some unknown Djaradin diety.", fua = "У цьому камені вирізьблено обличчя, щоб піднести його якомусь невідомому божеству джарадинів." }
    t[213216] = { name = "Клапоть Карбованої Шкіри", fen = "This piece of hide has been marked dozens of times, though what it commemorates is unknown.", fua = "На цьому шматку шкіри зроблено десятки позначок, та що саме вони відзначають — невідомо." }
    t[213269] = "Лук Капітана Слідопитів"
    t[213274] = "Слідопроходець Архіваріуса"
    t[213275] = "Каменетяг Архіваріуса"
    t[213276] = "Збільшувальна Булава Архіваріуса"
    t[213277] = { name = "Розмазаний Уривок Поезії", fen = "The remains of what looks to be a poem detailing a great battle.", fua = "Рештки того, що схоже на вірш про велику битву." }
    t[213357] = { name = "Кришталева Чаша Ясновидіння", fen = "Peering into the bowl, it feels like you can almost make out an image. Or that's your reflection.", fua = "Вдивляючись у чашу, ви ніби майже розрізняєте якийсь образ. Або це ваше відображення." }
    t[213358] = { name = "Невправно Викопаний Череп", fen = "There may have been great wisdom to be gleaned from this rare find, but whoever found it first plunged a pickaxe straight into it!", fua = "З цієї рідкісної знахідки можна було б почерпнути велику мудрість, але той, хто знайшов її першим, увігнав у неї кайло!" }
    t[213359] = { name = "Тріснутий Посох Драконідів", fen = "Time has rendered this magical focus inert, but the engravings along the shaft tell an even deeper story.", fua = "Час зробив цей магічний осередок бездіяльним, та гравіювання вздовж держака розповідають іще глибшу історію." }
    t[213360] = { name = "Викинутий Амулет Драконідів", fen = "The gem this amulet once held has been pried free, reducing its value to nearly worthless.", fua = "Самоцвіт, що колись прикрашав цей амулет, виламано, через що його цінність впала майже до нуля." }
    t[213361] = { name = "Тривожна Дитяча Іграшка", fen = "Children have taken an alarming shine to unsettling figurines. Maybe it's better left a mystery.", fua = "Діти стали з тривогою захоплюватися моторошними фігурками. Можливо, цю загадку краще лишити нерозгаданою." }
    t[213362] = { name = "Прадавня Цукерка Драконідів", fen = "It may have retained its form, but surely this rock-hard drakonid treat is past its expiration date.", fua = "Вона, може, й зберегла форму, але цей твердий, мов камінь, ласощ драконідів напевно давно прострочений." }
    t[213363] = { name = "Скинута Шкірка з Очей", fen = "When reptiles shed their scales, many species shed the skin on their eyes as well. During this time, the creatures are often blind and defenseless.", fua = "Коли плазуни скидають луску, багато видів скидають і шкірку з очей. У цей час створіння часто сліпі й беззахисні." }
    t[213364] = { name = "Порожній Флакон Парфумів", fen = "A lovely aroma still lingers on the rim.", fua = "На вінцях досі тримається чарівний аромат." }
    t[213365] = { name = "Різьблений Печерний Кристал", fen = "Intricate shapes have been carved into this crystal, causing the light to shine in unique patterns.", fua = "У цей кристал вирізьблено складні візерунки, через що світло сяє в ньому неповторними узорами." }
    t[213366] = { name = "Клапоть Головного Убору Ніффена", fen = "Comparing the material and design of this niffen hat to ones commonly used today, one can extrapolate the evolution of niffen fashion.", fua = "Порівнюючи матеріал і крій цього капелюха ніффена з тими, що поширені нині, можна простежити еволюцію моди ніффенів." }
    t[213367] = { name = "Викинутий Прототип Кігтя", fen = "This appears to be a rudimentary attempt at upgrading niffen digging capabilities. The project seems to have been scrapped due to lack of necessity.", fua = "Схоже, це примітивна спроба покращити здатність ніффенів копати. Проєкт, вочевидь, згорнули через непотрібність." }
    t[213368] = { name = "Камінь \"Подряпай-і-Понюхай\"", fen = "Scratching this stone goes against all archaeological principles. Sure is tempting though.", fua = "Дряпати цей камінь суперечить усім принципам археології. Та все ж надто спокусливо." }
    t[213374] = { name = "Носова Затичка Ніффена", fen = "Niffen noses are so sensitive, sometimes they just need a way to shut out the day and get some sleep.", fua = "Носи ніффенів настільки чутливі, що часом їм просто потрібен спосіб відгородитися від дня й трохи поспати." }
    t[213375] = { name = "Торбина Закопаних Цінностей", fen = "On the rare occasion that a niffen forgets where they buried their shinies, these lost pouches act as effective time capsules.", fua = "У рідкісних випадках, коли ніффен забуває, де закопав свої блискітки, ці загублені торбини стають чудовими капсулами часу." }
    t[213377] = { name = "Понівечена Книга Казок", fen = "Massive niffen claws don't mix well with delicate books. At least they tried.", fua = "Величезні пазурі ніффенів погано поєднуються з тендітними книжками. Принаймні вони спробували." }
    t[213380] = { name = "Невпізнаваний Кінський Викопень", fen = "Does this go in the centaur pile or the horse pile?", fua = "Це йде до купи кентаврів чи до купи коней?" }
    t[213382] = { name = "Частина Мисливської Карти Кентаврів", fen = "One can learn a lot about the local centaur by the way they hunt. This map fragment demonstrates the surprising coordination of ancient hunting parties.", fua = "Багато про місцевих кентаврів можна дізнатися з того, як вони полюють. Цей уламок карти показує дивовижну злагодженість давніх мисливських загонів." }
    t[213384] = { name = "Лялька З Кінського Волосу", fen = "Passed down from generation to generation, each parent adding to the stitching.", fua = "Передається з покоління в покоління, і кожен з батьків додає свій стібок." }
    t[213385] = { name = "Жорстка Щітка", fen = "There is no greater sign of intimacy and trust between centaur than mutual grooming.", fua = "Немає більшого знаку близькості й довіри між кентаврами, ніж взаємне доглядання." }
    t[213386] = { name = "Викопаний Кам'яний Наконечник Стріли", fen = "The shape and size of the arrowhead reveals much of how centaur hunting has adapted over the years.", fua = "Форма й розмір наконечника стріли багато розповідають про те, як полювання кентаврів змінювалося з роками." }
    t[213387] = { name = "Примітивна Різьба Кентавра", fen = "A tradition dating back as far as records go, many centaur across the plains share a love of whittling.", fua = "Багато кентаврів рівнин поділяють любов до різьблення — традиції, що сягає глибше за будь-які записи." }
    t[213388] = { name = "Вицвілий Малюнок Кентавра", fen = "Being a nomad means you can't take your cave drawings with you. Inventive centaur of the past solved this problem with their own painting skins.", fua = "Кочове життя означає, що печерні малюнки не візьмеш із собою. Винахідливі кентаври минулого розв'язали цю проблему власними мальованими шкірами." }
    t[213389] = { name = "Стародавній Щоденник Кентавра", fen = "Seemingly written from the perspective of a child, this diary does much to showcase what life was like for early centaur.", fua = "Цей щоденник, написаний нібито з погляду дитини, чимало розповідає про те, яким було життя давніх кентаврів." }
    t[213429] = { name = "Додаток Прискіпливого Архіваріуса", fen = "Last minute notes detailing additional archaeological finds.", fua = "Поспіхом написані нотатки з подробицями про додаткові археологічні знахідки." }
    t[213438] = { name = "Нескінченний Броньодон", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[213439] = { name = "Лютий Сновидний Кіготь", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[213440] = { name = "Лютий Сновидний Кіготь", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[213530] = { name = "Ентропійний Кристал", fen = "Urgency seeps into your mind to set whatever is inside free.", fua = "У ваш розум просочується нагальна потреба звільнити те, що всередині." }
    t[213531] = "Піски Порожнечі"
    t[213532] = { name = "Руна Порожнечі", fen = "A sense of doom washes over you just by holding it.", fua = "Відчуття приреченості охоплює вас, щойно ви берете її в руки." }
    t[213536] = { name = "Безцінний Артефакт", fen = "A precious relic painstakingly pieced together by the archivists.", fua = "Дорогоцінна реліквія, кропітко зібрана архіваріусами." }
    t[213537] = "Щупальце Безодні"
    t[213540] = "Примарні Часточки"
    t[213541] = { name = "Щедра Скриня Дракончика", fen = "Contains 15 Whelpling's Dreaming Crests.", fua = "Містить 15 Сновидних Гербів Дракончика." }
    t[213561] = "Звивистий Зміїстий Дракон: Луска Порожнечі"
    t[213631] = { name = "Порожня Котушка Часових Ниток", fen = "Previously used to hold the fabric of time.", fua = "Колись тримала тканину часу." }
    t[214504] = { name = "Знайома На Вигляд Кінцівка", fen = "Slime-covered. Partially digested. Your Cooking skill is not high enough to use this item.", fua = "Укрита слизом. Частково перетравлена. Ваша майстерність кулінарії недостатня, щоб скористатися цим предметом." }
    t[215139] = "Copy Copy Elemental Lariat"
    t[215143] = "Copy Copy Elemental Lariat"
    t[215160] = { name = "Спорядження Великих Розкопок", fen = "The only crate sturdy enough to survive Doomshadow. Contains many rare artifacts and supplies.", fua = "Єдина скриня, достатньо міцна, щоб пережити Тінь Загибелі. Містить багато рідкісних артефактів і припасів." }
    t[215359] = { name = "Дуже Великий Пакунок Припасів Валдраккенської Угоди", fen = "Contains Dragon Isles Supplies you can use to trade for faction items or progressing skills with faction activities.", fua = "Містить Припаси Драконових Островів, які можна обміняти на предмети фракції або витратити на розвиток умінь у фракційних заняттях." }
    t[215362] = { name = "Сховок Бур", fen = "Contains a random piece of Veteran gear, gold, and equipment upgrade materials.", fua = "Містить випадковий предмет спорядження ветерана, золото та матеріали для покращення спорядження." }
    t[215363] = { name = "Сховок Жарин", fen = "Contains a random piece of Veteran gear, gold, and equipment upgrade materials.", fua = "Містить випадковий предмет спорядження ветерана, золото та матеріали для покращення спорядження." }
    t[215364] = { name = "Сховок Снів", fen = "Contains a random piece of Veteran gear, gold, and equipment upgrade materials.", fua = "Містить випадковий предмет спорядження ветерана, золото та матеріали для покращення спорядження." }
