    t[218269] = { name = "Драконячий Фоліант Пробудження", fen = "Recently found on the aged shelves of Algeth'ar Academy, this tome contains a variety of formulae for enchanting Awakened Crests.", fua = "Нещодавно знайдений на давніх полицях Академії Алґетара, цей фоліант містить безліч формул для зачарування пробуджених гербів." }
    t[219283] = { name = "Обсидіановий Ірис", fen = "Tough as the flight they're named for, these pitch black flowers thrive in rugged environments.", fua = "Витривалі, як зграя, на честь якої названі, ці чорні як смола квіти буяють у суворих краях." }
    t[219285] = { name = "Блакитна Лілія", fen = "The very petals of this bloom crackle with arcane energy. It is said their buds will not flower unless in the presence of large amounts of magic.", fua = "Самі пелюстки цього суцвіття потріскують таємною енергією. Кажуть, їхні бруньки не розквітнуть, окрім як у присутності великої кількості магії." }
    t[219287] = { name = "Стокротка, Торкнута Часом", fen = "Covered in a fine bronze dust, these daisies glisten and glitter in the midday sun.", fua = "Укриті тонким бронзовим пилом, ці стокротки виблискують і мерехтять у полуденному сонці." }
    t[219288] = { name = "Смарагдова Квітка", fen = "The petals of this flower are cool to the touch, as though they were just plucked from a deep, dark forest.", fua = "Пелюстки цієї квітки прохолодні на дотик, наче їх щойно зірвали в глибокому темному лісі." }
    t[219290] = { name = "Рубінова Квітка", fen = "Warm to the touch and thrumming with life, these flowers are absolutely covered in pollen. Great for bees, not noses.", fua = "Теплі на дотик і повні життя, ці квіти геть укриті пилком. Чудово для бджіл, та не для носів." }
