    t[220116] = { name = "Завершена Ринкова Ревізія", fen = "A complete stack of earthen paperwork featuring this week's bills of sales. All documents have been signed off by Loldren.", fua = "Повна стопка земельників паперів із цьоготижневими рахунками продажів. Усі документи підписав Лолдрен." }
