    t[225335] = { name = "Ключ Контрабандиста", fen = "Despite a few blood splatters, this key looks to be in good shape. It looks like it might go into a large lock.", fua = "Попри кілька плям крові, цей ключ виглядає цілком справним. Схоже, він підходить до великого замка." }
    t[225554] = { name = "Безсонячна Принада", fen = "You pulled this from the head of an Illusion projecting kobyss in the Sunless Strand. With enough examples, you may be able to give them a taste of their own medicine.", fua = "Ви висмикнули її з голови кобиса, що насилав ілюзії на Безсонячному Узбережжі. Зібравши досить зразків, ви, можливо, віддячите їм їхньою ж монетою." }
    t[225558] = { name = "Принада Мутноплавця", fen = "You took this from a kobyss trying to fool you in the Velhan's Claim. With enough parts, you may be able to turn the tables.", fua = "Ви забрали її в кобиса, який намагався обдурити вас у Володінні Велгана. Зібравши досить деталей, ви, можливо, оберете долю проти них." }
    t[225559] = { name = "Голодна Мерехтлива Луска", fen = "You took this shimmering scale from a kobyss trying to distract you with an illusion in the Hungering Pool.", fua = "Ви зняли цю мерехтливу луску з кобиса, який намагався відвернути вашу увагу ілюзією в Голодній Заводі." }
